return {
  [598342094585344] = "adivinhação",
  [813709740240384] = "Você está bem?",
  [813709740127232] = "Hum?",
  [1139094851799552] = "Acenar",
  [1139165182847488] = "Você é o Rei do Amarelo e do Preto que exerce boa sorte",
  [1139165182497280] = "Claro.",
  [1143492898194944] = "Sobre o Sr.",
  [1143492898203136] = "Adeus",
  [818107786657792] = "O que você vende aqui?",
  [818107786770944] = "Então como posso vê-la? Ela deve ser muito poderosa!",
  [818107786771200] = "Quanto a isso... ela só gosta de crianças boas, daquelas que comem cenoura direito!",
  [818107786948352] = "Você precisa de ajuda?",
  [818107786971648] = "Droga, como uma casa ancestral tão assombrada poderia ser vendida?",
  [818107786971904] = "O que é isso de casa ancestral mal-assombrada de que você está falando?",
  [818107786972160] = "É a casa da minha família que tem centenas de anos de história. Aquele lugar está muito degradado e pretendo vendê-lo por algum dinheiro para subsidiar minha família.",
  [818107786972416] = "Mas todas as noites há ruídos estranhos na casa – passos, suspiros e alguém andando de um lado para outro escada acima.",
  [818107786972672] = "Eu sou o único na casa, então quem está fazendo barulho deve ser...algo impuro!",
  [818107786972928] = "<P_Heart> (Algo impuro? Pode ser Beyonder poder, vá dar uma olhada com ele.) </>",
  [818107786973184] = "Talvez eu possa ajudar; por que você não me deixa tentar?",
  [818107786973440] = "Você... você pode expulsar essa coisa? Isso é ótimo! Vamos, siga-me rapidamente!",
  [818107786973696] = "William Heywood, o anfitrião deste baile, não parece um verdadeiro anfitrião. Seu rosto de trinta e poucos anos deveria ser heróico, mas há uma leve camada de fadiga entre suas sobrancelhas.",
  [818107786977024] = "Senhora, você parece muito ansiosa?",
  [818107786978048] = "Garota fedorenta, não me culpe por ser indelicado se você continuar incomodando!",
  [818107787018496] = "Deixe-me perguntar por você.",
  [818107787025408] = "Veja bem, isso não é apenas conversa fiada sobre o tempo—",
  [818107787029248] = "Eu fui amaldiçoado! Não consigo me levantar do chão, só um beijo de amor verdadeiro pode quebrá-lo!",
  [818107787078912] = "Sim, por que... por que eu fiz isso?",
  [818107786770688] = "Isso esgotou suas forças, forçando-a a cair em um sono profundo, mas mesmo agora ela está nos protegendo das sombras.",
  [1143563228620544] = "Mude para um cemitério público.",
  [818107786652160] = "Além da cervejaria artesanal, você também pode tentar construir diversos tipos de oficinas para atender às necessidades dos diversos pedidos.",
  [818107786770432] = "Ela nasceu durante a noite e com dois estalar de dedos esta cidade foi construída.",
  [818107786911232] = "O que você está falando?",
  [818107787014656] = "Este Sr./Sra. {{|}}, você conhece Godot?",
  [822505833406720] = "Sim, o Rei das Amarelas e das Pretas aponta para o Sr.",
  [1143563229175808] = "Continue lutando. No dia em que você realmente estiver na minha frente, eu lhe direi quem é o verdadeiro mestre deste corpo.",
  [1143563229175552] = "<P_Heart> (Zombaria) </> Heh, você cruzou outro limite. Mas... devo admitir, você está realmente um pouco mais forte do que quando nos encontramos pela última vez.",
  [1143563229175040] = "Aqui de novo? Ainda fazendo lutas fúteis? Mesmo que você entenda alguns princípios de atuação, não conseguirá se livrar de mim.",
  [1143563229174784] = "Senhor, continuemos ansiosos por um amanhã melhor para o castelo!",
  [1143563229174528] = "O castelo passou de um terreno baldio à atual prosperidade de ferrovias, oficinas movimentadas e mercados abertos – você criou tudo isso com suas próprias mãos e acredito que isso seja apenas o começo.",
  [1143563229174272] = "Acredito que sua oficina certamente produzirá mais produtos de alta qualidade e será um best-seller no mercado.",
  [818107787015168] = "Ele é um viajante, tão jovem quanto nós.",
  [1143563229174016] = "A volatilidade do mercado é tão fascinante; você o dominou completamente.",
  [818107786911744] = "Naquela época, a malt ale que Thomas preparava era tão perfumada que poderia atrair bêbados da cidade vizinha. As tortas de Eleanor também eram uma especialidade, a crosta era tão escamosa que se esfarelava com uma mordida.",
  [818107786974208] = "O Barão está olhando para aquele canto. O que há?",
  [1143563228692992] = "<P_Heart> (Uivo) </> Ah—Mary Ann—por que você não entende meu amor—ah—",
  [1143563228561920] = "Isto é... Seda Brilhante? Mesmo os designers mais famosos não conseguem revelar o seu verdadeiro valor. Seria melhor orar ao Sr. Louco por ajuda.",
  [818107786658304] = "Veja o artesanato desses produtos, uma estética verdadeiramente retrô e verdadeiramente aristocrática!",
  [1143563228299776] = "Não faz sentido dizer isso. Os vivos nem conseguem viver bem, como teriam a capacidade de cuidar dos mortos!",
  [818107786558464] = "A pontuação adicionada à coleção de poesia é como colocar braços em Vênus. Droga, de quem foi essa ideia?",
  [1143563229086208] = "Tudo isso fez esse idiota acreditar: Terry tinha uma linda esposa chamada Olivia.",
  [1143563228955136] = "Os que sobraram naquela época não estão todos podres?",
  [1143563228824064] = "A identidade de Susie permitiu-lhe evitar muitos problemas. Quando não sabemos o que fazer, Susie apenas diz: 'Não sei, afinal sou apenas um cachorro'.",
  [1143563228808704] = "Capitão Dunn, qual foi sua impressão de Klein quando o conheceu?",
  [1143563229173760] = "Obrigado por me ajudar a encontrá-la.",
  [1143563229173504] = "E também permitirá que ela finalmente saia em um lindo sonho sem dor.",
  [1143563229173248] = "Deixe-me transformar em energia e desaparecer; Eu completarei o poder que está faltando...",
  [1143563229172992] = "Eu não sou a verdadeira boneca Lumi, mas a dolorosa realidade da qual ela quer fugir.",
  [1143563229172736] = "São todas as suas memórias cruéis e reais, que sou... eu.",
  [1143563229172480] = "Um último pedaço de energia?",
  [1143563229172224] = "É necessária uma última dose de energia.",
  [1143563229171968] = "Recuperar os fragmentos a deixará sóbria, mas destruir o poder extraordinário e deixar você escapar...",
  [1143563229171712] = "Eu entendo, foi aquela caixa de música extraordinária que transformou suas memórias e obsessões em um castelo.",
  [1143563229171456] = "Você sobe primeiro, também posso usar o diário para subir!",
  [1143563229171200] = "Podemos pular mais alto agora!",
  [1143563229170944] = "Nessas páginas dispersas do diário, o poder da memória ainda está escondido!",
  [1143563229170688] = "Vamos mudar de consciência rapidamente!",
  [1143563229170432] = "Eu cheguei!",
  [1143563229170176] = "Estou pronto!",
  [1143563229169920] = "Talvez eu possa usar aquela Carruagem de Canhão para me enviar para lá.",
  [1143563229169664] = "Mas você não pode chegar lá.",
  [1143563229169408] = "Ali... ouvi o primeiro segmento de memória.",
  [1143563229169152] = "Tem alguém ali, vamos perguntar a eles.",
  [1143563229168896] = "A Sra. “Justiça” me escreveu, dizendo que talvez eu precise de um lugar para ficar... <P_Heart> （Olhando ao redor） </> Mas onde é isso?",
  [1143563229168640] = "“Pegue um trem na estação ferroviária de Tingen e você chegará em breve…” Hmm, este é o lugar.",
  [1143563229168384] = "Suspiro, seja Loen ou Intis, eles são muito inferiores à minha cidade natal.",
  [1143563229167872] = "Não há internet aqui, nem ar condicionado, nem telefones celulares, nem videogames. O desejo de jogar em uma sala com ar condicionado só pode ser atribuído às habilidades dos antigos estudiosos. Você entende?",
  [1143563229167616] = "A máquina a vapor ruge há tantos anos. Sem petróleo, as carruagens daqui nunca alcançarão a velocidade das Grandes Antigas.",
  [1143563229167360] = "Satisfatório? Só posso dizer que é mais do meu agrado. Meus esforços foram apenas para torná-lo mais próximo da vida em minhas memórias.",
  [1143563229167104] = "Intis, governado por você, deve ser o seu trabalho mais gratificante.",
  [1143563229166848] = "Tsk, eu também não aprecio muito os nobres Intis. Uh, eu não aprecio alguns de seus estilos de fazer as coisas. Alguns estão bem.",
  [1143563229166592] = "Parece que você não aprecia o estilo dos nobres de Loen?",
  [1143563229166336] = "O povo Loen é mais conservador e sombrio do que o povo Intis. Suspeito que a chuva contínua tenha impacto na saúde mental do povo de Loen. Porém, esses políticos e nobres, talvez seus corações estejam...",
  [1143563229166080] = "Para ser honesto, na minha época, a tecnologia de Loen ainda perseguia a sombra da Intis – claro, isso se devia à minha governança.",
  [1143563229165824] = "Desculpe! Só estou curioso para saber a sua opinião...",
  [1143563229165568] = "Eu não sou o Imperador de Intis. Depois de ficar tanto tempo na ilha, você ainda precisa me fazer perguntas tão provocativas?",
  [1143563229165312] = "Imperador Roselle, como você vê Loen e Intis hoje?",
  [1143563229165056] = "Haha, embora seja difícil criar algo do nada, ouvir tais elogios ainda é muito satisfatório.",
  [1143563229164800] = "Suas invenções aumentaram enormemente a civilização e a conveniência da sociedade.",
  [1143563229164544] = "Eu me amaldiçoei por um longo tempo naquela época, me perguntando por que escolhi um Caminho tão fraco. No entanto, o desenvolvimento da árvore tecnológica realmente não poderia prescindir dela.",
  [1143563229164288] = "O preço também era bastante alto; as primeiras sequências foram completamente incapazes de lutar, e até Sequência 6, todos eram do tipo estudioso.",
  [1143563229164032] = "Depois de beber, lembrei-me de todo o conhecimento que havia perdido, tão claramente como se tivesse acabado de ler os livros.",
  [1143563229163776] = "Claro, meu Sequência 'Savant' inicial também deu muita ajuda - era uma poção feita sob medida para um transmigrador.",
  [1143563229163520] = "De acordo com registros históricos, de fato... era indescritível.",
  [1143563229163264] = "Você consegue imaginar como era o Intis sem sistema de saneamento naquela época?! Era simplesmente insuportável de olhar! Havia excrementos nojentos por toda parte!",
  [1143563229163008] = "Eu queria agir discretamente, heh — esqueça, isso é o que todo transmigrador quer fazer, certo? Além disso, a infraestrutura aqui é muito atrasada.",
  [1143563229162752] = "Imperador Roselle, você fez muitas contribuições para o desenvolvimento deste mundo.",
  [1143563229162496] = "...... Neste ponto, lamento ter chegado muito perto da Igreja do Vapor.",
  [1143563229162240] = "Prefiro que meu filho tenha mais humanidade do que um crente devoto.",
  [1143563229161984] = "Perguntei a ele quais conquistas Bonova teria no futuro, e ele apenas sorriu e não disse nada! Maldito Vidente! Ele sabia disso o tempo todo!",
  [1143563229161472] = "Aquele desgraçado do Zarathul, quando o Bonova acabou de nascer, veio parabenizar e disse que o Bonova era um ‘anjo fofo’.",
  [1143563229161216] = "A Igreja levou Benoit, meu filho mais novo. Nosso relacionamento como pai e filho pode não ser tão próximo, mas afinal ele é meu filho.",
  [48586280666624] = "Deixar",
  [1143563229160960] = "E agora, Vossa Majestade?",
  [1143563229160704] = "Quando meu estado ainda estava instável depois de tomar a poção, ouvi muitos elogios e canções. Essas vozes eram como âncoras, ajudando-me a me estabilizar.",
  [1143563229160448] = "Para ser sincero, também gostei desse nome no início. De fato me ajudou.",
  [1143563229160192] = "Acham que este título é uma honra para mim: o revolucionário escolhido por Deus. Jornalistas, clérigos, todo mundo gosta de usar esse título.",
  [1143563229159936] = "Eu sei o que você está pensando: Deus do Vapor e das Máquinas, certo?",
  [1143563229159680] = "Imperador Roselle, descobri que você é chamado de “Filho do Vapor”...",
  [1143563229159424] = "Eu, eu?",
  [1143563229159168] = "Embora ela já seja uma figura importante no mundo místico, ainda não consigo deixar de me preocupar. Como somos da mesma cidade natal, lembre-se de cuidar dela quando crescer.",
  [1143563229158912] = "<P_Heart> (Abre as mãos) </> Então, somos da mesma geração. Ela também deveria chamar você de tio/tia {{|}}.",
  [1143563229158656] = "Aliás, você é como nós, vindo do mesmo lugar.",
  [1143563229158400] = "<P_Heart> (Tosse levemente) </> Podemos não mencionar o diário...",
  [1143563229158144] = "Encontrei Bernadette algumas vezes e ela realmente me deixou uma impressão profunda. Seu diário também registrou coisas sobre você e seus filhos...",
  [1143563229157888] = "(O tom é estranho) No entanto, sendo capaz de empurrar essas coisas para Ele, até certo ponto, também sou grato a Ele.",
  [1143563229157632] = "Minha filha, ela tem o caráter mais correto e gentil. Isso tornou difícil para ela aceitar as coisas que fiz nos meus últimos anos. Claro, isso também é culpa da “Lua Primordial” – você entende a sensação de estar corrompido, certo?",
  [1143563229157376] = "Desde jovem ela soube ser filial com o velho pai, cuidar do irmão mais novo e amar a mãe. Às vezes, ela também é particularmente ereta, parecendo um pouco boba, suspiro.",
  [1143563229157120] = "Isso mesmo, eu sou o pobre e velho pai dela. Você a conheceu? Ela não é uma criança muito boa?",
  [1143563229156864] = "Imperador Roselle, você e a 'Rainha Mística' Bernadette são mãe e filha?",
  [1143563229156608] = "Você também tem essa sensação, certo?",
  [1143563229156352] = "Solidão, você diz...",
  [1143563229156096] = "E ele... ele é uma pessoa solitária. Posso sentir a solidão que permeia seus ossos.",
  [1143563229155840] = "Embora eu tenha começado a pensar na minha cidade natal mais tarde, pelo menos eu tinha esposa, uma filha e dois filhos. Eu também tinha muitos apegos e um sentimento de pertencimento aqui.",
  [1143563229155584] = "No entanto, posso dizer que ele é muito diferente de mim. Quando cheguei aqui, tratei este lugar como um jogo e joguei com muita alegria e alegria.",
  [1143563229155328] = "Mas se é recente, devem ser os vários vestígios históricos que deixei, a 'Carta da Blasfémia' e Bernadette, que nos permitiram finalmente encontrar-nos.",
  [1143563229155072] = "Devo dizer que é um prazer conhecê-lo...",
  [1143563229154816] = "Bem, nossas origens remontam a milhares de anos. Pensando bem, você também era nosso colega de quarto naquela época.",
  [1143563229154560] = "Imperador Roselle, como você e o Sr. “Tolo” se conheceram?",
  [1143563229154304] = "Não me sinto mais perdido e incompleto; isso é mais gratificante do que a plenitude da alma.",
  [1143563229154048] = "Pelo menos ainda tenho muitos sonhos lindos quando durmo e, depois que acordo, posso ver as cartas que me foram enviadas, contando o que aconteceu.",
  [1143563229153792] = "Não há necessidade de mostrar uma expressão triste; comparado a outras coisas, isso não é ruim.",
  [1143563229153280] = "<P_Heart> (Sussurros) </> Pelo menos, sem o fardo embutido em minha alma, ficará mais quieto quando eu adormecer.",
  [1143563229153024] = "<P_Heart> (Suspiros) </> Não quero voltar a esse estado. Então, eu escolhi ser assim agora. Mesmo que eu tenha que repetir a ressurreição e a amnésia, pelo menos mantenho meu passado e minha humanidade.",
  [1143563229152768] = "Se eu prosseguir ainda mais com a plenitude, me tornarei seu receptáculo, o que não estou disposto a fazer; e se eu extrair a alma e costurá-la sozinho, isso fará com que eu me torne aquele “eu” frio novamente.",
  [1143563229152512] = "Pelo que eu sei, a seita Morte Artificial já sofreu pesadas perdas. Você encontrou sua alma de volta?",
  [1143563229152256] = "E a metade restante da minha alma foi combinada com um Artefato Selado por ele durante a divisão. Comecei a passar pela ressurreição, assim como um 'Imortal'.",
  [1143563229152000] = "Essas duas metades da alma, uma metade fundida com a Unicidade da 'Morte' Caminho e tinham uma tendência a se tornarem ativas, o que foi utilizado pela seita Morte Artificial.",
  [1143563229151744] = "O Imperador do Submundo, isto é, o Salinger da 'Morte'. Ele previu sua própria queda, então dividiu minha alma – seu descendente de sangue – em duas metades.",
  [1143563229151488] = "Uma maldição! Quem fez isso com você?",
  [1143563229151232] = "No estágio ‘Imortal’, existem de fato situações semelhantes à minha. <P_Heart> (Suspiros) </> No entanto, meu estado não é um presente, mas uma maldição.",
  [1143563229150976] = "Sr. Azik, sua habilidade de imortalidade é do poder Sequência 4 'Imortal' Beyonder?",
  [1143563229150720] = "Afinal, para o departamento de história não são comuns entrevistas com quem viveu isso em primeira mão... Haha, brincadeira.",
  [1143563229150464] = "<P_Heart> (Sorrisos) </> As memórias que me lembro podem ser de alguma ajuda para a pesquisa no departamento de história.",
  [1143563229150208] = "É uma pena que depois de deixar Tingen em busca de lembranças, raramente mantivemos contato. Mas muitas vezes sinto falta da época em que era professor.",
  [1143563229149952] = "Você deve ter apreciado muito esse momento...",
  [1143563229149696] = "Ele exigiria que nos aprofundássemos e encontrássemos evidências para os nossos pontos de vista. Quando estávamos discutindo intensamente, ele sorria e dizia o quanto estava satisfeito com a discussão.",
  [1143563229149440] = "Muitas vezes pensei que tudo tinha acabado, mas alguns dias depois Cohen me encontraria novamente.",
  [1143563229149184] = "Meu amigo Cohen era uma pessoa que valorizava o talento e se concentrava nos estudos. Nossos pontos de vista muitas vezes conflitavam, levando a inúmeros pequenos debates.",
  [1143563229148928] = "Na verdade, deixando de lado a intimidade e a satisfação trazidas pela pesquisa, todos os alunos e colegas do departamento de história tinham um temperamento único. Conversar com eles foi uma coisa agradável.",
  [1143563229148672] = "Tingen é uma cidade de universidades e a Hoy University é a melhor entre elas. Sua vida no departamento de história deve ter sido muito agradável.",
  [1143563229148416] = "Julguei esse impulso como um hobby e um interesse profissional e, eventualmente, embarquei nesse caminho.",
  [1143563229148160] = "Quando escolhi estudar história pela primeira vez, ainda não tinha percebido a minha Unicidade . Houve apenas um vago impulso de explorar o passado.",
  [1143563229147904] = "“Um Estudo de Materiais Históricos Privados do Condado de Sivellas, Autor: Azik Eggers”… Incrível!",
  [1143563229147648] = "Este é meu antigo escritório. Na estante você ainda pode ver meus livros antigos.",
  [1143563229147392] = "Sr. Azik, você já foi professor de história na Universidade Khoy?",
  [1143563229147136] = "No mínimo, ele definitivamente não é você de hoje.",
  [1143563229146880] = "E eu, que facilitei tudo isso, era alto e poderoso, arrogante e frio. Às vezes me pergunto: o eu da era imperial era realmente eu?",
  [1143563229146624] = "Nas memórias do administrador, vi pessoas inocentes caírem e virarem cadáveres para serem conduzidos. Pelo bem do império, suas vidas foram tiradas tão levemente quanto penas.",
  [1143563229146368] = "Minhas experiências me deixaram sem sentimento de pertencimento a uma pátria, mas isso não é um arrependimento. Afinal, comparada a um conceito, minha vida teve muito mais pessoas concretas.",
  [1143563229146112] = "Não, não me sinto triste com isso. Essas lembranças são muito distantes, e naquela época minha humanidade era indiferente, então não tive uma percepção real de tudo isso.",
  [1143563229145856] = "Sinto muito... mencionei um assunto doloroso para você.",
  [1143563229145600] = "Após a queda da Morte, ondas de resistência surgiram por toda parte e o império entrou em colapso. O Balam Oriental e Ocidental de hoje não pode realmente ser considerado a minha pátria.",
  [1143563229145344] = "Contudo, não sou um “Balam” do presente; o país ao qual eu pertencia era o Império Balam.",
  [1143563229145088] = "Haha, por um tempo, me considerei apenas um estudioso comum do Continente Norte, até recuperar minhas memórias.",
  [1143563229144832] = "Sr. Azik, você é Balam?",
  [1143563229144576] = "Sim... Nos meus sonhos, muitas vezes me lembro deles.",
  [1143563229144320] = "Ele deve deixar você orgulhoso.",
  [1143563229144064] = "Quando ele ainda era pequeno, ele arrastava uma espada larga por aí, praticando diligentemente suas habilidades, querendo se tornar um cavaleiro.",
  [1143563229143808] = "Meu filho mais velho também herdou isso. Em muitas outras coisas, ele também era semelhante a mim. Alguns foram herdados e outros por admiração por seu pai.",
  [1143563229143552] = "Estou disposto a reconhecer os benefícios que o calor traz, mas não gosto dos chamados banhos de sol. Veja meu tom de pele; bronzeia com muita facilidade.",
  [1143563229143296] = "Você prefere o sol?",
  [1143563229143040] = "Assim, mais tarde fomos para o sul, onde o tempo estava muito agradável e o sol à beira-mar permitiu-nos recomeçar um momento maravilhoso.",
  [1143563229142784] = "O antigo castelo... foi onde morei. Minha esposa costumava reclamar comigo que o castelo era muito frio e sombrio; ela preferia o sol e o calor.",
  [1143563229142528] = "Sim, você pode ver muitas indústrias na cidade que dependem do turismo. São muitos os turistas que adoram a paisagem natural de Lamud e a história do antigo castelo.",
  [1143563229142272] = "Há alguns anos, um amigo também voltou para lá comigo. Acho que Lamud não deveria ter mudado muito?",
  [1143563229142016] = "Sou eu. <P_Heart> (Rindo) </> Foi uma época maravilhosa... de certa forma, foi meu renascimento depois de deixar o Império Balam.",
  [1143563229141760] = "Seu retrato? É você, Barão Lamud?",
  [1143563229141504] = "Parece que a pequena cidade deixou muitos retratos meus...",
  [1143563229141248] = "Sr. Eu vi um retrato no antigo castelo que se parece com você, não, é exatamente igual!",
  [1143563229140992] = "Claro, não coloque muita pressão sobre si mesmo por causa desta profecia; a progressão do destino muitas vezes acontece nos momentos que você menos espera.",
  [1143563229140736] = "<P_Heart> (Gentilmente) </> Acho que você não deveria subestimar as bênçãos de um deus. Ele escolheu você por um motivo.",
  [1143563229140480] = "Posso realmente fazer isso...",
  [1143563229140224] = "E no final, se você realmente alcançar essa altura, então aquele com quem você será capaz de lutar lado a lado será ele.",
  [1143563229139968] = "<P_Heart> (Sorri) </> Não sinta muita pressão; você ainda é um recém-chegado ao Mundo Extraordinário. Antes de você crescer, não permitiremos que você enfrente essas existências terríveis.",
  [1143563229139712] = "Resistindo ao apocalipse, eu...",
  [1143563229139456] = "Você carrega a esperança de resistir ao apocalipse.",
  [1143563229139200] = "O Sr. “Tolo” é um Deus misericordioso. Sem a ajuda dele, eu não teria sido capaz de escapar do destino de ser corrompido por um deus maligno......",
  [1143563229138944] = "De fato. Mas para mim, foi somente com a ajuda dele que pude descobrir a verdade e escapar do destino de perder minha humanidade.",
  [1143563229138688] = "Durante tanto tempo, você deve ter experimentado muitas coisas extraordinárias com o Sr.",
  [1143563229138432] = "Já que ele abriu a névoa da história para você, você também deverá ser capaz de ver nosso passado, começando daqui – do Departamento de História da Universidade Hoy.",
  [1143563229138176] = "Senhor Azik, as escrituras dizem que você é o Anjo que acompanha o Louco há mais tempo...",
  [1143563229137920] = "No entanto, a capacidade de exibição do Anel de Testemunhas é limitada, e os nomes que atendem aos critérios a cada semana aparecerão alternadamente aqui.",
  [1143563229137664] = "Os nomes gravados no Anel da Testemunha não são constantes – toda segunda-feira, a história muda e a glória surge junto com novos nomes.",
  [1143563229137408] = "E aqueles que mantêm o castelo em perfeita ordem, ou mesmo aqueles que acumularam riquezas nas ferrovias que se cruzam para se tornarem magnatas – qualquer um destes pode deixar o seu nome aqui.",
  [1143563229137152] = "Os favorecidos pelos deuses, os que testemunharam o aparecimento da graça divina, os versados ​​no modo de réquiem para os outros, ou os apaixonados pelos bailes da noite de primavera, os que cultivaram a sua ordem com perfeição...",
  [1143563229136896] = "Aqueles que podem deixar seus nomes aqui podem ser aqueles que avançaram nas chamas da liga, ou aqueles que se cultivaram ao extremo – é claro, todos os caminhos levam ao Mundo Místico, e os métodos não são únicos…",
  [1143563229136640] = "A radiação circundante é como uma galáxia que flui lentamente. Gravará nele os nomes mais deslumbrantes. Portanto, as pessoas o chamam de “Anel da Testemunha”.",
  [1143563229136384] = "E obrigado... por não me abandonar.",
  [1143563229136128] = "Obrigado por não abandoná-la.",
  [1143563229135616] = "E ela me salvou também.",
  [1143563229135360] = "Ela salvou você.",
  [1143563229135104] = "Lembro-me de tudo o que aconteceu agora há pouco.",
  [1143563229134848] = "Desculpe.",
  [1143563229134592] = "Você está acordado...",
  [1143563229134336] = "Rápido! Vamos! Ao longo do diário!",
  [1143563229134080] = "Mas também podemos percorrer o diário e obter o fragmento antes que ele o faça!",
  [1143563229133824] = "Ah não, esse diário é o coração dela que não quer enfrentar tudo isso. Quer aproximar-se do fragmento e esconder a memória.",
  [1143563229133568] = "Um diário? Por que isso apareceria aqui? Deixe-me sentir sua intenção...",
  [1143563229133312] = "O último fragmento de memória está lá em cima!",
  [1143563229133056] = "Mas a entrada está bloqueada por estes pilares; devemos destruí-los!",
  [1143563229132800] = "Parece que posso entrar pela abertura aqui...",
  [1143563229132544] = "Esse fragmento de memória está trancado dentro da cerca!",
  [1143563229132288] = "Em seguida, leve-me à impressão da memória e despertarei esses brinquedos e mecanismos há muito adormecidos.",
  [1143563229132032] = "Olha, esse é o selo que exige ressonância! Cada momento de companheirismo feliz deixa um eco emocional, e eu sou o melhor em ouvi-los!",
  [1143563229131776] = "Nós conseguimos! Eu posso voltar para o lado dela!",
  [1143563229131520] = "Espere! O que é esse som? Alguém está pedindo ajuda adiante!",
  [1143563229131264] = "Pronto... posso ver o céu. Essa poderia ser a saída?",
  [1143563229131008] = "Oh não, estou preso neste castelo por aquela garota? Devo encontrar uma maneira de sair!",
  [1143563229130752] = "Esse é o lugar mais quente e maravilhoso; você definitivamente não vai querer ir embora...",
  [1143563229130496] = "Venha, pegue minha mão e eu o levarei ao meu castelo.",
  [1143563229130240] = "Ótimo, vamos brincar juntos!",
  [1143563229129984] = "Alguém finalmente chegou? Estou esperando há muito tempo.",
  [1143563229129728] = "Durante esses quatorze dias, você ajudou um corvo a coletar fragmentos de memória. Então, estritamente falando, devo agradecer pessoalmente em nome do corvo.",
  [1143563229129472] = "Não se preocupe, é apenas uma foto. É uma lembrança para mim e também um presente de gratidão que o corvo quis lhe dar.",
  [1143563229129216] = "O que há para ter medo? Eu não faria nenhuma pegadinha, pelo menos não agora.",
  [1143563229128960] = "Tão simples? Você não tem medo que eu tire fotos de algo que não deveria?",
  [1143563229128704] = "Considere-me o fotógrafo especial de hoje. Ouvi dizer que nos primeiros treze dias outras pessoas tiraram fotos para você; no último dia, que tal uma perspectiva diferente?",
  [1143563229128448] = "Olá, convidado especial.",
  [1143563229128192] = "Você tirou treze fotos e ajudou um corvo a coletar treze tipos de memórias. Você já se perguntou... quem permitiu que aquele corvo vivesse até o décimo quarto dia?",
  [1143563229125120] = "Adeus, espero que você tenha a mesma sorte da próxima vez.",
  [1143563229124864] = "Mas você sabe? A parte mais interessante é nunca ver a verdade. É observar as pessoas procurando desesperadamente por respostas, suspeitando dos outros, suspeitando de si mesmas e depois, passo a passo, trilhando o caminho errado.",
  [1143563229124608] = "Você até me viu.",
  [1143563229124352] = "Você também descobriu a verdade sobre a sala trancada.",
  [1143563229124096] = "Você encontrou o assassino.",
  [1143563229123840] = "Brilhante, você realmente se esforçou muito para deduzir isso.",
  [1143563229123584] = "Do começo ao fim, <P_Yellow> só você </> esteve aqui, curtindo essa farsa.",
  [1143563229123328] = "Esse Beyonder item atraiu uma certa existência especial, que fez o Barão Hawkes notar a anormalidade, levando à morte do Barão Hawkes.",
  [1143563229123072] = "Alguém desencadeou a anormalidade mental do Barão, distorceu a vontade do médico, fez do leal mordomo o assassino neste caso e usou a voz do Barão para falsificar a hora da morte, deixando todos desconfiados.",
  [1143563229122816] = "Para ser mais preciso, você é o assassino, mas o verdadeiro culpado que causou todas essas contradições é outra pessoa!",
  [1143563229122304] = "Você esteve concentrado no assassino o tempo todo, mas não me viu.",
  [1143563229122048] = "Que pena.",
  [1143563229121792] = "Muito bom. Você conseguiu perceber que a sala trancada era falsa, a cena havia sido alterada e deduziu o método de incriminar o criado. Você é muito melhor do que aqueles caras que apenas olham para as evidências superficiais.",
  [1143563229121536] = "Dói, minha cabeça dói tanto... uh, quem sou eu... eu sou...",
  [1143563229121280] = "Como eu poderia matá-lo? Meu querido mestre, como eu poderia... não, isso não está certo...",
  [1143563229121024] = "Eu estava aqui quando ele nasceu. A primeira vez que ele andou a cavalo, a primeira vez que caçou... Lembro-me de tudo.",
  [1143563229120512] = "Por que? Você era o mordomo que o acompanhava desde a infância; por que você mataria o Barão Hawkes?",
  [1143563229120256] = "Ajustei a dosagem do remédio; contanto que a dosagem estivesse errada, seu coração pararia a qualquer momento. Também fui eu quem tranquei a porta do quarto e configurei o quarto como um mistério trancado.",
  [1143563229119744] = "Você envenenou o Barão Hawkes enquanto entregava seu remédio, fingiu a ilusão de que ele ainda estava vivo e até forjou a cena do crime para incriminar o servo.",
  [1143563229119488] = "Mas estou preso sob as pedras há muito tempo e estou muito fraco. Por favor me ajude e aja junto comigo!",
  [1143563229119232] = "Você pode explorar o espaço e recuperar os fragmentos através da minha consciência.",
  [1143563229118976] = "Estou familiarizado com este espaço e ainda posso ouvir esses fragmentos e ressoar com eles.",
  [1143563229118720] = "Se não encontrarmos esses fragmentos e restaurarmos suas memórias, ninguém poderá sair deste lugar...",
  [1143563229118464] = "Suas memórias e emoções estão despedaçadas, espalhadas entre esses fragmentos.",
  [1143563229118208] = "Ela não fez isso de propósito; ela simplesmente não é muito lúcida.",
  [1143563229117952] = "Também sei que este é um espaço composto de memórias e que estamos todos presos aqui agora.",
  [1143563229117696] = "Obrigada... Não sei por que estou aqui, mas lembro que meu nome é Lumi.",
  [1143563229117440] = "Já se passaram três anos, está parado há três anos... consertar pode não ser difícil.",
  [1143563229117184] = "Todos na cidade dizem que os relógios que você conserta funcionam com mais precisão do que os novos. Se você acha que este relógio de bolso não é bom o suficiente, conserte-o.",
  [1143563229116928] = "...... eu quero fazer melhor.",
  [1143563229116672] = "O que você quer jogar fora é aquela versão sua que foi rejeitada pelos juízes.",
  [1143563229116416] = "Eu... eu sou sonâmbulo? Eu chamo isso de lixo durante o dia e recupero à noite?!",
  [1143563229116160] = "Como eu saberia! Achei que essa coisa estava me assombrando! Achei que era um espírito persistente!",
  [1143563229115904] = "Você não sabia?",
  [1143563229115648] = "O que? Eu mesmo recuperei?!",
  [1143563229115392] = "Foi você quem andou sonâmbulo à noite e recuperou este relógio de bolso.",
  [1143563229115136] = "Está de volta!",
  [1143563229114880] = "Isto...",
  [1143563229114624] = "Sr./Sra. {{|}}, como está o relógio de bolso?",
  [1143563229114368] = "......Por questões de segurança, não podemos acordá-lo; devemos mandá-lo de volta primeiro.",
  [1143563229114112] = "Eu... agradeço meu relógio, mas ele não é reconhecido...",
  [1143563229113856] = "Um relojoeiro rural, trabalhando em relógios durante toda a vida, ainda não consegue fazer nada decente.",
  [1143563229113600] = "......Você não entende, você nunca quer entender.",
  [1143563229113344] = "Ele está com os olhos fechados?! Seus movimentos são lentos... ele está sonâmbulo?",
  [1143563229112832] = "Sr. Morgan?!",
  [1143563229112576] = "Você não pode jogar fora; talvez haja uma razão. Vou devolver o relógio de bolso ao seu lugar original e observá-lo esta noite para ver por que ele continua voltando.",
  [1143563229112320] = "Ontem à noite, joguei-o no velho castelo, pensando que finalmente tinha me livrado dele... mas...",
  [1143563229112064] = "Joguei o relógio na lata de lixo e no dia seguinte ele estava de volta na mesa. Enterrei na terra, joguei numa árvore, levei para a próxima cidade e ele sempre voltava!",
  [1143563229111808] = "Este relógio de bolso, cada equipamento foi polido por minhas próprias mãos. Há três anos, levei-o para uma competição em Backlund e os jurados disseram que o estilo era muito antigo e não tinha valor de mercado.",
  [1143563229111552] = "Minha família é relojoeira há gerações. Todos na cidade vêm até mim quando seus relógios quebram.",
  [1143563229111296] = "Você realmente não é desta cidade... Hmm, este é o meu relógio.",
  [1143563229111040] = "E se eu pudesse ajudá-lo a tirar o relógio de bolso da cidade?",
  [1143563229110784] = "Pare de me incomodar.",
  [1143563229110528] = "Sr. Morgan, todo mundo diz que este é o seu relógio.",
  [1143563229110272] = "Mas uma vez ele foi a Backlund e voltou outra pessoa... ele joga esse relógio de bolso em todos os lugares, mas ele sempre volta para sua mão...",
  [1143563229110016] = "Morgan é o melhor relojoeiro da cidade. Todo mundo vai até ele quando seus relógios quebram. Os relógios que ele conserta funcionam com mais precisão do que os novos.",
  [1143563229109504] = "É o relógio de bolso do Morgan! Está de volta?",
  [1143563229109248] = "Olá, este relógio de bolso...",
  [1143563229108992] = "Leve embora... não é meu. Você pode jogar fora, só não me deixe ver.",
  [1143563229108736] = "Está de volta?!",
  [1143563229108480] = "Senhor, este é o relógio que você perdeu?",
  [1143563229108224] = "Flo tem conflitos com a família, Frill odeia astrologia e não pode sair. Poderia ser ele? Mas por que?",
  [1143563229107968] = "As páginas arrancadas parecem muito novas. Alguém os falsificou e colou?",
  [1143563229107712] = "<P_Heart> (...Vou perguntar ao peixeiro.) </>",
  [1143563229107456] = "Contanto que o problema seja resolvido, irei agora. Vocês dois tenham uma boa conversa.",
  [1143563229107200] = "Como você pode dizer isso ao seu irmão? Estou com o coração partido.",
  [1143563229106944] = "Simplesmente porque você é uma idiota descuidada, Flo.",
  [1143563229106688] = "Achei que você odiava - espere, então que tal esbarrar no canto da mesa e ver a minhoca na maçã?",
  [1143563229106432] = "<P_Heart> (Sussurrando) </> conversou comigo corretamente.",
  [1143563229106176] = "Todo mundo entende, mas você só sabe olhar livros de astrologia o dia todo, e já faz muito tempo que você...",
  [1143563229105920] = "Só tenho mais experiência. A astrologia muitas vezes precisa ser combinada com a realidade para ser interpretada com mais precisão.",
  [1143563229105664] = "Uau, você é um verdadeiro mestre em astrologia!",
  [1143563229105408] = "Você memorizou todas as interpretações astrológicas? E você pode resolver meu destino com apenas alguns olhares?",
  [1143563229105152] = "Quando abri as páginas do livro e descobri que os padrões correspondiam às interpretações astrológicas conhecidas, adivinhei aproximadamente.",
  [1143563229104896] = "Com base no mapa astral que você descreveu, julgo que seu relacionamento com sua família não tem sido muito bom ultimamente.",
  [1143563229104384] = "Sua astrologia favorita não te contou? Essa pessoa viu de relance!",
  [1143563229104128] = "Suspiro, seu leitor ávido, mudei o conteúdo do livro!",
  [1143563229103872] = "O livro? Como as coisas do livro poderiam estar erradas?",
  [1143563229103616] = "Você nunca suspeitou que havia algo errado com o livro?",
  [1143563229103360] = "Huh? As estrelas são iguais às que desenhei?!",
  [1143563229103104] = "Você mesmo tem que contar a ele. Vamos juntos.",
  [1143563229102848] = "Olhar para mim ao lado dele com os olhos, em vez daquele livro.",
  [1143563229102592] = "Só quero que ele olhe a realidade de maneira adequada, em vez de ficar olhando para as estrelas o dia todo.",
  [1143563229102336] = "“Não é adequado para comer” e ele não comerá uma única mordida! “Não é adequado para ficar perto da água”, e ele nem lava o rosto!",
  [1143563229102080] = "Se posso sair, preciso de adivinhação e o que comer no jantar hoje também preciso de adivinhação !",
  [1143563229101824] = "Sim, mas você sabe como tem sido Flo nos últimos três anos?",
  [1143563229101312] = "Freer, foi você quem colou isso, não foi?",
  [1143563229101056] = "Vou conversar com Freer; sinta-se à vontade para olhar ao redor.",
  [1143563229100800] = "O que você está olhando? Um bando de leitores ávidos.",
  [1143563229100544] = "<P_Heart> (Irmão mais novo de Flo? Não parece gostar muito de astrologia.) </>",
  [1143563229100288] = "Tsk, astrologia, astrologia, tudo que você sabe é astrologia o dia todo.",
  [1143563229100032] = "Meu querido irmão, me dê os parabéns! Este é um mestre em astrologia!",
  [1143563229099776] = "Quem é esse?",
  [1143563229099264] = "Esse é o meu bem mais precioso, guardado em segurança em casa.",
  [1143563229099008] = "Livros? Posso dar uma olhada?",
  [1143563229098752] = "Huh? Mas meus livros de astrologia são todos cópias manuscritas que fiz um grande esforço para adquirir...",
  [1143563229098496] = "Talvez a sua interpretação da astrologia esteja errada?",
  [1143563229098240] = "<P_Heart> (Não notei nenhuma mudança nas estrelas nessas últimas noites, poderia ser...) </>",
  [1143563229097728] = "Estranho, sua sorte tem sido muito boa ultimamente e alguém vai até te ajudar na sua carreira.",
  [1143563229097472] = "Você, você conhece astrologia? Você realmente é uma pessoa maravilhosa!",
  [1143563229097216] = "Conheço um pouco sobre astrologia; Posso dar uma olhada para você.",
  [1143563229096960] = "Deve ser que as posições deles tenham mudado, sugando minha sorte! Você não acha isso assustador?",
  [1143563229096704] = "Quer sair, esbarra no canto de uma mesa! Compre uma maçã, corte-a e terá um buraco de minhoca!",
  [1143563229096448] = "Venho estudando astrologia há três anos, mas nos últimos dias as posições das estrelas ficaram todas confusas! E comecei a ter azar também!",
  [1143563229096192] = "Sou um entusiasta da astrologia. Todo mundo me chama de Flo, que olha as estrelas. Talvez você já tenha ouvido falar de mim?",
  [1143563229095936] = "Estrelas? O que está acontecendo?",
  [1143563229095680] = "<P_Heart> (Ah, não, fui descoberto.) </>",
  [1143563229095424] = "Quem está aí?",
  [1143563229094912] = "As lendas são todas falsas! Só um tolo acreditaria neles.",
  [1143563229094656] = "Não há nenhuma Deusa neste lago que possa realizar desejos!",
  [1143563229094400] = "Se, como disse a Baronesa, o criado é tímido e honesto, quem foi que lhe respondeu?",
  [1143563229094144] = "O servo mentiu ao ouvir a voz do Barão Hawkes... não, não deveria haver tantas contradições. É como se... algo tivesse dado errado em algum lugar.",
  [1143563229093888] = "O terceiro ponto, relativo à contradição do servo.",
  [1143563229093632] = "Por que razão alguém que uma vez arriscou a vida para salvar o Barão cometeria tal crime?",
  [1143563229093376] = "Segundo ponto, relativo à contradição do mordomo.",
  [1143563229093120] = "Como a atitude de uma pessoa poderia mudar tanto sem motivo? Poderia esta mudança de atitude ser o motivo para cometer o crime?",
  [1143563229092864] = "O primeiro ponto, relativo à contradição do médico.",
  [1143563229092608] = "Existem atualmente três contradições inexplicáveis ​​neste caso.",
  [1143563229092352] = "Será que o mordomo falsificou a cena do crime para incriminar o criado? Mas ele já esteve disposto a sacrificar sua vida para salvar seu mestre...",
  [1143563229092096] = "Como explicar a contradição entre a cena do crime e o depoimento?",
  [1143563229091840] = "A hora em que o mordomo foi ao quarto para entregar o remédio coincide com a hora da morte do Barão Hawkes. Ele teve tempo suficiente para assassinar o Barão Hawkes.",
  [1143563229091584] = "E os outros? Quem mais teve a oportunidade de assassinar o Barão Hawkes?",
  [1143563229091328] = "O criado que trouxe o chá foi a última pessoa a ir para o quarto. Segundo o depoimento, ele tem possibilidade de mentir e sua suspeita é alta.",
  [1143563229091072] = "Os depoimentos foram todos resolvidos. Pense nisso, quem tem as suspeitas mais óbvias?",
  [1143563229090816] = "Mordomo, médico, criado... nesse período todos tiveram a oportunidade de entrar no quarto. Parece que preciso coletar os depoimentos dos outros três para continuar a dedução.",
  [1143563229090560] = "Depois que a Baronesa saiu, alguém entrou na sala e encheu novamente o chá do Barão. Essa pessoa é provavelmente o assassino que criou o cenário do quarto trancado.",
  [1143563229090304] = "Antes de o Barão Hawkes morrer, o chá em sua xícara estava quase pronto, mas ainda havia muitas manchas de água no chão da sala.",
  [1143563229090048] = "O que o assassino fez no quarto?",
  [1143563229089792] = "A relação entre o Barão Hawkes e o Dr. Evan é um pouco estranha; O Dr. Evan pode ter um motivo. Parece necessário falar com ele.",
  [1143563229089536] = "Quem pode ter o motivo do crime?",
  [1143563229089280] = "A anormalidade do Barão Hawkes começou com a compra de uma antiguidade. Provavelmente é um item Beyonder. Poderia ser o início deste caso de assassinato?",
  [1143563229089024] = "Não há mais pistas aqui. Vamos analisar o que o Barão encontrou recentemente?",
  [1143563229088768] = "<P_Heart> (Essas abóboras são estranhas, vamos verificá-las primeiro.) </>",
  [1143563229088512] = "<P_Heart> (Parece que este é o lugar.) </>",
  [1143563229088256] = "Você também sente o cheiro dessas abóboras - tem certeza de que elas também são autênticas?",
  [1143563229088000] = "...... Somente o sangue dos malfeitores visto com meus próprios olhos pode garantir o descanso de Terry e Olivia.",
  [1143563229087744] = "Se eu não fizer isso, como poderei caçar um fugitivo no mar? Rezar para Gehrman Sparrow?",
  [1143563229087488] = "Sim! Exagerei minha beleza e menti sobre possuir uma grande quantidade de bens do meu marido, apenas para atraí-lo e atraí-lo para cá—",
  [1143563229087232] = "Então você entrou no jogo, escrevendo de volta para confundi-lo, dando-lhe uma chance de se vingar?",
  [1143563229086976] = "“Minha querida esposa Olivia, o pagamento das mercadorias que enviei para casa, você depositou no Backlund Bank, certo?”",
  [1143563229086720] = "Quando a primeira carta forjada chegou, descobri o problema – porque estava escrito dentro:",
  [1143563228893696] = "Se precisar, posso fazer um esboço de retrato para você.",
  [1143492898233856] = "Palco aberto",
  [1143563228619776] = "Eu estava sempre esperando você perguntar. Mas você foi muito teimoso. Você disse que um servo não tinha o direito de fazer pedidos.",
  [1143563229085440] = "É simples, esse pirata matou meu pobre marido e recebeu as cartas de nossa família.",
  [1143563229085184] = "Ele teve o que merecia, só quero saber toda a verdade.",
  [1143563229084928] = "O quê, quer me arrastar para ver a polícia?",
  [1143563229084672] = "Tempestade acima! Não, isso não está certo... não sei... não, Terry nunca mencionou isso!",
  [1143563229084416] = "Ela sofria de leucemia aguda há seis meses e, como não havia dinheiro suficiente para o tratamento, faleceu pouco depois.",
  [1143563229084160] = "Olivia já faleceu?",
  [1143563229083904] = "O que... o que? Isto é... isto...",
  [1143563229083648] = "Esta é Olívia.",
  [1143563229083392] = "<P_Heart> (A reação de Dana parece um pouco estranha, só para garantir, devo seguir e ver?) </>",
  [1143563229083136] = "Heh, uma amiga, hein... então vem comigo, vou te levar para encontrá-la.",
  [1143563229082880] = "Ha, sou amigo de Terry. Eu até vi o retrato que ele apreciava; ela é realmente uma linda senhora.",
  [1143563229082624] = "Muito lindo... você sabe disso muito bem, não é?",
  [1143563229082368] = "Sra. Dana, você sabe onde Olivia está? Ela é muito linda, deve ser famosa nessa vila, né?",
  [1143563229082112] = "Oh? Terry Lisbon faleceu... Meu nome é Dana, moro perto.",
  [1143563229081856] = "Sou Aaron e estou aqui para informar a Sra. Olivia da morte de seu marido, Terry. Posso perguntar quem você é?",
  [1143563229081600] = "<P_Heart> (Lamento julgar os outros, mas ela não é \"incrivelmente linda\", provavelmente não é aquela Sra. Olivia.) </>",
  [1143563229081344] = "Quem é você? O que você está fazendo aqui?",
  [1143563229081088] = "Suspiro... então pensarei em outra maneira. No entanto, Olivia é uma senhora incrivelmente bonita, deve ser fácil perguntar sobre ela.",
  [1143563229080832] = "Você é local? Segui o endereço, mas o dono não está aqui.",
  [1143563229080576] = "Meu nome é Aaron, vim de Pritz Harbour para visitar a viúva de Terry Lisbon, Olivia, para informá-la da morte de seu marido.",
  [1143563229080320] = "Ele parece muito ansioso...",
  [1143563229080064] = "Estou aqui para relatar uma morte. Você sabe para onde foi a dona Olivia, que mora aqui?",
  [1143563229079808] = "Oh! Você apareceu de repente, você realmente me deu um susto.",
  [1143563229079296] = "Usar minha escassa vida em troca de uma chance de testemunhar a verdade é realmente uma dádiva.",
  [1143563229079040] = "Obrigado, acho que você pode ser um anjo.",
  [1143563229078784] = "Você está disposto?",
  [1143563229078528] = "O preço é a sua vida, e sua alma dançará com a matemática para sempre.",
  [1143563229078272] = "Qual é o preço? Minha alma?",
  [1143563229078016] = "O conhecimento se transformou em um demônio em seu coração?",
  [1143563229077760] = "Você é um demônio?",
  [1143563229077504] = "Zoe Páprica. Você quer ver o fim dessa conjectura? A verdade por trás dos números, das equações e do iceberg.",
  [1143563229077248] = "Trinta e oito anos, passei trinta e oito anos provando essa conjectura. Ainda errado... Não tenho um segundo de trinta e oito anos.",
  [1143563229076992] = "Errado. Ainda errado.",
  [1143563229076736] = "Então deixe-me ver tudo.",
  [1143563229076480] = "A última página do mundo vegetal.",
  [1143563229076224] = "Só existe um preço: sua vida. Use o pouco tempo que lhe resta para trocar por toda a verdade que você nunca poderia perseguir na vida.",
  [1143563229075968] = "Todas as folhas. Cada padrão de veia. Cada estrutura celular. Dos tempos antigos ao presente, de agora ao futuro. Todas as folhas.",
  [1143563229075712] = "Todas as folhas?",
  [1143563229075456] = "Eleanor Wise, quer ver todas as folhas?",
  [1143563229075200] = "É impossível acompanhar – espécies antigas estão desaparecendo e novas espécies estão evoluindo. Minhas anotações nunca conseguem acompanhar a velocidade da própria vida.",
  [1143563229074944] = "Mas calculei que, mesmo que durma três horas a menos todas as noites, só conseguirei registrar algumas centenas a mais.",
  [1143563229074688] = "Três mil e setecentos. Registrei três mil e setecentas espécies de plantas em minha vida.",
  [1143563229074176] = "Prometi ensinar-lhe conhecimento oculto.",
  [1143563229073920] = "A última parte da Escola de Busca do Conhecimento. Métodos de meditação para Espreitadores de Mistérios, técnicas avançadas de percepção espiritual e algumas pesquisas sobre o Sábio Oculto. Não tenho mais utilidade para eles.",
  [1143563229073664] = "Isso, para você.",
  [1143563229073408] = "Obrigado. Eu vi o professor, eu vi o Lucas. Eles estão realmente muito felizes.",
  [1143563229073152] = "Acabou.",
  [1143563229072640] = "Pena... mas também sorte.",
  [1143563229072128] = "Não posso responder a essa pergunta, só posso lhe dizer a verdade imutável.",
  [1143563229071872] = "Por que? Por que não tenho que pagar um preço?",
  [1143563229071616] = "Posso mostrar-lhe a verdade do mundo... sem nenhum custo.",
  [1143563229071360] = "Você quer saber a verdade do mundo? Por que funciona desta forma, aonde acabará por levar. O fim de todos os questionamentos.",
  [1143563229071104] = "Você acha que é apenas uma testemunha? Não. Você também foi convocado. Esse livro escolheu você porque você também está perseguindo — perseguindo algo que você mesmo não consegue definir claramente.",
  [1143563229070848] = "Mas você não viu o seu próprio.",
  [519109611792128] = "Sem problemas.",
  [519109611814912] = "Está bem aqui!",
  [1143563229070592] = "Você viu as folhas de Eleanor, o iceberg de Zoe, a resposta de Edwin. Você viu por que eles entraram.",
  [1143563229070080] = "Quem vê a última página não morre de conhecimento. Eles veem a verdade e depois fecham os olhos de satisfação. Esta é a felicidade de quem busca conhecimento.",
  [519109612000256] = "Isso é...",
  [519109612008704] = "Sem problemas!",
  [1143563229069568] = "O Imperador Roselle disse uma vez: \"Se alguém pode aprender a verdade pela manhã, vale a pena enfrentar a morte à noite.\"",
  [519109612045824] = "Obrigado.",
  [1143563229069312] = "Todos os buscadores de conhecimento aqui que buscam a verdade são felizes.",
  [1143563229069056] = "Marlow, acho que seu professor está feliz.",
  [1143563229068800] = "Vamos, vou levá-lo para o “Domínio do Conhecimento”.",
  [1143563229068544] = "E você? Qual você escolhe?",
  [1143563229068288] = "Ele não tem medo da morte. Ele simplesmente sente que pode fazer mais coisas enquanto está vivo. Vocês dois estão certos.",
  [1143563229068032] = "Marlow escolheu a vida. Ele tem medo da morte.",
  [1143563229067776] = "E Marlow?",
  [1143563229067520] = "Estou certo. A vida é limitada, o conhecimento é infinito. Vale a pena trocar o limitado pelo infinito.",
  [1143563229067264] = "Tem certeza... que quer trocar sua vida por uma chance de vislumbrar a verdade?",
  [1143563229067008] = "Esse ainda é o último passo.",
  [1143563229066752] = "Você está no último degrau desde os vinte e dois anos. Agora você tem sessenta anos.",
  [1143563229066496] = "Você sabia que estou a apenas um passo de provar isso?",
  [1143563229066240] = "Um novo projeto do grupo de Matemática Aplicada – otimização do algoritmo Difference Engine. Há financiamento, há assistentes. Eles disseram que você pode participar.",
  [1143563229065984] = "Um novo projeto?",
  [1143563229065728] = "Zoe, uma carta da academia. Seu projeto ocupou a sala de pesquisa por muito tempo e precisa ser liberado para um novo projeto.",
  [1143563229065472] = "Tente não tocar em cogumelos de cores vivas. Vamos.",
  [1143563229065216] = "Obrigado. Se não fosse por você, ele poderia ter...",
  [1143563229064960] = "Este patch é todo do mesmo tipo. Todos os anos as pessoas vêm buscá-los. Todos os anos morrem pessoas.",
  [1143563229064704] = "Huh? Parece bastante delicioso.",
  [1143563229064448] = "Não toque nisso. Brânquias amarelas, gorro branco, base bulbosa – altamente venenosas!",
  [1143563229064192] = "Eu me importo.",
  [1143563229063936] = "E daí se houver uma nova espécie? Você registrou três mil e setecentas espécies de plantas; quem se importa com mais um?",
  [1143563229063680] = "A encosta norte desta montanha ainda não foi pesquisada. A composição do solo na encosta norte é diferente desta, podendo haver novas espécies.",
  [1143563229063424] = "Eleanor, você está nesta montanha há três meses. O financiamento está quase acabando, por quanto tempo você vai arrecadar?",
  [1143563229063168] = "Por que, por que? Por que ele entrou mesmo sabendo que isso significava a morte?",
  [1143563229062912] = "Mas o professor foi o último mentor da Escola da Verdade; ele devia saber o preço da “Última Página”.",
  [1143563229062656] = "Eu estava tolamente querendo provar isso uma vez.",
  [1143563229062400] = "Eu adivinhei. Na verdade, eu adivinhei. Ninguém que entrou jamais voltou.",
  [1143563229062144] = "Depois a professora e o Lucas?",
  [1143563229061888] = "Essas pessoas... já morreram há muito tempo.",
  [1143563229061632] = "Estou disposto a lhe ensinar todo o conhecimento oculto que aprendi em minha vida.",
  [1143563229061376] = "Nunca fui capaz de resistir a esses sussurros terríveis, mas você! Você pode isolar essa voz, talvez possa me acolher.",
  [1143563229061120] = "Agora que minha vida está chegando ao fim, antes de morrer, quero mergulhar nas profundezas do conhecimento para encontrá-los e confirmar... que eles também são felizes.",
  [1143563229060864] = "Mas não me arrependo; Vivi uma vida covarde, mas feliz.",
  [1143563229060608] = "Sempre me perguntei: decepcionei meu professor ao escolher a vida? Não sou um buscador qualificado de conhecimento, nem um Espreitador de Mistérios qualificado. Tenho medo da perda, medo do desconhecido, medo de virar esta página.",
  [1143563229060352] = "Sim. Meu colega Lucas escolheu a verdade. A professora levou Lucas às profundezas do Domínio do Conhecimento e eles nunca mais voltaram.",
  [1143563229060096] = "Você escolheu a vida?",
  [1143563229059840] = "Mais tarde, minha professora perguntou a Lucas e a mim – o que é mais importante, a vida ou a verdade?",
  [1143563229059584] = "Ele deu a resposta, conduzindo-os ao “Domínio do Conhecimento”, mas aqueles que entraram nunca mais retornaram.",
  [1143563229059328] = "Até que alguém fez aquela pergunta: “Qual é o fim da verdade?”",
  [1143563229059072] = "Já foi um objeto sagrado da Escola da Verdade. No início, apenas ajudava as pessoas a organizar memórias e resumir o conhecimento aprendido. Mas comunicaria com as pessoas; quanto mais comunicava, mais profundo dava. De resumir, passou a deduzir e depois a revelar.",
  [1143563229058816] = "É a “Última Página”, que o Artefato Selado está me chamando novamente.",
  [1143563229058560] = "Você está bem? Isso agora foi—",
  [1143563229058304] = "<P_Heart> (Ele foi corroído pelos sussurros; sua loucura deve ser suprimida!) </>",
  [1143563229058048] = "Você está certo... estou velho... um novo buscador de conhecimento está bem diante de mim... leve-o para dentro... leve-o para dentro...",
  [1143563229057792] = "Correr! Deixe este lugar!",
  [1143563229057536] = "Está acontecendo de novo... a voz... está me chamando para virar aquela página novamente... é sempre a mesma frase...",
  [1143563229057280] = "Procurando por aqueles crentes fanáticos do conhecimento. Durante quarenta anos, tenho impedido você, impedido que seja devorado pelo conhecimento.",
  [1143563229057024] = "Está buscando, sempre esteve buscando.",
  [1143563229056768] = "A última página?",
  [1143563229056512] = "O livro que você trouxe, a sombra remanescente dentro dele, são todos chamados da “Última Página”...",
  [1143563229056256] = "Mas você ainda veio e ainda caminhou até mim.",
  [1143563229056000] = "Parece que você já provou seu amargor, e é por isso que você chama isso de maldição.",
  [1143563229055744] = "Faz você sentir que pode transcender tudo, e então você realmente tentará transcender tudo – inclusive a morte. Já vi muitas pessoas que entraram assim.",
  [1143563229055488] = "Conhecimento é poder? Se você pensar assim, isso se tornará uma maldição.",
  [1143563229055232] = "O que você acha que é conhecimento?",
  [1143563229054976] = "Responda-me uma pergunta e eu lhe direi a resposta.",
  [1143563229054720] = "Não, quero descobrir qual é a sombra remanescente para evitar que qualquer poder extraordinário vaze aqui. Parece que você também é um Beyonder ?",
  [1143563229054464] = "Eu também sei que você é um Beyonder , atraído aqui por uma sombra remanescente sem sentido.",
  [1143563229054208] = "Como você sabia?",
  [1143563229053952] = "Você também está aqui para buscar a verdade?",
  [1143563229053696] = "Vá encontrá-lo. Se você também é um buscador desesperado de conhecimento como eu.",
  [1143563229053440] = "Vá para o Lago Dourado do Outono. Lá, uma verdade está enterrada.",
  [1143563229053184] = "Se você também está procurando, tendo esgotado sua vida assim como eu—",
  [1143563229052928] = "<P_Heart> (Que som? Há Beyonder poder!) </>",
  [1143563229052672] = "A verdade sempre está além do fim da sua vida.",
  [1143563229052416] = "É doloroso? Está desesperado?",
  [1143563229052160] = "<P_Heart> (Uma verdade que nunca poderá ser alcançada?) </>",
  [1143563229051904] = "Muitos estudos, depois de um tempo interminável, poderão apenas levar a uma verdade que nunca poderá ser alcançada.",
  [1143563229051648] = "Ter um professor repreendendo você significa que ainda há alguém orientando sua direção. Isso também é uma espécie de felicidade...",
  [1143563229051392] = "Fazer pesquisa é muito cansativo. Os dados do experimento da semana passada estavam errados novamente, e fui repreendido pelo meu professor na reunião do grupo esta manhã.",
  [1143563229051136] = "Venho estudando variantes do Antigo Feynapotteriano há um ano e meu manuscrito foi rejeitado três vezes.",
  [1143563229050880] = "Diga-me... minha abóbora é autêntica?",
  [1143563229050624] = "Eu realmente... não suporto deixá-la ir.",
  [1143563229050368] = "Mas não tenho escolha. Tentei esmagar as abóboras – era inútil, elas voltariam a crescer no dia seguinte. Só posso continuar vendendo-os. Se eu vender uma, poderei vê-la uma vez.",
  [1143563229050112] = "Eu sei que a coisa dentro da abóbora devora o comprador. Todo mundo que veio comprar uma abóbora morreu.",
  [1143563229049856] = "Mais tarde descobri que toda vez que vendia uma, ela aparecia naquela noite.",
  [1143563229049600] = "Naquela noite, ela apareceu – de pé ao lado da cama, como quando estava viva. Ela não disse nada, apenas ficou lá até o amanhecer.",
  [1143563229049344] = "Uma semana depois, uma videira cresceu em seu túmulo, florescendo com flores fora de estação. Mais tarde, as vinhas deram origem a estas abóboras.",
  [1143563229049088] = "<P_Heart> (Silêncio por um longo tempo) </> Minha esposa morreu há três meses e eu a enterrei na margem leste.",
  [1143563229048576] = "……Sim. Todo mundo que vem comprar melões é.",
  [1143563229048320] = "Há vestígios de sangue por todo lado no chão... você tem alimentado essas abóboras com as pessoas?",
  [1143563229048064] = "Já que você descobriu isso, experimente você mesmo o que significa ser autêntico.",
  [1143563229047808] = "<P_Heart> (Tez alterada) </> ... Você está perguntando se é autêntico?",
  [1143563229047552] = "Vou perguntar uma última vez: esta sua abóbora é autêntica?",
  [1143563229047296] = "Com um cheiro tão forte de sangue, você sabe muito bem o que tem dentro dessas abóboras.",
  [1143563229047040] = "<P_Heart> (Olhos piscaram) </> Você está procurando problemas de propósito? Se você quiser, pegue; se não, vá embora. Não atrase meus negócios. Há pessoas esperando na fila atrás de você.",
  [1143563229046784] = "Então escolha um para mim. Mas, essa sua abóbora é autêntica?",
  [1143563229046528] = "Minhas abóboras são diferentes das outras. Eles podem realizar seus desejos e seus sonhos - você saberá assim que comprar um.",
  [1143563229046272] = "Quanto? A casca da sua abóbora é feita de ouro ou as sementes são feitas de ouro?",
  [1143563229046016] = "Dois mil Sol por libra.",
  [1143563229045760] = "Quanto custa a sua abóbora por quilo?",
  [1143563229045504] = "Oh, alguém que conhece suas coisas chegou. Posso dizer que você é um especialista – quer comprar uma abóbora?",
  [1143563229045248] = "Perto do celeiro. Não diga que eu te contei.",
  [1143563229044992] = "Todos que os compraram disseram que valeu a pena. Mas algumas pessoas nunca mais voltaram depois de comprá-los.",
  [1143563229044736] = "<P_Heart> (\"Sonhos tornados realidade\"?) </>",
  [1143563229044480] = "<P_Heart> (Voz baixa) </> ... Um lavrador trouxe algumas abóboras, alegando que eram coisas boas que poderiam realizar os \"sonhos\" de alguém.",
  [1143563229044224] = "Este aviso de pessoa desaparecida diz que alguém desapareceu perto da fazenda—",
  [1143563229043968] = "Não me pergunte. Sou apenas alguém vendendo peixe defumado na estação; Não sei nada sobre esses assuntos.",
  [1143563229043712] = "Chefe, deixe-me perguntar: aconteceu alguma coisa na fazenda Golden Autumn Lake recentemente?",
  [1143563229043456] = "<P_Heart> (Na verdade... é que você não consegue esquecê-lo...) </>",
  [1143563229043200] = "Tudo bem, parece que Martin realmente está assombrando este lugar. Eu não terminei com você!",
  [1143563229042944] = "Na verdade-",
  [1143563229042688] = "Muito menos eu.",
  [1143563229042432] = "Não fui eu.",
  [1143563229041920] = "Lá vamos nós de novo, cestos quebrados e legumes podres... quem fez isso!",
  [1143563229041664] = "Terminei de fazer as malas, você também deve fechar sua barraca logo.",
  [1143563229041408] = "Ahem... tudo bem, tudo bem, eu não te odeio, ok?",
  [1143563229040896] = "Por que você tem tantas perguntas hoje?",
  [1143563229040640] = "Então, você... não me odeia?",
  [1143563229040384] = "Ainda bem que foi apenas um sonho. Como um cara tão irritante quanto você pode morrer? Hahaha.",
  [1143563229039872] = "Mas, por alguma razão, sempre que me deparava com aquela barraca de carne, meu coração ficava particularmente em pânico e vazio.",
  [1143563229039616] = "Sonhei que você morreu, comprei sua barraca de verduras e transformei-a em barraca de carne.",
  [1143563229039360] = "<P_Heart> (Pausa) </> A propósito, tenho tido sonhos ultimamente, velho amigo.",
  [1143563229039104] = "O que há para ficar com raiva? Há muito tempo estou acostumado com como você é.",
  [1143563229038848] = "<P_Heart> (O relacionamento deles não parece tão ruim...) </> Você não está mais com raiva?",
  [1143563229038592] = "<P_Heart> (Suspirando) </> E a cesta de legumes, aprenda a arrumar.",
  [1143563229038336] = "Esses vegetais também, se não forem frescos, troque-os rapidamente, caso contrário não ficam bem.",
  [1143563229038080] = "Na verdade, não é como se as cebolas não pudessem ser penduradas, só não aponte-as para os meus olhos...",
  [822505833449984] = "Chegou o momento prometido, meu ouvinte e testemunha desta história.",
  [1143563229037824] = "Tosse... fui muito duro agora?",
  [1143563229037568] = "Uh... na verdade eu...",
  [1143563229037312] = "Eu digo Martin, você está muito estranho hoje, por que não está dizendo uma palavra?",
  [1143563229037056] = "Sr. Mori... parece...",
  [1143563229036800] = "<P_Heart> (Olhos opacos) </> Sinceramente... é assim todos os dias... só temos que discutir...",
  [360778595140864] = "Isso missão sempre me deixa desconfortável, minha pequena Rozanne, a pessoa com quem mais me preocupo.",
  [822505833100288] = "Definitivamente!",
  [1143563229036544] = "<P_Heart> (Ocupado) </> Esqueça, esqueça, saia do caminho, não bloqueie a estrada.",
  [1143563229036288] = "A cesta de legumes está sempre uma bagunça, quando você vai aprender a arrumar?!",
  [1143563229036032] = "O quê, meu presunto também te deixa desconfortável? Seu idiota sem gosto, essa é a fragrância da cura!",
  [1143563229035776] = "E essas cebolas sempre me fazem chorar. Já se passaram vinte anos, você não pode pendurá-los em outro lugar!",
  [1143563229035520] = "Espere, eu não estou—",
  [1143563229035264] = "O cliente achou que minha carne não estava fresca e quis que eu pagasse por ela!",
  [1143563229035008] = "Quem mais! As lagartas dos vegetais subiram todas nas minhas salsichas!",
  [1143563229034752] = "Quem? Meu?",
  [1143563229034496] = "Martin, você chegou bem na hora! Afaste ainda mais a sua cesta de vegetais!",
  [1143563229034240] = "Devo deixá-lo saber o quão durão eu sou!",
  [360778595458048] = "Sr.",
  [1143563229033984] = "Sr. Mori, o que você está fazendo?",
  [1143563229033728] = "De novo... de novo... quantas vezes eu já disse...",
  [1143563229033472] = "<P_Heart> (Será que realmente é assombrado...) </>",
  [1143563229033216] = "Boa ideia, conte comigo.",
  [1143563229032960] = "Por que não ir à igreja e orar?",
  [1143563229032704] = "Aquela sombra negra... é mesmo o fantasma de Martin? Deusa...",
  [1143563229032448] = "Acostumei-me com isso. Martin faleceu no mês passado e pensei que a discussão iria acabar, mas quem diria que Mori começaria a discutir novamente com a barraca de vegetais vazia.",
  [1143563229032192] = "Isso... e eles ainda poderiam ser vizinhos por vinte anos?",
  [1143563229031936] = "Tudo é uma briga: abrir a porta é uma briga, fechar a barraca é uma briga, você atrapalha meu jeito de pendurar salsichas, estou impedindo você de mexer nos legumes... é tão animado todos os dias.",
  [1143563229031680] = "Tanto tempo? Sobre o que eles estavam discutindo?",
  [1143563229031424] = "Mori e Martin eram vizinhos. Mori tinha uma barraca de carne, Martin vendia vegetais. Eles não suportavam ver um ao outro e discutiam há vinte anos.",
  [1143563229031168] = "Quem é Martinho? O relacionamento deles era muito ruim?",
  [1143563229030912] = "Então vou chutar seu túmulo com força!",
  [1143563229030656] = "Calma, irmão Mori, você não pode chutar a bunda de um morto.",
  [1143563229030400] = "Se você não se comportar, juro que vou chutar sua bunda com força!",
  [1143563229030144] = "<P_Heart> (De frente para a barraca de verduras) </> Escuta, a barraca já é minha!",
  [1143563229029888] = "Eu vi uma sombra negra se movendo perto de longe ontem à noite, agindo sorrateiramente...",
  [1143563229029632] = "G-fantasma?",
  [1143563229029376] = "<P_Heart> (Abaixando a voz) </> Poderia ser... o fantasma de Martin?",
  [1143563229029120] = "Também não sei, fiquei só olhando a massa do pão no forno...",
  [1143563229028864] = "Não sei... fechei a barraca bem cedo ontem...",
  [1143563229028608] = "Quem fez isso! Quem diabos fez isso!",
  [1143563229028352] = "Onde está meu presunto? Meu bacon? Minhas salsichas assadas secretas?",
  [1143563229028096] = "Eu assumi esta barraca de vegetais! Mudei para uma barraca de carne! Por que ele volta ao seu estado original todos os dias!",
  [1143563229027840] = "Posso te ajudar.",
  [1143563229027584] = "Mas já verifiquei vários lugares... não aguento mais esperar!",
  [1143563229027328] = "Tenho um assunto urgente em relação à minha filha que precisa de adivinhação —",
  [1143563229026304] = "Será que... ele está sendo controlado?",
  [1143563229026048] = "Ele apenas fez o mesmo brinde duas vezes seguidas, e a segunda vez foi quase exatamente igual.",
  [1143563229025792] = "A atuação do Barão é um pouco rígida... não nervosa, como se ele estivesse \"atuando\".",
  [1143563229024768] = "Vamos trabalhar duro juntos, {{PlayerName}}. Esforce-se para melhorar e, um dia, ambos retornaremos à nossa cidade natal.",
  [1143563229024512] = "......Sim, posso entendê-lo muito bem, Sr. Klein. Essa é a nossa cidade natal comum, e muitas vezes sinto falta dos dias daquela época.",
  [1143563229024256] = "(...Neste momento, como projeção histórica de seu período Tingen, ele ainda não sabe a verdade de que sua casa está enterrada há muito tempo. Melhor não expor isso.)",
  [1143563229024000] = "Talvez só você, como compatriota, possa compreender tais sentimentos.",
  [1143563229023744] = "Contar essas coisas para pessoas de fora, a maioria acharia muito absurdo. Mas comparado a aqui, realmente parece mais um lindo sonho.",
  [1143563229023488] = "Às vezes, quando acordo tarde da noite, penso em tudo o que está ali: o leite de soja e os palitos de massa frita na loja do café da manhã, as multidões enterradas em seus telefones no metrô, o caminho para casa tarde da noite depois de fazer horas extras...",
  [1143563229023232] = "Quero voltar para meu verdadeiro lar. Lá não há Extraordinário, nem poções, nem conhecimentos que façam perder o controle e enlouquecer.",
  [1143563229022976] = "Qual motivo?",
  [1143563229022720] = "Você poderia dizer isso. Espero ser forte o suficiente para proteger tudo o que quero proteger. Mas além disso... tenho outro motivo.",
  [1143563229022464] = "Você é realmente uma pessoa gentil, Sr. Klein. A proteção foi a razão pela qual você quis se tornar mais forte em primeiro lugar?",
  [1143563229022208] = "No entanto, precisamente por causa disso, devemos esforçar-nos para nos tornarmos mais fortes para proteger a nossa vida quotidiana pacífica de ser perturbada.",
  [1143563229021952] = "<P_Heart> (Silêncio) </> Sim. Mas talvez este seja o preço que um Beyonder deva pagar, um pobre coitado que luta constantemente contra o perigo e a loucura.",
  [1143563229021696] = "Você deve sentir muita falta deles.",
  [1143563229021440] = "Porém... para protegê-los, tento não vê-los agora. O Mundo Extraordinário é muito perigoso e não quero que o perigo os alcance.",
  [1143563229021184] = "Sim, tenho um irmão mais velho e uma irmã mais nova. Meu irmão trabalha em um departamento governamental e minha irmã ainda está na escola. Ambos são pessoas muito boas.",
  [1143563229020928] = "A sua família também está em Tingen?",
  [1143563229020672] = "Eu fiz universidade lá, fui Vigia Noturno lá, e lá... eu vivi muita coisa.",
  [1143563229020416] = "Sim, essa é minha cidade natal. Uma pequena cidade tranquila, com um ritmo de vida lento e as pessoas muito simpáticas.",
  [1143563229020160] = "Sr. Klein, ouvi dizer que você é de Tingen.",
  [1143563229019904] = "<P_Heart> (Trocando um olhar com Klein, suspirando simultaneamente) </> Suspiro...",
  [1143563229019648] = "……Talvez. Mas até onde eu sei, os materiais para sequências superiores são ainda mais caros.",
  [1143563229019392] = "Depois de avançar para um Sequência alto, não precisarei mais me preocupar com algumas libras ou xelins?",
  [1143563229019136] = "Você realmente estudou a fundo como economizar dinheiro... Todas essas sugestões são muito úteis! Sinto que posso aguentar mais um pouco.",
  [1143563229018880] = "Além disso, tente negociar em vez de usar dinheiro sempre que possível. Use Beyonder materiais que você não precisa trocar por aqueles que você precisa; isso economiza a marcação do intermediário.",
  [1143563229018624] = "Faça compras. Por exemplo, os preços do mesmo material Beyonder podem variar muito entre diferentes canais. O preço de câmbio interno para Vigias Noturnos é geralmente mais barato que o mercado negro.",
  [1143563229018368] = "Então, e se você se deparar com uma situação em que precise gastar dinheiro?",
  [1143563229018112] = "Resumindo, a essência de economizar dinheiro é: se você não precisa gastá-lo, absolutamente não o gaste.",
  [1143563229017856] = "Além disso, o dinheiro ganho deve ser alocado adequadamente: parte para despesas diárias e parte economizada para compra de Beyonder materiais.",
  [1143563229017600] = "Isso é realmente muito frugal...",
  [1143563229017344] = "Quanto às refeições, a padaria oferece descontos no pão restante do dia anterior ao encerramento. Você pode comprar um saco de pão de centeio por 2 centavos e, com 1 centavo de sopa de ervilha, uma refeição custa apenas 3 centavos.",
  [1143563229017088] = "Embora as condições sejam um pouco simples, a limpeza e a segurança podem ser garantidas.",
  [1143563229016832] = "Bem... em primeiro lugar, em relação ao alojamento – se não for ficar muito tempo, um quarto normal num hotel por 2 soli por noite é suficiente.",
  [1143563229016576] = "Sr. Klein, sempre sinto que não tenho dinheiro suficiente ultimamente... Você tem algum conselho para economizar dinheiro?",
  [1143563229016320] = "Portanto, também estou de olho em pistas relevantes para ele. Se eu puder ajudar o Sr. Azik a recuperar suas memórias, também ficaria muito feliz.",
  [1143563229016064] = "<P_Heart> (Suspirando) </> O Sr. Azik perdeu muitas memórias. Atualmente ele está viajando pelo mundo em busca de pistas que possam despertar suas memórias.",
  [1143563229015808] = "Memórias perdidas?",
  [1143563229015552] = "Às vezes penso que, se não fosse pela orientação dele, eu poderia ter perdido o controle ou morrido em algum incidente extraordinário há muito tempo.",
  [1143563229015296] = "Sim. O Sr. Azik é como um ancião para mim. Embora ele esteja procurando por suas memórias perdidas, sua ajuda para mim nunca diminuiu.",
  [1143563229015040] = "Ele deve ser um professor muito bom.",
  [1143563229014784] = "O Sr. Azik é muito experiente e sempre pode dar conselhos precisos e úteis.",
  [1143563229014528] = "Sempre que encontro Beyonder conhecimento que não entendo ou situações perigosas, escrevo para ele pedindo conselho ou ajuda.",
  [1143563229014272] = "Você costuma pedir conselhos ao Sr. Azik?",
  [1143563229014016] = "Contanto que eu estrague tudo, posso convocar seu mensageiro. Posso escrever cartas para ele através do mensageiro e ele responderá às minhas perguntas.",
  [1143563229013760] = "Antes de o Sr. Azik deixar Tingen, ele me deu um apito de cobre.",
  [1143563229013504] = "Você ainda está em contato com ele agora?",
  [1143563229013248] = "De certa forma, o Sr. Azik foi meu professor no Departamento de História da Universidade Khoy. Ele é um estudioso muito erudito e também um poderoso Beyonder .",
  [1143563229012992] = "Sr. Klein, notei que você menciona frequentemente \"Sr. Azik\". Ele é seu mentor?",
  [1143563229012480] = "Sim, lembro que nosso compatriota também disse mais tarde: Quando eu me tornar uma grande potência, vou derrotar todos os \"Videntes\" que encontrar!Sequência",
  [1143563229012224] = "Ah, certo, você também vem de lá, então pode entender o diário que Roselle escreveu em chinês.",
  [1143563229011968] = "......Isso me lembra aquela frase do diário de Roselle, onde o Imperador disse: “Videntes” sempre dizem metade e escondem metade, nunca explicando as coisas claramente?",
  [1143563229011712] = "<P_Heart> (Risos) </> Talvez esses segredos escondidos nos Sequência Caminhos só possam ser compreendidos quando você mesmo os experimentar.",
  [1143563229011456] = "Portanto?",
  [1143563229011200] = "Isso mesmo, o destino é como uma névoa espessa. Você pode iluminar a pequena área sob seus pés através de adivinhação , mas não consegue perceber tudo completamente. Portanto-",
  [1143563229010944] = "Por exemplo, interpretar a trajetória do destino e dizer ao cliente exatamente o que você vê? Mas sinto que adivinhar o destino é inerentemente misterioso e profundo.",
  [1143563229010688] = "Alcançar esta etapa é “realizar ações que se alinhem com o nome da poção”, e a próxima etapa é “compreender as leis ocultas”.",
  [1143563229010432] = "Por exemplo, se você é um “Vidente”, você pode considerar ir a um clube Adivinhação ou montar uma barraca adivinhação na rua para adivinhar para outras pessoas e receber feedback.",
  [1143563229010176] = "A essência do chamado \"Método de atuação\" é \"realizar ações que se alinhem com o nome da poção, compreender as leis ocultas e obedecer estritamente a elas\".",
  [1143563229009920] = "Mas você já aprendeu alguns dos mistérios, então discutir esse aspecto com você não deve ser considerado uma violação do juramento.",
  [1143563229009664] = "Aham... na verdade, jurei diante da Deusa que não revelaria o Método de atuação para outras pessoas ignorantes.",
  [1143563229009408] = "Sr. Klein, eu sei que Beyonders precisa digerir poções através de \"Atuação\", mas eu realmente gostaria de ouvir sua compreensão de como fazer isso especificamente.",
  [1143563229009152] = "Eu entendo, obrigado pelo lembrete.",
  [1143563229008896] = "Você os vê e eles também veem você.",
  [1143563229008640] = "<P_Heart> (Solenemente) </> Quando você tenta investigar essas existências que excedem em muito a sua compreensão, suas ações são como acender uma tocha no escuro—",
  [1143563229008384] = "Contemplado?",
  [1143563229008128] = "Mas lembre-se: nunca adivinhe para si mesmo e nunca adivinhe para existências de alto nível. O primeiro o levará ao auto-engano, e o último fará com que você seja “observado”.",
  [1143563229007872] = "Radiestesia de pêndulo e sonho adivinhação . O pêndulo é adequado para julgamentos rápidos do certo e do errado, enquanto o sonho adivinhação pode fornecer informações mais detalhadas.",
  [1143563229007616] = "Então qual é o seu método adivinhação mais comumente usado?",
  [1143563229007360] = "Contudo, esta informação precisa ser interpretada, e a precisão da interpretação depende da experiência do adivinho.",
  [1143563229007104] = "O núcleo de adivinhação é a \"revelação\", que envolve estabelecer uma conexão com o Mundo Espiritual através de espiritualidade para obter informações vagas.",
  [1143563229006848] = "<P_Heart> (Sorrisos) </> Antes de me tornar um Beyonder , eu pensava o mesmo. Mas agora eu sei que adivinhação é realmente eficaz; requer apenas o método certo.",
  [1143563229006592] = "Sr. Klein, para ser honesto, eu costumava pensar que adivinhação era apenas um truque enganoso.",
  [1143563229006336] = "Minha Deusa dos Desejos tem um nome, e o nome dela é Sarah.",
  [1143563229006080] = "Mamãe nunca mentiu para mim. Os presentes são reais e a Deusa também é real.",
  [1143563229005824] = "Valéria...",
  [1143563229005568] = "E mesmo que mamãe não possa me ver, sei que ela me ama.",
  [1143563229005312] = "Sim, claro que sim. Mas ela não é apenas minha mãe; algumas coisas são mais importantes do que reuniões.",
  [1143563229005056] = "Parece que ela também não pode voltar desta vez. Você não quer vê-la?",
  [1143563229004800] = "Sim! É a mamãe!",
  [1143563229004544] = "Serra enviou isso?",
  [1143563229004032] = "E as bonecas e os doces de frutas que são populares em Backlund ultimamente.",
  [1143563229003776] = "Quão completo! Grama Lâmina de Água, Erva Fragrância Noturna, Grama Abelha Rainha, “Compêndio de Poções Avançadas”…",
  [1143563229003520] = "Fico contente em ajudar.",
  [1143563229003264] = "Você poderia me ajudar a abrir o outro pacote?",
  [1143563229003008] = "Huh? Há outro pacote aqui.",
  [1143563229002752] = "Nossa, chega de conversa. Preciso me apressar e espalhar a Grama Lâmina de Água fresca para secar.",
  [1143563229002496] = "Quero que ela saiba que estou trabalhando duro para me tornar alguém tão incrível quanto ela.",
  [1143563229002240] = "Escrevo meus desejos e é como se estivesse falando com ela.",
  [1143563229001984] = "Só sinto um pouco de falta da mamãe.",
  [1143563229001728] = "Então por que você ainda vai ao lago para fazer desejos?",
  [1143563229001472] = "Deixe-me contar um segredo: na verdade sei que não existe nenhuma Deusa dos Desejos no lago; isso foi algo que mamãe inventou.",
  [1143563229001216] = "Afinal, sou a inteligente Valerie.",
  [1143563229000960] = "Então você descobriu, afinal.",
  [1143563229000704] = "Que grama de lâmina de água fresca, obrigado pelo presente de aniversário!",
  [1143563229000448] = "Se eu não tivesse visto você largar o pacote, com certeza teria acreditado.",
  [1143563229000192] = "Eu estava passando e vi um flash de luz branca, então vim por curiosidade!",
  [1143563228999936] = "Olá, Valéria!",
  [1143563228999680] = "<P_Heart> (Talvez eu deva agir como a Deusa dos Desejos pela primeira vez.) </>",
  [1143563228999424] = "<P_Heart> (Se Serra não puder voltar, ela não poderá ajudá-la a realizar seu desejo de aniversário.) </>",
  [1143563228999168] = "<P_Heart> (Pobre Valerie) ... </>",
  [1143563228998912] = "Suspiro, amanhã é aniversário da pequena Valéria e não sei se Serra poderá voltar dessa vez.",
  [1143563228998656] = "Na realidade, esses “presentes da Deusa” foram todos arranjados discretamente por Sarah.",
  [1143563228998400] = "Contanto que você deixe um desejo sincero à beira do lago, você poderá receber um presente da Deusa.",
  [1143563228998144] = "No passado, sempre que ela saía, Valerie chorava. Então ela simplesmente inventou uma história para animar a pequena Valerie.",
  [1143563228997888] = "Sarah trabalha como médica em Backlund e está tão ocupada que nem tem tempo para escrever cartas e quase não volta para casa algumas vezes por ano.",
  [1143563228997632] = "Não existe Deusa. Essa era a mãe de Valerie, Sarah, disfarçada.",
  [1143563228997376] = "A lenda poderia ser verdadeira?",
  [1143563228997120] = "A pequena Valerie sempre acreditou firmemente que uma Deusa vive no Lago Dourado do Outono. Contanto que se ore sinceramente, o desejo será atendido.",
  [1143563228996864] = "Eles estão discutindo se existe uma Deusa dos Desejos no lago.",
  [1143563228996608] = "Olá, senhora. Você sabe sobre o que as crianças estão discutindo?",
  [1143563228996352] = "Que ratinho espiritual inteligente. É uma pena que se o mestre pisou em uma armadilha mística letal no momento em que voltou para a sala, ou se foi gravemente ferido por um Espírito Maligno e morreu após pisar na armadilha enquanto fugia para a cozinha, é algo que nunca saberemos.",
  [1143563228996096] = "<P_Heart> (Linguagem do esquilo) </> Guincho, guincho, guincho! Quando acordei... o Mestre estava deitado na cozinha... e ele estava... ele já estava com frio...",
  [1143563228995840] = "<P_Heart> (Linguagem do esquilo) </> E então... eu não sabia mais de nada...",
  [1143563228995584] = "<P_Heart> (Linguagem do esquilo) </> Ele dizia... o que quisesse... mesmo que fosse apenas um residente de passagem... iria acolher todos eles...",
  [1143563228995328] = "<P_Heart> (Linguagem do esquilo) </> Ele riu... bem baixinho, mas fez meu corpo espiritual tremer... Ele disse... que já havia colhido muitas almas... e desta vez também... estava determinado a ter sucesso...",
  [1143563228995072] = "<P_Heart> (Linguagem do esquilo) </> Está desenhando uma grade no chão... um quadrado, dois quadrados, muitos quadrados... esses quadrados estão brilhando com uma luz estranha... é como... como algum tipo de misticismo...",
  [1143563228994816] = "<P_Heart> (Linguagem do esquilo) </> Em meu torpor, eu vi uma... sombra negra... vagando pela sala...",
  [1143563228994560] = "<P_Heart> (Linguagem do esquilo) </> Não sei por que, estou com tanto, tanto sono... É como se algo... estivesse suprimindo meu espiritualidade ...",
  [1143563228994304] = "<P_Heart> (Linguagem do esquilo) </> Squeak... naquela noite... O Mestre ainda não tinha voltado...",
  [1143563228989184] = "Um caderno? Diz... \"Um guia itinerante para a cidade dos nenúfares\"?",
  [1143563228988672] = "Não... não!",
  [1143563228988160] = "Sim, mas isso também requer alguma sabedoria e um olhar atento... Acho que é hora de estabelecer um mercado de livre comércio aqui! Por favor, siga-me.",
  [1143563228987904] = "Acho que, além de utilizá-lo para o comércio ferroviário, vender estes vinhos finos para locais mais próximos também pode ser uma boa escolha!",
  [1143563228987648] = "Meu Senhor, obrigado por trazer esperança e um amanhã a esta terra.",
  [1143563228987136] = "Cor perfeita, aroma perfeito. Este vinho se tornará um dos vinhos mais famosos da rota comercial!",
  [1143563228986880] = "<P_Heart> (...Ele adormeceu...) </>",
  [1143563228984832] = "Suspiro, não importa, tenho que ir rápido.",
  [1143563228984576] = "Você está falando dos meus gatinhos? Se ao menos... eles pudessem derrubar menos das minhas poções.",
  [1143563228984320] = "Romance? E seus amigos?",
  [1143563228984064] = "Em outras palavras, você não tem absolutamente nenhuma hostilidade comigo? E você não quer me usar? Isso é verdadeiramente novo.",
  [1143563228983808] = "Mas você conseguiu me encontrar através do broche...",
  [1143563228983552] = "Para os vampiros ou os caçadores de recompensas que eles contrataram, sou como um pedaço de ar, completamente invisível.",
  [1143563228983296] = "Eu tenho um item Beyonder que pode apagar minha existência da mente daqueles com más intenções.",
  [1143563228980736] = "Essa perseguição e caça cuidadosamente planejadas, no final, se transformaram em uma armadilha onde o assassino caiu direto na rede.",
  [1143563228980480] = "A garota foi para o canto. O que ela enfrentou não foi um beco sem saída, mas policiais de guarda armados.",
  [1143563228980224] = "Um enorme holofote se acendeu de repente, iluminando a noite fora da delegacia como se fosse dia.",
  [1143563228979968] = "Acredito que mesmo sem meu lembrete, você se sairá bem... Boa sorte...",
  [1143563228979712] = "Não quero perder esta aposta, então mudei um pouco o horário...",
  [1143563228979456] = "<P_Heart> (Milagre? As escrituras da Igreja do Louco dizem que o Louco governa milagres...) </>",
  [1143563228979200] = "<P_Heart> (Se eu pudesse estalar os dedos e limpá-lo milagrosamente, seria ótimo.) </>",
  [1143563228978944] = "<P_Heart> (Um terreno tão grande, mesmo que eu contratasse pessoas para limpá-lo, levaria meses.) </>",
  [1143563228978432] = "Com o seu poder, talvez você possa construir o castelo imediatamente!",
  [1143563228978176] = "Eu servi um Abençoado de um deus?! Meu Senhor, por favor, fique tranquilo, com certeza vou manter minha boca fechada! Por favor, permita-me servi-lo pelo resto da minha vida!",
  [1143563228977920] = "Isto é – um milagre de um deus.",
  [1143563228977664] = "Isso... que tipo de poder é esse? Num instante...",
  [1143563228973312] = "<P_Heart> (Sorri) </> Sol... luz quente... combina muito bem com ele.",
  [1143563228973056] = "Ele é muito querido pelo seu povo agora; ele escolheu \"Sun\" como seu codinome.",
  [1143563228972800] = "Naquela época, eu sabia que ele poderia trazer um tipo diferente de esperança para a Cidade de Prata.",
  [1143563228972544] = "<P_Heart> (Silêncio por um momento) </> Ele era diferente desde criança. Outras crianças temiam a escuridão, mas ele sempre olhava para o céu. Outras crianças obedeceram ao destino, mas ele continuou perguntando por quê.",
  [1143563228972288] = "Ele agora é bispo da Igreja do Louco. A Nova Cidade de Prata mudou-se para perto do Império Bairam, e Derrick reconstruiu sua casa com seus membros do clã.",
  [1143563228972032] = "Também sei que ele ora a outros deuses.",
  [1143563228971776] = "Claro que me lembro. Aquela criança e eu brigamos lado a lado muitas vezes.",
  [1143563228971520] = "Anciã Lovia, você ainda se lembra de Derrick?",
  [1143563228971264] = "<P_Heart> (Levanta os olhos) </> Só lembro que para cada alma que agrupo, existe mais uma possibilidade de sair da escuridão.",
  [1143563228971008] = "Na Terra Abandonada dos Deuses, não há qualificação para falar sobre arrependimento.",
  [1143563228970752] = "Você já se arrependeu? Obtendo poder desta forma?",
  [1143563228970496] = "<P_Heart> (Suavemente) </> A habilidade de criar golems... vem de outra.",
  [1143563228970240] = "Existem outras almas?",
  [1143563228969984] = "Certa vez, isso me ajudou a lutar contra espíritos malignos. Porém, deve me proteger e não pode lutar com força total.Sequência",
  [1143563228969728] = "Você já lutou contra isso muitas vezes?",
  [1143563228969472] = "<P_Heart> (Olhando para longe) </> Ele também pode pegar luz emprestada para esconder e ocultar a malícia.",
  [1143563228969216] = "A Espada do Amanhecer pode purificar as trevas. O Silver Rapier pode contornar barreiras para atacar diretamente.",
  [1143563228968960] = "Quais habilidades um Cavaleiro de Prata possui?",
  [1143563228968704] = "Aquela alma era um Cavaleiro de Prata Sequência 3 em vida, e após a morte... ainda tem a força de um Sequência 4.",
  [1143563228968448] = "<P_Heart> (Silêncio por um momento) </> Isso foi há muito tempo.",
  [1143563228968192] = "Na história, vi um espírito maligno em uma armadura prateada protegendo você.",
  [1143563228967936] = "<P_Heart> (Olhos cinza claros levantados levemente) </> Como você sabe?",
  [1143563228967680] = "Anciã Lovia, aquele Cavaleiro de Prata que você pastoreia... pode me contar sobre isso?",
  [1143563228967424] = "Mas para alguém como eu, já é um sonho.",
  [1143563228967168] = "<P_Heart> (Silencioso) </> Sim. É simples.",
  [1143563228966912] = "Parece maravilhoso.",
  [1143563228966656] = "Quando o sol se pôr, leve-os para casa um por um.",
  [1143563228966400] = "<P_Heart> (Olhando para longe) </> Então cante uma música, bem, muito lenta; não importa se estou desafinado, as ovelhas não vão rir de mim de qualquer maneira.",
  [1143563228966144] = "E então... é só observá-los, observar a luz do sol brilhando na lã, tornando-a dourada.",
  [1143563228965632] = "<P_Heart> (Suavemente) </> Eu quero sentar lá e pastorear ovelhas de verdade. Os brancos, caminhando lentamente na grama, de cabeça baixa comendo, ocasionalmente olhando para \"baa\".",
  [1143563228965376] = "<P_Heart> (Cantos da boca ligeiramente levantados) </> Colinas, talvez. Do tipo com gramados verdes. Não grama escura... mas verde real e suave.",
  [1143563228965120] = "Imagine só?",
  [1143563228964864] = "<P_Heart> (Silêncio por um longo tempo) </> ... Não pensei nisso.",
  [1143563228964608] = "Anciã Lovia, se... você pudesse deixar a Terra Abandonada dos Deuses, o que você mais gostaria de fazer?",
  [1143563228964352] = "Diga às pessoas lá fora... vivam bem. Sob a luz do sol, dê mais algumas olhadas neste mundo para nós.",
  [1143563228964096] = "Isso é bom.",
  [1143563228963840] = "Todo mundo sabe. Seu nome está gravado no monumento da Nova Cidade de Prata, junto com o Chefe Colin.",
  [1143563228963584] = "<P_Heart> (Olha para a escuridão eterna) </> Eu não traí a Cidade de Prata... nunca.",
  [1143563228963328] = "Chefe Colin Ilíada... ele morreu em batalha na Corte do Rei Gigante. Mas todos na Cidade de Prata se lembram dele e de você também.",
  [1143563228963072] = "<P_Heart> (Suavemente) </> Colin... o Chefe viu?",
  [1143563228962816] = "Os moradores da Nova Cidade de Prata vivem muito felizes agora; eles têm seus próprios campos e casas e podem se comunicar e negociar normalmente com pessoas de outros países.",
  [1143563228962560] = "Luz solar... a luz solar pela qual esperamos três mil anos...",
  [1143563228962304] = "Há luz solar, plantas verdes e alimentação normal; as crianças não precisam mais comer carne de monstro.",
  [1143563228962048] = "É verdade. O Sr. Louco abriu a passagem para o mundo exterior, e os residentes da Cidade de Prata migraram para as terras férteis perto do Império Balam.",
  [1143563228961792] = "...... O que você disse?",
  [1143563228961536] = "Anciã Lovia, a Cidade de Prata já deixou a Terra Abandonada dos Deuses. Agora, na Nova Cidade de Prata, a luz do sol pode brilhar.",
  [1143563228961280] = "Há muito que não consigo distinguir a fronteira entre a loucura e a sobriedade. Mas sei que enquanto estiver vivo não deixarei a Cidade de Prata cair nas trevas.",
  [1143563228961024] = "<P_Heart> (Olhos cinzentos claros caem ligeiramente) </> Corrupção? Na Cidade de Prata, até a respiração está sendo corrompida.",
  [1143563228960768] = "Mas afinal o Verdadeiro Criador é um deus do mal, você não está preocupado em ser corrompido?",
  [1143563228960512] = "<P_Heart> (Olhando para longe) </> Às vezes, a fé é um meio, não um fim.",
  [1143563228960256] = "Canto Seu nome honorífico, mas nunca esqueci quem sou. Sou um Ancião da Cidade de Prata, membro do Conselho dos Seis e... alguém que quer encontrar uma saída para o meu povo na escuridão.",
  [1143563228960000] = "Por mais de dois mil anos, os verdadeiros deuses nunca demonstraram misericórdia conosco. Só Ele me respondeu na escuridão, trazendo... esperança.",
  [1143563228959744] = "<P_Heart> (Silencioso) </> O que você acha que é fé?",
  [1143563228959488] = "Anciã Lovia, ouvi dizer que você uma vez adorou o Verdadeiro Criador?",
  [1143563228959232] = "Se você não economizou dinheiro suficiente para a escola, espere um pouco mais. Ou vá para uma fábrica menor para ser aprendiz e aprender enquanto trabalha. Acho que, contanto que você trabalhe duro, você definitivamente poderá viver uma vida um pouco melhor do que agora.",
  [1143563228958976] = "O planejamento de longo prazo é necessário para que você não se arrependa de ter tomado o caminho errado... mas você também deve permitir que a vida tome alguns desvios ocasionalmente.",
  [1143563228958720] = "Isso é incrível, parece que você tem um plano muito bom para o seu futuro.",
  [1143563228958464] = "<P_Heart> (Acena com a cabeça) </> Eles têm os melhores laboratórios lá. Mas a mensalidade é muito cara, então tenho que economizar muito dinheiro agora.",
  [1143563228958208] = "Isso significa ir para uma grande empresa em Backlund?",
  [1143563228957952] = "Agora só consigo consertar relógios de bolso e fazer pequenos brinquedos. Mas mais tarde... Quero projetar grandes motores a vapor para serem usados ​​em fábricas, ou em trens, ou em lugares ainda mais incríveis.",
  [1143563228957696] = "<P_Heart> (Olhos brilhando levemente) </> Sim. Não um reparador, mas um designer. Ser capaz de projetar minhas próprias máquinas e fazê-las realmente girar.",
  [1143563228957440] = "Parece interessante?",
  [1143563228957184] = "......Eu quero ser um mecânico a vapor.",
  [809242974022912] = "Rugido?",
  [1143563228956928] = "O que você quer fazer depois da formatura?",
  [1143563228956672] = "O dinheiro deve ser gasto em lugares úteis. Isto é o que Benson me ensinou.",
  [1143563228956416] = "Não todos os dias. É que... cada centavo tem a sua utilidade. O dinheiro economizado pode comprar um livro de referência ou deixar meu irmão trabalhar um turno de horas extras a menos.",
  [1143563228956160] = "Você calcula assim todos os dias?",
  [1143563228955904] = "Se a distância não for grande, você pode caminhar mais em vez de usar o transporte público. Embora você só possa economizar um ou dois centavos por dia, isso representa uma grande soma de dinheiro.",
  [1143563228619520] = "Jovem Mestre...",
  [1143563228893440] = "A maioria deles foi sorteada no turno da noite. Eles gostam de jogar cartas e eu gosto de desenhar.",
  [1143492898233600] = "Estágio de mudança",
  [1143563228954368] = "......Deixe-me ensinar um truque para comprar frutas.",
  [1143563228954112] = "As despesas têm sido altas ultimamente, me pergunto se há alguma maneira de economizar dinheiro...",
  [1143563228953856] = "Ele é assim mesmo. Escondendo tudo nessas piadas sem graça.",
  [1143563228953600] = "Ele sofria com a falta de educação, então, assim como apoiou Klein para ir para a universidade, ele apoiou meu sonho.",
  [1143563228953344] = "<P_Heart> (Acena com a cabeça) </> Ele disse que Melissa se tornaria a maior mecânica a vapor de Backlund.",
  [1139165182367488] = "Eu vejo...",
  [1143563228953088] = "Ele é um bom irmão que pensa nos irmãos mais novos.",
  [1143563228952832] = "Sim. Mas ele nunca reclamou. Então também tentamos não deixá-lo preocupado e demos mais tempo para ele descansar.",
  [1143563228952576] = "Deve ter sido muito difícil.",
  [1143563228952320] = "Mas por um tempo, ele raramente falava sobre isso. A situação no Continente Sul era ruim, a empresa demitiu muitas pessoas e, para manter o emprego, ele teve que aceitar tarefas mais pesadas, muitas vezes fazendo horas extras e fazendo viagens de negócios para locais com ambientes adversos.",
  [1143563228952064] = "Ele disse que a inteligência do Sr. Frank é inferior à de um babuíno de cabelos cacheados – se ele estiver em boas condições.",
  [1143563228951808] = "Não, ele gosta de contar piadas para o pai. Especialmente sobre o nosso antigo senhorio, Sr. Frank.",
  [1143563228951552] = "Então ele deve parecer muito sério?",
  [1143563228951296] = "Ele... parece mais velho do que sua idade real. Não porque ele seja velho, mas porque... ele se preocupa com muitas coisas.",
  [1143563228951040] = "Benson? Ele trabalhava em uma empresa de importação e exportação com salário semanal de 1 libra e 10 xelins.",
  [1143563228950784] = "Melissa, você pode me contar sobre seu irmão Benson?",
  [1143563228950528] = "<P_Heart> (Balança a cabeça) </> Se ele não diz isso, ele tem seus motivos. Nossa família é assim; estamos mais acostumados a cuidar uns dos outros silenciosamente... Já chega.",
  [1143563228950272] = "Você não perguntou a ele o motivo de suas mudanças recentes?",
  [1143563228950016] = "<P_Heart> (Acena com a cabeça) </> Ele só... não é muito bom em dizer isso diretamente.",
  [1143563228949760] = "Ele foi muito bom para você.",
  [1143563228949504] = "<P_Heart> (Corando) </> Quase comi tudo... Ele realmente fez muito bem, exceto que usou muitos temperos caros...",
  [1143563228949248] = "Surpreendentemente bom. Ele disse que já havia roubado alguns pedaços – “o privilégio de um chef” – mas eu sei que isso é mentira; ele definitivamente não comeu muito.",
  [1143563228948992] = "Qual foi o gosto?",
  [1143563228948736] = "Outro exemplo, eu cozinhava tudo em casa, mas naqueles dias ele de repente fez uma panela grande de guisado de ervilha tenro com cordeiro.",
  [1143563228948480] = "Por exemplo, ele saía repentinamente para correr no meio da noite ou desistia da entrevista com um professor da Universidade de Tingen que havia preparado há muito tempo para encontrar um emprego bem remunerado... Ele deve ter desejado que vivêssemos melhor.",
  [1143563228948224] = "Estranho? O que você quer dizer?",
  [1143563228947968] = "Sim, Benson trabalhava fora e Klein e eu nos concentramos em nossos estudos. Mas ele era... um pouco estranho naquela época.",
  [1143563228947712] = "Você e Klein moraram em Tingen antes?",
  [1143563228947456] = "<P_Heart> (Tímido) </> Fazer esse tipo de trabalho me deixa muito relaxado.",
  [1143563228947200] = "Está tudo bem, está tudo bem. A escola ensina a teoria básica, eu só... coloco em prática.",
  [1143563228946944] = "Você é incrível. Isso deve ser complicado, certo?",
  [1143563228946688] = "O princípio é simples; trata-se apenas de transmitir energia cinética através de engrenagens para controlar o ritmo, de modo que os movimentos de salto e caminhada sejam regulares.",
  [1143563228946432] = "Juntei tudo com materiais que a escola não queria e coisas que peguei na estrada. Engrenagens, ferro enferrujado, molas, mecanismos de relógio...",
  [1143563228946176] = "Parece tão requintado, como você fez isso?",
  [1143563228945920] = "...... Você notou? Isso é uma coisinha que fiz para me divertir.",
  [1143563228945664] = "Isto é uma... boneca? Você mesmo fez isso?",
  [1143563228945408] = "Uh... da próxima vez, definitivamente da próxima vez!",
  [1143563228945152] = "Eu sabia que você me entenderia! Você quer ver o cogumelo que acabei de cultivar? Pode imitar vozes humanas! Embora só possa dizer \"ajuda\" por enquanto...",
  [1143563228944896] = "<P_Heart> (Silêncio por um momento) </> O que você diz parece fazer algum sentido.",
  [1143563228944640] = "Eu sei que minha pesquisa parece uma loucura. Mas neste mundo, as maiores invenções parecem malucas no início. Não é?",
  [1143563228944384] = "A Mãe misericordiosa deu-nos a capacidade de mudar o mundo; se não o usarmos, será o maior desperdício.",
  [1143563228944128] = "Se eu não fizesse investigação porque tinha medo de perder o controlo, então problemas como a fome, a pobreza e as doenças nunca seriam resolvidos.",
  [1143563228943872] = "O maior risco? Acho que está impedindo a tentativa.",
  [1143563228943616] = "Então qual você acha que é o maior risco?",
  [1143563228943360] = "O importante é que após cada perda de controle eu saiba como melhorar na próxima vez.",
  [1143563228943104] = "Temer? Por que ter medo? A perda de controle é apenas parte do processo. Assim como uma criança que está aprendendo a andar cairá, os pesquisadores também cometerão erros.",
  [1143563228942848] = "Você não está com medo?",
  [1143563228942592] = "Certa vez, as vinhas que cultivei cresceram muito rápido e quase envolveram todo o navio. Outra vez, aqueles pequeninos começaram a se reproduzir sozinhos e a correr por todo o navio...",
  [1143563228942336] = "Algumas vezes.",
  [1143563228942080] = "Sua pesquisa já saiu do controle?",
  [1143563228941824] = "Talvez porque... algumas variedades têm efeitos colaterais significativos. Como aqueles esporos que fazem as pessoas perderem temporariamente a capacidade de se mover; Originalmente, eu só queria usá-los para lidar com piratas!",
  [1143563228941568] = "Então por que está associado a “veneno”?",
  [1143563228941312] = "Por exemplo, aquele tipo de cogumelo que faz as feridas cicatrizarem rapidamente e as algas marinhas que podem purificar a água – todas essas coisas são úteis!",
  [1143563228941056] = "<P_Heart> (Suspiros) </> Já disse isso muitas vezes, não sou um especialista em toxinas. Sou muito bom em fazer com que plantas e animais produzam certos compostos especiais.",
  [1143563228940800] = "Sr. Frank, você poderia me falar sobre suas habilidades? Por exemplo, como você conseguiu o título de “Especialista em Toxinas”?",
  [1143563228940544] = "As pessoas dizem isso com frequência! Mas acho que é um elogio, né?",
  [1143563228940288] = "Sr. Frank, alguém já lhe disse que sua imaginação é muito rica?",
  [1143563228940032] = "Atualmente estou pesquisando adicionar limões a ele! Assim será um prato à parte, sem necessidade de tempero extra!",
  [1143563228939776] = "Então, como você planeja resolver o problema do sabor?",
  [1143563228939520] = "Então combinei os genes dos peixes marinhos com o repolho. O resultado é que pode crescer no mar, mas tem gosto de peixe.",
  [1143563228939264] = "Sim! Os vegetais frescos são difíceis de conservar no mar, por isso pensei, se os vegetais pudessem adaptar-se ao ambiente marinho como os peixes, não seríamos capazes de os cultivar na superfície do mar?",
  [1143563228939008] = "Espere, vegetais que produzem escamas de peixe?",
  [1143563228938752] = "Muitos, muitos! Por exemplo, cogumelos que podem se mover por conta própria, vegetais que produzem escamas de peixe e—",
  [1143563228938496] = "Qual é a sua conquista de pesquisa de maior orgulho?",
  [1143563228938240] = "Claro que é normal! Afinal, sou apenas um pesquisador comum.",
  [1143563228937984] = "Isso parece normal.",
  [1143563228937728] = "Mas se eu tivesse que dizer, gosto de observar o crescimento das plantas. Observar uma semente brotar do solo, crescer lentamente, brotar folhas, florescer e dar frutos – esse processo é simplesmente maravilhoso.",
  [1143563228937472] = "Pesquisa é meu hobby.",
  [1143563228937216] = "Sr. Frank, além da pesquisa, você tem algum outro hobby?",
  [1143563228936960] = "Claro! Quem recusaria um navio que pensa por si, navega por si e se alimenta?",
  [1143563228936704] = "......Tem certeza que ela vai gostar dessa “recompensa”?",
  [1143563228936448] = "<P_Heart> (Movido) </> Então devo retribuir a ela com os resultados da minha pesquisa! Assim que eu descobrir como transformar a nave inteira em um organismo vivo, o Futuro nunca mais precisará atracar para buscar suprimentos!",
  [1143563228936192] = "Ela é uma boa pessoa. Apesar de sempre ter um olhar frio, ela nunca me impede de fazer pesquisas como aquela galera da Igreja Mãe Terra.",
  [1143563228935936] = "Sr. Frank, que tipo de pessoa você acha que a Capitã Cattleya é?",
  [1143563228935680] = "Mas eu só quero que o navio seja autossustentável. Não é uma estratégia de sobrevivência brilhante?",
  [1143563228935424] = "É intermitente. Ainda estou pesquisando como estabilizar o rendimento. A capitã Cattleya disse que se eu deixasse o navio dela “doente” novamente, ela me jogaria no mar para alimentar os peixes.",
  [1143563228935168] = "O “Futuro” ainda está produzindo leite agora?",
  [1143563228934912] = "Embora a capitã estivesse muito zangada naquele momento, percebi que ela ficou realmente muito surpresa. Um navio que pode produzir leite sozinho – isso é único no mundo inteiro!",
  [1143563228934656] = "Foi nessa época que aqueles meus pequeninos começaram a procriar, enterraram-se no convés e aí o “Futuro” começou a produzir leite!",
  [1143563228934144] = "Você sabe? O próprio “Futuro” também é objeto da minha pesquisa!",
  [1143563228933888] = "É ótimo! O capitão me dá muita liberdade. Posso fazer meus próprios experimentos e, embora o espaço seja um pouco pequeno, é o suficiente!",
  [1143563228933632] = "Sr. Frank, como é viver no \"Futuro\"?",
  [1143563228933376] = "Os efeitos colaterais são... <P_Heart> (Pensando seriamente) </> Algumas pessoas veem coisas que são muito interessantes, então não querem acordar. Mas isso mostra que é eficaz, não é?",
  [1143563228933120] = "E quanto aos efeitos colaterais?",
  [1143563228932864] = "Sim! Depois de comê-lo, você vê muitas coisas interessantes e depois esquece que não consegue dormir. Muito razoável, certo?",
  [519041160661760] = "Suspirar...",
  [1143563228932608] = "Tratar a insônia?",
  [519041160701952] = "Sozinho, soluço...",
  [1143563228932352] = "Por exemplo, aquele tipo de cogumelo que causa alucinações em quem toca – eu só queria usar para tratar insônia!",
  [1143563228932096] = "Bem, admito que algumas das variedades que cultivei... têm de facto alguns efeitos secundários.",
  [1143563228931840] = "É assim que os outros me chamam aleatoriamente. Sou claramente um mestiço e melhorador agrícola.",
  [1143563228931584] = "Então de onde veio o título “Especialista em Toxinas”?",
  [519041160887296] = "Estou pronto para ouvir a qualquer momento.",
  [1143563228931328] = "Embora ela às vezes fique pálida quando vê meus resultados, ela nunca me impede... uh, às vezes ela me impede um pouco, eu acho.",
  [1143563228931072] = "Ela me deu um lugar para fazer experimentos, permitindo-me continuar minha pesquisa.",
  [519041160984832] = "Hum...",
  [1143563228930816] = "Isso é muito simples de dizer. Depois que deixei a Igreja, fiquei à deriva no mar por um tempo e mais tarde conheci a Capitã Cattleya.",
  [1143563228930560] = "Sr. Frank, você pode me contar sua história? Como você se tornou o primeiro imediato do 'Futuro'?",
  [1143563228930304] = "Consequências? Claro que haverá consequências. Boas consequências – todos podem comer até se fartar. Isso é o suficiente!",
  [1143563228930048] = "Sr. Frank, você já pensou que sua pesquisa poderia ter algumas consequências?",
  [1143563228929792] = "Disseram que eu profanei os limites da vida. Mas a vida não tem limites! Quando a Mãe criou todas as coisas, ela não esperava que elas se fundissem e se concretizassem?",
  [1143563228929536] = "Mas eu só queria tornar a carne bovina mais barata para que mais pessoas pudessem comer até se fartar. Não é isso que a Mãe espera ver?",
  [1143563228929280] = "......Eu certamente posso entender a reação deles.",
  [519041161272576] = "EU...",
  [1143563228929024] = "Passei dois anos inteiros pesquisando esse assunto. E o resultado? O pessoal da Igreja me mandou para a Inquisição!",
  [1143563228928768] = "<P_Heart> (Animadamente) </> Sim! Pense nisso: se as vacas pudessem crescer da terra como o trigo, os agricultores não teriam que gastar tanta energia para criá-las! Num campo, espigas de trigo crescem em cima e pernas de vaca embaixo – que desenho perfeito!",
  [519041161374208] = "Não podemos.",
  [519041161400320] = "Você é o idiota! Mamãe nunca mentiu para mim; meu desejo se tornará realidade.",
  [519041161429760] = "E então?",
  [1143563228928512] = "Então você tentou cruzar um touro com trigo?",
  [1143563228928256] = "Cresci na fé da Mãe Terra. A Mãe misericordiosa nos ensinou: todas as coisas coexistem, os ciclos de vida. Acabei de pensar: como posso praticar melhor a vontade dela?",
  [1143563228928000] = "Desentendimentos? Não, isso não foi um desentendimento. É que eles não entenderam!",
  [1143563228927744] = "Sr. Frank, ouvi dizer que uma vez você teve alguns... desentendimentos com a Igreja da Mãe Terra?",
  [1143563228927488] = "Afinal, sou apenas um cachorro. E é exatamente nisso que sou melhor.",
  [1143563228927232] = "Por exemplo, ficar ao lado de Audrey, guardar tudo o que ela valoriza e manter um coração simples neste mundo.",
  [1143563228926976] = "Significa: farei o que puder do meu jeito.",
  [1143563228926720] = "<P_Heart> (Pensativamente) </> Então essa frase significa...",
  [1143563228926464] = "Sou apenas um cachorro – esta frase é a verdade, não uma desculpa.",
  [1143563228926208] = "Não preciso me tornar um humano para provar meu valor, nem preciso fingir ser apenas um cachorro comum para fugir de responsabilidades.",
  [1143563228925952] = "Mas um cachorro também pode ser inteligente, pensar e escolher seu próprio modo de vida.",
  [1143492898195200] = "Sobre fé",
  [1143492898202368] = "Limpe o espelho",
  [1143563228925696] = "O mal-entendido dos humanos é que eles sempre acham que um cachorro deve ser estúpido, simples e capaz apenas de abanar o rabo.",
  [1143563228925440] = "Sim. Mas isso não é “não é como um cachorro”, é “um cachorro também pode fazer isso”.",
  [1143563228925184] = "Mas você pode falar, ler psicologia e entrar em sonhos...",
  [1143563228924928] = "Essas coisas, mesmo em alta Sequência , não são fáceis de mudar.",
  [1143563228924672] = "Vou tirar o cabelo, correr atrás do rabo, deitar para tomar sol e girar animadamente quando ouço a palavra 'sair'.",
  [1143563228924416] = "Claro, sou realmente um cachorro.",
  [1143563228924160] = "Sra. Susie, você costuma dizer 'Eu sou apenas um cachorro', você realmente acha isso?",
  [1143563228923904] = "Mas, estranhamente, quanto mais aprendo, mais sinto que não preciso aprender tanto. Às vezes, só preciso deitar aos pés dela e apoiar a cabeça nela.",
  [1143563228923648] = "Para entender melhor os humanos e acompanhar melhor Audrey.",
  [1143563228923392] = "Então, por que você estuda psicologia?",
  [1143563228923136] = "Os humanos inventaram tantas teorias complexas, mas muitas vezes ignoram a intuição mais simples.",
  [1143563228922880] = "Mas posso cheirar com meu nariz se alguém dormiu bem na noite passada e posso distinguir se uma risada é real ou falsa ouvindo com meus ouvidos.",
  [1143563228922624] = "Eles passam muito espaço discutindo 'autocognição', 'traumas de infância' e 'conflitos subconscientes'.",
  [1143563228922368] = "Não está certo? O que está errado?",
  [1143563228922112] = "Mas sempre sinto que os livros de psicologia humana às vezes não estão certos.",
  [1143563228921856] = "Sim. Audrey diz que os livros são coisas boas e que devemos ler mais.",
  [1143563228921600] = "Sra. Susie, ouvi dizer que você está estudando psicologia?",
  [1143563228921344] = "Além disso, Audrey disse que a coisa mais poderosa do Espectador Caminho não é lutar, mas sim fazer o oponente não querer lutar com você. Acho que isso faz muito sentido.",
  [1143563228921088] = "Afinal, quando um golden retriever abana o rabo para você, quem pode realmente ficar com raiva?",
  [1143563228920832] = "Então eu poderia me deitar, abanar o rabo e olhar para ele com os olhos mais inocentes.",
  [1143563228920576] = "E se ele fosse forçado a isso?",
  [1143563228920320] = "No entanto, duvido que ele lutaria comigo. Sr. Alfred é o tipo de pessoa que é muito exigente com as regras – por que ele brigaria com um cachorro?",
  [1143563228920064] = "E então, depois que ele passou, eu escapuli silenciosamente.",
  [1143563228919552] = "O Árbitro é bom em regras, ordem e supressão; o Espectador é bom em observação e orientação. Se ele realmente quisesse me pegar, eu provavelmente usaria primeiro 'Invisibilidade Psicológica' para parecer uma pedra.",
  [1143563228919296] = "Nossos caminhos são diferentes, então não devemos comparar assim.",
  [1143563228919040] = "Quero dizer... teoricamente, você é mais forte que ele?",
  [1143563228918784] = "Eu sou apenas um cachorro, por que treinaria com um humano?",
  [1143563228918528] = "<P_Heart> (Suprimindo uma risada) </> Isso significa que se um dia vocês dois brigassem...",
  [1143563228918272] = "Parece que é esse o caso.",
  [1143563228918016] = "Isso não significa... que você tem um Sequência superior ao do Sr. Alfred da família Earl Hall?",
  [1143563228917760] = "Sim. Audrey diz que estou progredindo muito rapidamente.",
  [1143563228917504] = "Dona Susie, você avançou?",
  [1143563228917248] = "Ela precisa de um observador imperceptível, e posso encontrar meu lugar aqui; Também posso ver sua exaustão e lembrá-la de parar e descansar. Estamos sempre ajudando uns aos outros.",
  [1143563228916992] = "Os humanos sempre pensam que a cura é unilateral: os médicos curam os pacientes, os fortes ajudam os fracos. Mas Audrey me ensinou: relacionamentos verdadeiros são ver um ao outro.",
  [1143563228916736] = "Na verdade, não creio que isso seja aconselhamento psicológico, apenas preocupação com ela como amiga.",
  [1143563228916480] = "Então como você responde?",
  [1143563228916224] = "Ela ficará atordoada por um momento, depois rirá e dirá: “Susie, quando você aprendeu aconselhamento psicológico?”",
  [1143563228915968] = "Às vezes deito-me a seus pés, apoio a cabeça em seus joelhos e pergunto: \"Audrey, o ritmo da sua respiração está errado hoje. Você está cansado?\"",
  [1143563228915712] = "Audrey é uma Beyonder do Espectador Caminho; ela é muito boa em observar os outros, mas muitas vezes se esquece de observar a si mesma. Ela pode chorar pela dor dos outros, mas esconde bem seu próprio cansaço.",
  [1143563228915456] = "Foi ela também quem não me tratou como um monstro depois que aprendi a falar.",
  [1143563228915200] = "Ela é a primeira pessoa a chamar meu nome, aquela que não se importou que eu fosse um presente grátis.",
  [1143563228914944] = "Sra. Susie, aos seus olhos, que tipo de pessoa é a Srta. Audrey?",
  [1143563228914688] = "Na verdade, isso é algo que acontece naturalmente depois de muito tempo juntos.",
  [1143563228914432] = "Isto é verdadeiramente mágico.",
  [1143563228914176] = "Às vezes ela não diz nada, apenas olha para mim e sorri. Eu posso entender.",
  [1143563228913920] = "Às vezes ela sorri, dá um tapinha na minha cabeça e diz: “Obrigada, Susie”.",
  [1143563228913664] = "Ela diz alguma coisa?",
  [1143563228913408] = "Desde então, toda segunda-feira, às três da tarde, eu mesmo vou até lá. Às vezes ela nem falou ainda e eu já estou deitado.",
  [1143563228913152] = "E então eu entendi. Saí, deitei-me à porta e apurei os ouvidos.",
  [1143563228912896] = "Ela parecia estar dizendo: 'Susie, preciso ficar um pouco sozinha. Você pode me ajudar a vigiar a porta?",
  [1143563228912640] = "Na primeira vez, Audrey olhou para mim com uma expressão difícil de explicar. Mas também pude ver confiança em seus olhos.",
  [1143563228912384] = "Mas eu também sou a família dela. Acho que há muitas coisas sobre as quais os membros da família não precisam perguntar muito.",
  [1143563228912128] = "Claro que estou curioso. Sou um cachorro e a curiosidade é a nossa natureza.",
  [1143563228911872] = "Você sabe o que a senhorita Audrey está fazendo lá dentro? Você não está curioso?",
  [1143563228911616] = "Você observa com muito cuidado.",
  [1143563228911360] = "Sra. Susie, toda segunda-feira à tarde, você guarda a porta do quarto da Srta. Audrey?",
  [1143563228911104] = "Isso me convém melhor do que lutar e matar.",
  [1143563228910848] = "Mas agora é muito bom ler livros, estudar o oculto e ensinar vocês, jovens.",
  [1143563228910592] = "Só quando meu cabelo ficou grisalho é que percebi que o conhecimento que eu entendia naquela época estava apenas no nível introdutório do ocultismo.",
  [1143563228910336] = "Um pouco. Afinal, quando somos jovens, todos se acham especiais.",
  [1143563228910080] = "Você já se arrependeu de não ter avançado?",
  [1143563228909824] = "No entanto, as habilidades de Sequência 9 são limitadas e são principalmente conhecimentos teóricos.",
  [1143563228909568] = "O fluxo de espiritualidade , vestígios dos segredos extraordinários e ocultos.",
  [1143563228909312] = "Você pode entendê-lo como alguém que “vê” melhor.",
  [1143563228909056] = "Pryer Misterioso, bem...",
  [1143563228908800] = "Sr. Neil, o 'Espreitador de Mistérios' tem alguma habilidade especial?",
  [1143563228908544] = "<P_Heart> (Sorrisos) </> Se houver uma chance, ficarei muito feliz em tocar um para você.",
  [1143563228908288] = "Minha esposa disse uma vez que o piano é um instrumento que traz beleza.",
  [1143563228908032] = "É que todos em Blackthorn foram muito atenciosos, temendo que pudessem tocar nas minhas tristes lembranças, então, eventualmente, ninguém mencionou querer mais ouvir músicas.",
  [1143563228907776] = "<P_Heart> (Balança a cabeça) </> Não precisa se desculpar, está tudo no passado.",
  [1143563228907520] = "……Desculpe.",
  [1143563228907264] = "Mais tarde, minha esposa faleceu e fiquei muito tempo deprimido por causa disso.",
  [1143563228907008] = "Por que você parou de jogar mais tarde?",
  [1143563228906752] = "No entanto, na sala de recreação Vigias Noturnos ', muitas vezes tocava músicas para os membros da equipe.",
  [1143563228906496] = "Nível de músico – você achou que eu diria isso? Haha, na verdade, é muito mediano, nem metade da qualidade da minha esposa.",
  [1143563228906240] = "Entendo... quão bem você joga?",
  [1143563228905984] = "Minha falecida esposa amava muito música e foi ela quem me ensinou a tocar.",
  [1143563228905728] = "Sr. Neil, ouvi dizer que você toca piano?",
  [1143563228905472] = "O proprietário do Evil Dragon Bar, um capitão aposentado abençoado pelo Vento. Aquele velho fica bêbado todos os dias, mas quando se trata de negócios sérios, ele é mais confiável do que qualquer um.",
  [1143563228905216] = "Quem é Swain?",
  [1143563228904960] = "Da última vez, um Abençoado pelo Vento perdeu o controle no Distrito Leste, e fomos Swain e eu quem resolveu o problema.",
  [1143563228904704] = "Assim que encontrarmos um companheiro de equipe perdendo o controle, independentemente do time ao qual ele pertença, entraremos em ação para ajudar.",
  [1143563228904448] = "Parece que o relacionamento não é tão ruim assim?",
  [1143563228904192] = "Jovens, de diferentes religiões, há sempre um momento em que não querem admitir a derrota. Mas no final, somos todos pessoas que guardam Tingen nas sombras.",
  [1143563228903936] = "Existe competição entre Vigias Noturnos e os Mandated Punishers?",
  [1143563228903680] = "Oficial Beyonders da Igreja do Senhor das Tempestades, cada um de nós lida com uma parte dos incidentes em Tingen.",
  [1143563228903424] = "Sr. Neil, você conhece os Punidores Mandatados?",
  [1143563228903168] = "Acontece que ele é muito sério de vez em quando; alguém precisa ajudá-lo a se soltar.",
  [1143563228902912] = "Ele é o tipo de pessoa que assume toda a responsabilidade sobre si. Aprender com ele é bom para vocês, jovens.",
  [1143563228902656] = "Não é verdade? Ele tem cada vez mais o comportamento de um capitão agora.",
  [1143563228902400] = "Eu não posso dizer...",
  [1143563228902144] = "Quando ele veio para Blackthorn pela primeira vez, assim como todo recém-chegado, ele não entendeu nada. Fui eu quem lhe ensinou os cursos de ocultismo.",
  [1143563228901888] = "Quando me tornei Vigia Noturno , Dunn ainda era uma criança!",
  [1143563228901632] = "Você o viu crescer?",
  [1143563228901376] = "Eu o observei crescer passo a passo, passando de um membro comum.",
  [1143563228901120] = "Ele é uma pessoa confiável.",
  [1143563228900864] = "Sr. Neil, que tipo de pessoa você acha que o Capitão Dunn é?",
  [1143563228900608] = "Sempre equipamento, equipamento! O conhecimento também é muito importante!",
  [1143563228900352] = "<P_Heart> (Olhos iluminam) </> Claro! Contém alguns manuscritos ocultos da Igreja de centenas de anos atrás. Estou solicitando financiamento para retranscrevê-los, mas Dunn diz que isso deve acontecer depois da aquisição do equipamento.",
  [1143563228900096] = "Conhecimento... você quer dizer os materiais nos arquivos?",
  [1143563228899840] = "Proteger os cidadãos quando jovens e guardar estes conhecimentos herdados quando mais velhos – ambos são muito bons.",
  [1143563228899584] = "Talvez os reembolsos devam ser moderados, afinal os recursos são limitados... Você gosta de trabalhar na Igreja?",
  [1143563228899328] = "Comprar materiais para fazer água benta para purificar as manchas deixadas pelos cultistas – isso não é motivo suficiente?",
  [1143563228899072] = "Difícil não é a palavra, só que os requisitos para preenchimento de formulários de reembolso estão cada vez mais rígidos...",
  [1143563228898816] = "Tantos anos... você acha o trabalho difícil?",
  [1143563228898560] = "Agora que você pergunta, percebo que na verdade dediquei mais de trinta anos à Igreja.",
  [1143563228898304] = "Sr. Neil, há quanto tempo você trabalha para a Igreja da Noite?",
  [1143563228898048] = "Hmm, as coisas ficaram estranhas... Como esperado, ainda preciso praticar mais as habilidades de comunicação.",
  [1143563228897792] = "......Haha.",
  [1143563228897536] = "Afinal, eles já estão com frio, não é?",
  [1143563228897024] = "Além disso, as pessoas mortas costumam ser mais fáceis de conviver do que as vivas, porque você nunca precisa se preocupar com a possibilidade de elas tornarem as coisas repentinamente estranhas.",
  [1143563228896768] = "Você se acostuma.",
  [1143563228896512] = "Então, quando você enfrenta cadáveres, você não sente medo?",
  [1143563228896256] = "Talvez o fato de eu me tornar um “Colecionador de Cadáveres” estivesse destinado no escuro.",
  [1143563228896000] = "Claro, fiz muitas coisas assim quando ainda era padre.",
  [1143563228895744] = "E o dever de um Coletor de Cadáveres é acompanhá-los em sua jornada final com dignidade.",
  [1143563228895488] = "De agora em diante, eles não precisam ter medo, não precisam sentir dor e certamente não precisam sofrer.",
  [1143563228895232] = "Pense neles como pessoas que terminaram a sua jornada; eles acabaram de chegar ao destino antes de nós e agora podem descansar.",
  [1143563228894976] = "Uh... então como devo tratá-los...",
  [1143563228894720] = "Sim, e primeiro você deve aprender uma coisa: não os trate como cadáveres.",
  [1143563228894464] = "Capitão Frye, como alguém atua como Colecionador de Cadáveres? Você realmente tem que lidar com cadáveres?",
  [1143563228894208] = "Sim, não demorará muito.",
  [1143563228893952] = "Tudo bem?",
  [1143563228693248] = "Madame Hailey, parece que você nem sempre diz coisas boas.",
  [1143563228562176] = "Rezar? O Sr. Tolo me ajudará a elaborá-lo?",
  [1143563228431104] = "Ah, acho que deve ter sido uma alma errante sem maldade. Ele realizou seu desejo...",
  [1143563228300032] = "Bastardo, como você pode dizer isso! Essa é a nossa mãe, a mãe que trabalhou duro para nos criar.",
  [1143563228284672] = "Meu Senhor se autodenomina \"O Louco\". No passado, no presente e no futuro, ele é o grande governante que domina o Mundo Espiritual, o Rei do Amarelo e do Preto que exerce a boa sorte e o farol para todo ser vivo que busca a eternidade.",
  [1143563229086464] = "Claro que é porque esse cavalheiro ganancioso fingiu ser Terry e me escreveu novamente.",
  [1143563228955392] = "É por isso que você tem que saber escolher. Aperte-os; não pegue aqueles que são muito moles e não leve aqueles com buracos de minhoca. Ao chegar em casa, corte as partes machucadas e o resto pode ser comido por três dias.",
  [1143563228824320] = "Ao mesmo tempo, essa identidade lhe permitiu evitar muitos olhares, e ela também é muito talentosa na digestão de poções. Concluímos muitas missões emitidas pelo Sr. Louco juntos.",
  [1143563228807936] = "Sim, hesitei por muito tempo. Mas ela finalmente disse: 'Precisamos de pessoas dispostas a proteger esta cidade.'",
  [1143563228893184] = "<P_Heart> (Realmente tem tudo neste caderno...) </>",
  [1143563228892928] = "Retratos de criminosos... relatórios de autópsia... Rozanne cochilando... Luo Yao jogando cartas...",
  [1143563228892416] = "Posso dar uma olhada?",
  [1143563228892160] = "Bem, eu sei um pouco; Eu uso para registros diários ou trabalho.",
  [1143563228891904] = "Capitão Frye, ouvi dizer que você sabe desenhar?",
  [1143563228891648] = "Sim, quero ficar aqui para sempre e proteger tudo aqui.",
  [1143563228891392] = "Você... realmente ama Blackthorn.",
  [1143563228891136] = "Isso porque já me candidatei para trocar meu mérito por outras coisas. Blackthorn precisa de alguns equipamentos novos, bem como vários amuletos e materiais extras.",
  [1143563228890880] = "Mas ouvi o Sr. Leonard dizer que você claramente vem acumulando isso há muito tempo...",
  [1143563228890624] = "Além disso, o mérito que acumulei não é suficiente para trocar por fórmulas e poções.",
  [1143563228890368] = "Também significa ter que deixar Blackthorn.",
  [1143563228890112] = "Mas um Sequência mais alto significa um poder mais forte, que pode proteger mais pessoas...",
  [1143563228889856] = "Isso é o suficiente por enquanto.",
  [1143563228889600] = "Capitão Frye, você está preso em Sequência 7 há muito tempo, por que não avança mais?",
  [1143563228889088] = "Um recém-chegado com potencial e muito preocupado com os seus companheiros.",
  [1143563228888576] = "Bem, como Vigias Noturnos , sempre confiamos em nossos companheiros de equipe. Os companheiros de Blackthorn são sempre os melhores.",
  [1143563228888320] = "Luo Yao, Xiga, Rebecca... são todos confiáveis...",
  [1143563228887552] = "Confiável.",
  [1143563228887296] = "Você pode ser mais específico, por exemplo, Sr. Leonard?",
  [1143563228887040] = "Eles são todos muito bons.",
  [1143563228886784] = "Capitão Frye, o que você acha de todos em Blackthorn?",
  [1143563228886528] = "Até que eu também me torne parte da história.",
  [1143563228886272] = "Enquanto eu ainda estiver na Blackthorn Security Company, guardarei este lugar, protegerei essas histórias e as pessoas dentro delas.",
  [1143563228886016] = "Sim. Se essas coisas forem mantidas em Blackthorn, as pessoas sentirão que a vivacidade ainda existe.",
  [1143563228885760] = "Parece que naquela época era muito animado...",
  [1143563228885504] = "O capitão Dunn gostava de pensar enquanto segurava o cachimbo, os formulários de reembolso do Velho Neil eram muitos para serem contados e todos gostavam de se reunir para combater o mal quando estavam de serviço.",
  [1143563228885248] = "Eles foram todos deixados para trás pelas pessoas antes.",
  [1143563228884992] = "Essas coisas têm alguma história?",
  [1143563228884736] = "Parece haver muitos itens antigos espalhados em Blackthorn, como canos... formulários de reembolso... cartões para combater o mal...",
  [1143563228884480] = "Então, <P_Heart> (Acena com a cabeça) </> vale a pena.",
  [1143563228884224] = "Para uma família comum como a nossa, uma renda estável é muito importante.",
  [1143563228883968] = "Essa é a mensalidade da Melissa, esse é o aluguel da família, esse é o pão e a carne na mesa...",
  [1143563228883712] = "<P_Heart> (Sorri) </> Mas quando eu receber meu salário... sei que cada soli não veio facilmente e não será desperdiçado...",
  [1143563228883456] = "<P_Heart> (Suspiros) </> O trabalho é muito tedioso, os documentos ficam empilhados como uma montanha e tenho que lidar com todo tipo de relacionamento. Às vezes fazendo hora extra até tarde da noite, olhando a neblina pela janela, eu penso... vale a pena tudo isso?",
  [1143563228883200] = "Todos esses são resultados de muito trabalho, então como você se sente agora?",
  [1143563228882944] = "<P_Heart> (Risos) </> Mas no final, passei. Embora não estivesse no topo da lista, bastava-me entrar no Ministério das Finanças para trabalhar...",
  [1143563228882688] = "Eu me sinto como um... <P_Heart> (Pausa) </> Babuíno de cabelos cacheados na frente dos livros.",
  [1143563228882432] = "Durante esse período, tive muita privação de sono todos os dias e perdi muito cabelo.",
  [1143563228882176] = "<P_Heart> (Acena com a cabeça) </> Tinha um certo nível de dificuldade, então eu trabalhava durante o dia e estudava gramática e contabilidade à noite.",
  [1143563228881920] = "O exame foi difícil?",
  [1143563228881664] = "Mais tarde, ouvi dizer que Backlund iria reformar e usar exames para selecionar pessoal. Eu pensei... por que não tentar? Klein também me aconselhou a fazer isso.",
  [1143563228881408] = "Esse tipo de vida... <P_Heart> (Balança a cabeça) </> Não quero experimentar isso de novo.",
  [1143563228881152] = "<P_Heart> (Recordações) </> Sim, naquela época a empresa de importação e exportação estava demitindo funcionários e quase perdi meu emprego. Todas as manhãs, quando acordava, a primeira coisa que me preocupava era se receberia uma carta de demissão.",
  [1143563228880896] = "Da empresa de importação-exportação ao Ministério da Fazenda esse processo deve ter muitas histórias, certo?",
  [1143563228880640] = "Encontrar um ponto de entrada também é muito importante; você deve usar motivos apropriados para fazer a outra parte aceitar sua oferta.",
  [1143563228880384] = "Isso mesmo, barganhar não é ser irracional, mas sim usar algumas técnicas para negociar e finalmente chegar a um acordo.",
  [1143563228880128] = "Verdadeiramente incrível, parece que também é preciso ser bom em observar.",
  [1143563228879872] = "Apontei para os arranhões e manchas na mesa e pechinchei com o chefe por vinte minutos, finalmente reduzindo para 30% do preço original.",
  [1143563228879616] = "A superfície da mesa parecia ter algumas manchas e arranhões, mas todos podiam ser removidos. Verifiquei os trilhos das gavetas e as juntas das pernas da mesa; a estrutura ainda era muito resistente.",
  [1143563228879360] = "E daquela vez comprei uma mesa de segunda mão...",
  [1143563228879104] = "<P_Heart> (Com admiração) </> Isso é incrível.",
  [1143563228878848] = "No final, gastei minhas economias apenas para concluir a instalação da lâmpada a gás, sem pedir um único centavo emprestado.",
  [1143563228878592] = "Depois usei meus contatos na empresa de importação e exportação para conseguir as lâmpadas a preço de custo.",
  [1143563228878336] = "Por exemplo, a vez em que instalamos lâmpadas a gás... Primeiro convenci o proprietário a pagar pela reforma da tubulação, dizendo que isso aumentaria a qualidade da casa e aumentaria o aluguel.",
  [1143563228878080] = "Não parece simples, você pode dar alguns exemplos?",
  [1143563228877824] = "O núcleo da negociação é a informação e a negociação. É preciso saber aproximadamente o preço de custo do produto, conhecer a margem de lucro do comerciante, saber quem são seus concorrentes e depois dominar algumas técnicas de negociação...",
  [1143563228877568] = "<P_Heart> (Confiante) </> Isso mesmo, isso é um fato.",
  [1143563228877312] = "Sr. Benson, ouvi dizer que você é muito bom em... barganha?",
  [1143563228877056] = "No final, ele até me elogiou como um jovem com consciência que faz as coisas com honestidade.",
  [1143563228876800] = "Calculei uma conta para ele e tive a ideia de ganhar mais aluguel. Diante de mais aluguel, ele concordou prontamente.",
  [1143563228876544] = "Que tipo de motivo foi esse?",
  [1143563228876288] = "Encontrei um motivo que o forçou a concordar e, no final, paguei apenas uma multa de depósito de 3 soli para rescindir o contrato com sucesso.",
  [1143563228876032] = "O Sr. Frank é muito astuto e conta cada centavo. Mas, felizmente, ele... <P_Heart> (Pausa) </> sua inteligência não é tão boa quanto a de um babuíno de cabelos cacheados, então ele não consegue calcular contas excessivamente complexas.",
  [1143563228875776] = "A negociação correu bem?",
  [1143563228875520] = "<P_Heart> (Sorrisos) </> Eu disse a ele diretamente - 'Sr. Frank, estamos aqui para rescindir o contrato. Aí comecei a negociar...",
  [1143563228875264] = "<P_Heart> (Curiosamente) </> Então como foi resolvido depois?",
  [1143563228875008] = "Quando fomos procurar o Sr. Frank, ele sentou-se no sofá e declarou com grande entusiasmo: 'Você deveria conhecer meus princípios: absolutamente nenhum pagamento atrasado de aluguel é permitido!'",
  [1143563228874752] = "Mais tarde, porém, Klein encontrou um emprego e planejamos nos mudar para a Rua Daffodil. Porém, ainda faltava meio ano de aluguel e tivemos que pagar uma multa...",
  [1143563228874496] = "Quando alugamos a casa dele pela primeira vez, ele só queria assinar por três meses, dizendo que tinha medo de que não pudéssemos pagar o aluguel. Esforcei-me muito para garantir um contrato de aluguel de um ano.",
  [1143563228874240] = "Ele é o tipo de pessoa... que faz você perceber profundamente a realidade da sociedade.",
  [1143563228873984] = "Uma figura lendária? Parece que também ouvi algumas coisas...",
  [1143563228873728] = "<P_Heart> (Risos) </> Ah, esse era o nosso senhorio em Tingen, uma 'figura lendária' do prédio de apartamentos da Iron Cross Street.",
  [1143563228873472] = "Sr. Benson, você parece mencionar o Sr. Frank com frequência?",
  [1143563228873216] = "Mas a única coisa que me preocupa é... ela é muito sensata... assumindo um monte de coisas que não deveria na idade dela...",
  [1143563228872960] = "Melissa dedica muito tempo e energia aos seus hobbies; ela definitivamente poderá se tornar mecânica ou engenheira no futuro...",
  [1143563228872704] = "<P_Heart> (Acena com a cabeça) </> Claro, esse é o sonho dela, e Klein e eu sempre a apoiamos.",
  [1143563228872448] = "Parece realmente muito especial, então você apoia os hobbies dela?",
  [1143563228872192] = "Mas eu sabia que ela estava apenas escondendo todas as suas emoções naquelas engrenagens.",
  [1143563228871936] = "Depois que nossos pais faleceram, ela ficou em silêncio por um tempo. Achei que ela fosse chorar ou fazer birra, mas ela simplesmente se trancou no quarto, mexendo naquelas máquinas.",
  [1143563228871680] = "<P_Heart> (Risos) </> Sim, e ela poderia montá-lo novamente depois de desmontá-lo e até mesmo fazê-lo funcionar melhor.",
  [1143563228871424] = "<P_Heart> (Surpreso) </> Desmontando o relógio de pêndulo?",
  [1143563228871168] = "Quando ela era criança, outras crianças gostavam de brincar de boneca, mas ela estava ocupada desmontando o relógio de pêndulo da sala.",
  [1143563228870912] = "Especialmente seu hobby – ela costuma ser obcecada por engrenagens, rolamentos e outros equipamentos mecânicos.",
  [1143563228870656] = "<P_Heart> (A expressão suaviza) </> Isso mesmo, ela é muito especial.",
  [1143563228870400] = "Ouvi dizer que Melissa é uma irmã muito especial?",
  [1143563228870144] = "<P_Heart> (Sorri misteriosamente) </> Eu tenho meus caminhos. Sou muito bom em... barganhar, mas às vezes também preciso da cooperação de Klein e Melissa.",
  [1143563228869888] = "<P_Heart> (Risos) </> Então como você lidou com isso?",
  [1143563228869632] = "Sua inteligência não é tão boa quanto a de um babuíno de cabelos cacheados, mas ele sempre consegue encontrar vários motivos para aumentar o aluguel.",
  [1143563228869376] = "Você sabe qual foi a coisa mais interessante? Era o nosso antigo senhorio, Sr. Frank.",
  [1143563228869120] = "<P_Heart> (Encolhe os ombros) </> Estava tudo bem; esta é responsabilidade do irmão mais velho. Mas no geral, a vida ainda era muito interessante...",
  [1143563228868864] = "Teve um período que você sustentava a família sozinho, deve ter sido muito difícil, né?",
  [1143563228868608] = "Se não fosse pelo meu irmão e minha irmã mais novos, eu teria perdido muita motivação para a vida e para o trabalho... <P_Heart> (Pausa) </> Esqueça, não vamos falar sobre isso.",
  [1143563228868352] = "Porém... <P_Heart> (A expressão suaviza) </> na verdade, estou muito grato por eles.",
  [1143563228868096] = "<P_Heart> (Acena com a mão) </> É animado, mas também dá dor de cabeça. Por exemplo, de manhã, Melissa discutia comigo sobre seu despertador mecânico.",
  [1143563228867840] = "<P_Heart> (Risos) </> Parece muito animado.",
  [1143563228867584] = "Melissa estava sempre mexendo nas engrenagens e nas molas; essas partes estavam espalhadas por toda parte, e muitas vezes eu pisava nelas enquanto caminhava.",
  [1143563228867328] = "Klein ficava sempre acordado lendo até tarde; a luz do seu quarto ficava acesa até o meio da noite.",
  [1143563228867072] = "<P_Heart> (Risos) </> Um pouco caótico, mas também muito quente.",
  [1143563228866816] = "Sr. Benson, como é geralmente a família Moretti?",
  [1143563228866560] = "Se você tiver oportunidade... em primeiro lugar, você sabe nadar?",
  [1143563228866304] = "Cada vez que você vai para o mar, você pode encontrar coisas inesperadas. Tempestades, piratas, monstros... ou até existências mais antigas.",
  [1143563228866048] = "<P_Heart> (Calmamente) </> Essa é a rotina diária no mar. Os navios mercantes precisam de proteção, os cultistas precisam ser expurgados, as ruínas precisam ser exploradas e também...",
  [1143563228865792] = "Parece muito perigoso...",
  [1143563228865536] = "Mas no final, nós os afundamos. Aqueles piratas... <P_Heart> (Pausas) </> ou foram arrastados pelas correntes ou se tornaram presas dos tubarões.",
  [1143563228865280] = "<P_Heart> (Acena com a cabeça) </> Batalhas no mar nunca são fáceis. Perdemos dois canhões laterais e três marinheiros ficaram feridos.",
  [1143563228865024] = "A batalha foi intensa?",
  [1143563228864768] = "Finalmente, nós os bloqueamos perto de uma ilha sem nome.",
  [1143563228864512] = "<P_Heart> (Recordações) </> Nós os perseguimos por três dias inteiros, cruzando a área do mar tempestuoso. Eles estavam familiarizados com os recifes e as correntes de lá, e quase os perdemos.",
  [1143563228864256] = "O que aconteceu depois? Você conseguiu?",
  [1143563228864000] = "Esse navio pertencia aos 'Red Skulls', um grupo de caras cruéis e astutos que se especializaram em saquear navios mercantes e matar todas as testemunhas.",
  [1143563228863744] = "<P_Heart> (Contemplando) </> Muitos anos atrás, estávamos rastreando um navio pirata nas profundezas do Mar Sônia.",
  [1143563228863488] = "Você é capitão há tantos anos, qual foi a viagem mais inesquecível que você fez?",
  [1143563228863232] = "<P_Heart> (Sério) </> Acredite, você não quer experimentar isso.",
  [1143563228862976] = "É tão sério?",
  [1143563228862720] = "Se você ouvir esse tipo de canto no mar no futuro, sugiro que cubra os ouvidos imediatamente ou... pule no mar.",
  [1143563228862464] = "Gehrman Sparrow uma vez me ouviu cantar uma vez, sua expressão na época... <P_Heart> (Balança a cabeça) </> Ainda não consigo esquecer.",
  [1143563228862208] = "<P_Heart> (Desamparado) </> Alguém disse uma vez, outros cantam por dinheiro, mas quando eu canto... é para vidas.",
  [1143563228861952] = "<P_Heart> (Contendo o riso) </> Na verdade... tem uma sensação de poder?",
  [1143563228861696] = "<P_Heart> (Para, um tanto envergonhado) </> ...Isso é sobre o sentimento.",
  [1130298758679552] = "Capitão Dunn...",
  [1143563228861440] = "Crash, crash, crash, oh grande mar, quebrando-se ao pé das rochas!",
  [1143563228861184] = "<P_Heart> (Limpa a garganta, começa a cantar) </> Onda, onda, onda, oh mar, onda contra as rochas cinzentas e frias!",
  [1143563228860928] = "<P_Heart> (Curiosamente) </> Por quê? Que tipo de música você canta?",
  [1143563228860672] = "<P_Heart> (Desamparado) </> Eu tentei muitas vezes, mas... <P_Heart> (Pausa) </> o efeito não foi muito ideal.",
  [1143563228860416] = "Não é que eu quisesse cantar; era um requisito da poção. Para digerir a poção do 'Rei do Mar', é preciso cantar no mar, usando a voz para desencadear tempestades.",
  [1143563228860160] = "<P_Heart> (Suspiros) </> Esse já foi um passo necessário para agir como um 'Rei do Mar'.",
  [1143563228859904] = "Acabei de ouvir alguém mencionar isso ocasionalmente, dizendo que sua voz para cantar... é única.",
  [1143563228859648] = "<P_Heart> (A expressão endurece) </> ...Quem te disse isso?",
  [1143563228859392] = "Senhor “O Enforcado”, ouvi dizer... você sabe cantar?",
  [1143563228859136] = "Alguns perigos ocultos devem ser identificados antes que se transformem numa catástrofe.",
  [1143563228858880] = "Além do mais... se os rituais malignos do Porto de Bansi realmente se espalhassem, todo o Mar Sonia não conheceria paz.",
  [1143563228858624] = "<P_Heart> (Olha para longe) </> Como capitão da Igreja das Tempestades, tenho a responsabilidade de monitorar aquela área marítima.",
  [1143563228858368] = "Você quer ir a Bansy Harbor para investigar?",
  [1143563228858112] = "Verifiquei os relatórios internos da Igreja; a situação lá é muito mais complexa do que parece superficialmente.",
  [1143563228857856] = "<P_Heart> (Em voz profunda) </> No mês passado, ouvi dizer que os sacrifícios primitivos em Bansy Harbor pareciam mostrar sinais de renascimento...",
  [1143563228857600] = "Houve algum incidente nos últimos anos?",
  [1143563228857344] = "<P_Heart> (Acena com a cabeça) </> Mais tarde, o porto foi tomado pela Igreja das Tempestades, que substituiu esta tradição maligna por rituais ortodoxos. Mas as coisas subterrâneas... podem não ter sido completamente limpas.",
  [1143563228857088] = "Isto é... sacrifício humano?",
  [1143563228856832] = "Todos os anos, eles realizavam um ritual, sacrificando pessoas vivas e compartilhando seu sangue e carne...",
  [1143563228856576] = "<P_Heart> (Abaixa a voz) </> Costumava haver uma tradição primitiva de sacrifício lá, adorando um chamado 'Deus do Tempo'.",
  [1143563228856320] = "Que segredos? Existe alguma coisa que eu possa saber?",
  [1143563228856064] = "O Porto de Bansi está localizado nas profundezas do Mar Sonia. Nominalmente, está sob a jurisdição da Igreja do Senhor das Tempestades, mas na realidade esconde muitos segredos.",
  [1143563228855808] = "<P_Heart> (Parece solene) </> ... Um porto amaldiçoado.",
  [1143563228855552] = "Você sabe que tipo de lugar é Bansy Harbor?",
  [1143563228855296] = "O mar é mais perigoso que a terra, mas também é mais... livre.",
  [1143563228855040] = "<P_Heart> (Balança a cabeça) </> Eu sou um capitão; Sou responsável por um campo de batalha diferente.",
  [1143563228854784] = "Você também é responsável por lidar com esses tipos de eventos do Mystic World?",
  [1143563228854528] = "Aqueles que cometem crimes, aqueles que perdem o controle, os cultistas... todos são tratados igualmente, usando trovões e relâmpagos para eliminar ameaças.",
  [1143563228854272] = "<P_Heart> (Acena com a cabeça) </> Eles acreditam que a vontade da tempestade é direta, furiosa e não deixa espaço para mais nada.",
  [1143563228854016] = "Simples e direto?",
  [1143563228853760] = "Claro, certos estilos da Igreja... <P_Heart> (Abaixa a voz) </> por exemplo, a maneira como os Punidores Mandatados lidam com as coisas às vezes é muito simples e direta.",
  [1143563228853504] = "A tempestade não argumentará com você; isso apenas testará se você é forte o suficiente.",
  [1143563228853248] = "<P_Heart> (Risos) </> Estou acostumado com isso. No mar, as pessoas que são demasiado exigentes em relação às regras muitas vezes não vivem muito.",
  [1143563228852736] = "A Igreja do Senhor das Tempestades tem muitas diferenças em relação às outras igrejas. Defendemos o poder e a coragem para enfrentar a tempestade diretamente.",
  [1143563228852480] = "<P_Heart> (Risos) </> Pela força, e também pela sorte e coragem.",
  [1143563228852224] = "Então como você se tornou capitão mais tarde?",
  [1143563228851968] = "Naquela época eu tinha acabado de embarcar no navio, não sabia de nada e só sabia usar os punhos para falar.",
  [1143563228851712] = "Contando desde quando eu era apenas um marinheiro comum, ou até antes... já se passaram muitos anos.",
  [1143563228851456] = "Ouvi dizer que você também pertence à Igreja do Senhor das Tempestades... há quanto tempo?",
  [1143563228851200] = "<P_Heart> (Em voz profunda) </> Não questiono mais; Eu apenas sirvo piedosamente e obedeço à sua vontade.",
  [1143563228850944] = "<P_Heart> (Coloca a mão direita no peito, curva-se levemente) </> Agora eu só quero dizer - é nossa honra, Sr. Tolo.",
  [1143563228850688] = "Então parece que todos vocês respeitam muito o Sr. Louco agora?",
  [1143563228850432] = "Principalmente quando percebi que às vezes, mesmo sem pedir nada em troca, ele estava disposto a compartilhar aquela informação preciosa.",
  [1143563228850176] = "Uma e outra vez... o conhecimento que ele demonstrou, as orações que ele respondeu, sua proteção da Clube do Tarô e da Cidade de Prata...",
  [1143563228849920] = "O que fez você mudar de ideia depois?",
  [1143563228849664] = "Eu tive que confirmar que seu poder era real, confirmar que ele não tinha maldade conosco e confirmar que tudo isso não era algum tipo de armadilha.",
  [1143563228849408] = "<P_Heart> (Honestamente) </> No mundo Extraordinário, confiar facilmente em uma existência desconhecida é perigoso.",
  [1143563228849152] = "Você não acreditou no Sr. Louco naquela época?",
  [1143563228848896] = "Passei muito tempo observando e testando antes de gradualmente compreender... a grandeza daquela existência.",
  [1143563228848640] = "Qualquer pessoa racional, enfrentando esse poder além da imaginação, escolheria primeiro ser cautelosa.",
  [1143563228848384] = "<P_Heart> (Pausa) </> Admiração e suspeita.",
  [1143563228848128] = "Quando você viu o Sr. Louco pela primeira vez, o que você sentiu?",
  [1143563228847872] = "Quando eu estava realizando uma missão no mar, acidentalmente encontrei alguns fenômenos estranhos... e então fui puxado para cima daquela névoa cinzenta.",
  [1143563228847616] = "Aquilo foi um... acidente e também um arranjo do destino.",
  [1143563228847360] = "Senhor “O Enforcado”, como você se juntou ao Clube do Tarô naquela época?",
  [1143563228847104] = "Daquele dia em diante, eu realmente descobri os segredos por trás da identidade de ‘Aprendiz’. Ganhei poder e também ganhei... uma chance de sobreviver.",
  [1143563228846848] = "Fiz uma aposta e orei para ele. Ele não apenas respondeu, mas também me ajudou a afastar aqueles sussurros, tão simples quanto... tirar a poeira.",
  [1143563228846592] = "Até que recitei aquele nome honorífico – o nome honorífico do Sr. Tolo.",
  [1143563228846336] = "Então como você...",
  [1143563228846080] = "Quando experimentei isso pela primeira vez, pensei que fosse morrer.",
  [1143563228845824] = "Toda lua cheia, ouço sussurros. Não são alucinações auditivas, mas vozes soando diretamente em meu cérebro, falando uma língua que não entendo... acompanhadas por um toque de loucura e perda de controle.",
  [1143563228845568] = "Na verdade, foi uma maldição. Essa pulseira pertencia à família Abraham, e eu... porque a usei, herdei a maldição da linhagem daquela família.",
  [1143563228845312] = "Na realidade...",
  [1143563228845056] = "Então descobri que enquanto segurasse aquela pulseira eu poderia atravessar paredes e abrir portas trancadas... Achei que era boa sorte, um presente do destino.",
  [1143563228844800] = "Mas isso é porque ela não tinha mais parentes. Eu cuidei dela por muito tempo, e ela quis me passar seu precioso Característica de Beyonder depois que morreu, junto com aquela pulseira...",
  [1143563228844544] = "É realmente muito incrível...",
  [1143563228844288] = "Você consegue imaginar o choque de um paciente idoso de repente lhe mostrar a capacidade de atravessar paredes?",
  [1143563228844032] = "......É um pouco bizarro, mas ganhei meus poderes de uma senhora idosa. Era a Sra. Anlisa; ela foi minha paciente quando eu ainda era médico em uma clínica.",
  [1143563228843776] = "Senhorita “Mágica”, como você obteve seus poderes?",
  [1143563228843520] = "<P_Heart> (Sorrindo) </> Então, obrigado por gostar - isso é muito importante para mim.",
  [1143563228843264] = "<P_Heart> (Suspiros) </> A vida já é muito curta e há muitas coisas para fazer. Mas escrever, embora atormente as pessoas, é um dos meus poucos hobbies.",
  [1143563228843008] = "Deve ter sido muito difícil...",
  [1143563228842752] = "Por esse raciocínio do livro, você sabe quantos fios de cabelo perdi e quantas vezes sofri de insônia?",
  [1143563228842496] = "A inspiração vem da vida, ou melhor, dos amigos ao meu redor que estão sempre em apuros.",
  [1143563228842240] = "Uh... claro que terminei. Como você inventou essa história?",
  [1143563228841984] = "Oh? Você realmente terminou de ler... não daquele tipo que você só lê um terço e deixa na cabeceira da cama?",
  [1143563228841728] = "Dona “Mágica”, li a sua “Villa Tempestade”, é maravilhosa!",
  [1143563228841472] = "Por exemplo... estátuas que se movem sozinhas à meia-noite? Ou herdando um legado misterioso de longe? Acontece que meu novo livro está faltando alguma inspiração.",
  [1143563228841216] = "Minha história acabou. <P_Heart> (Piscando) </> E você? Você tem mais alguma história bizarra?",
  [1143563228840960] = "Então é assim...",
  [1143563228840704] = "<P_Heart> (Encolhendo os ombros) </> Acho que ele fez essas coisas, talvez por uma sensação de compensação.",
  [1143563228840448] = "Mais tarde, quando me formei na faculdade de medicina, ele também usou seus contatos para me ajudar a encontrar um emprego na Clínica Yusuf.",
  [1143563228840192] = "Não é nada. Quando eu estava no ensino fundamental, minha mãe faleceu de uma doença grave. Foi então que recebi uma carta do meu pai pedindo-me que herdasse a propriedade em Backlund.",
  [1143563228839936] = "Desculpe, eu não queria...",
  [1143563228839680] = "Pai... ele era um oficial de baixo escalão que foi para East Balam em busca de poder e riqueza e começou uma nova família.",
  [1143563228839424] = "...... Nada de especial. Eu morava em um pequeno apartamento no bairro de Backlund Bridge e minha mãe e eu dependíamos uma da outra.",
  [1143563228839168] = "Só por curiosidade, como seria a infância de um grande escritor.",
  [1143563228838912] = "Por que você perguntou isso de repente? Me investigando?",
  [1143563228838656] = "Senhorita “Mágica”, como você era... quando era criança?",
  [1143563228838400] = "<P_Heart> (balançando a cabeça) </> Eu não consegui. Embora eu sempre diga que ela é problemática, mas... ela é minha melhor amiga.",
  [1143563228838144] = "Claro que tive que acompanhá-la. Embora eu seja apenas um escritor ‘delicado e sensível’, deixá-la morrer sozinha?",
  [1143563228837888] = "Então e você?",
  [1143563228837632] = "Imprudente, impulsiva, sempre pensando primeiro com os punhos... já imaginou? Na verdade, ela queria investigar um general pirata sozinha!",
  [1143563228837376] = "Amigo? Aquela garota foi enviada pelo céu para me atormentar.",
  [1143563228837120] = "Ouvi dizer que você e a senhorita Xio Derecha são bons amigos?",
  [1143563228836864] = "Claro. O medo e a gratidão não são contraditórios, e o espanto e a curiosidade podem coexistir. Resumindo... estou muito feliz por ter cantado esse nome honorífico naquele dia.",
  [1143563228836608] = "Você realmente é um escritor, mesmo pensando nesse tipo de coisa como material?",
  [1143563228836352] = "Nunca parei de aprender, de tentar entender as regras deste mundo Extraordinário... embora isso seja bastante perigoso. Mas é interessante, não é?",
  [1143563228836096] = "E você não acha? Esta é uma verdadeira aventura. Tal como escrevo nos meus romances, misteriosos, perigosos, mas cheios de possibilidades.",
  [1143563228835840] = "Claro que eu estava com medo. Mas mais do que isso... curiosidade. Aquela longa mesa de bronze, aquele palácio acima da névoa cinzenta e os vários meios que ele exibiu – isso era um poder além da minha imaginação.",
  [1143563228835584] = "Naquela hora você não sentiu medo? Enfrentando uma existência que pode ser um deus?",
  [1143563228835328] = "Cada um tem seus próprios segredos, mas nesta reunião podemos trocar informações, trocar materiais e até obter sua orientação.",
  [1143563228835072] = "Estou muito grato. Ele me deu uma chance de sobreviver e me deixou conhecer outros membros... The Hanged Man, Justice, The Sun.",
  [1143563228834816] = "O poder do Sr. “Tolo” é realmente insondável... Você deve estar muito grato a ele.",
  [1143563228834560] = "E ele realmente estendeu a mão para ajudar, de uma forma muito simples, como se estivesse apenas sacudindo a poeira.",
  [1143563228834304] = "Sim. Esse tipo de dor... o canto de todos os Deuses Verdadeiros não recebeu resposta, apenas ele ouviu.",
  [1143563228834048] = "Sussurros da Lua Cheia?",
  [1143563228833792] = "Hmm... é difícil descrever. Eu o conheci quando estava mais desesperado.",
  [1143563228833536] = "Senhora “Mágico”, para você, que tipo de existência é o Sr. “Tolo”?",
  [1143563228833280] = "Haha, você ficou com medo? Você começou a suar frio? Esse é o tom que aprendi com o Sr. Mundo!",
  [1143563228833024] = "Cuidado com os espectadores...",
  [1143563228832768] = "Portanto, <P_Heart> (Sério) </> no mundo Extraordinário, você deve sempre—'Cuidado com os Espectadores'.",
  [1143563228832512] = "Beyonders do Espectador Caminho pode não apenas realizar psicoterapia, mas também usar o controle da mente para fazer Beyonders entrar em colapso.",
  [1143563228832256] = "Isto não é invisibilidade no sentido tradicional, mas sim “Invisibilidade Psicológica” – quando a cognição é guiada pela sugestão, a realidade também escapa do campo de visão.",
  [1143563228832000] = "O que? Dona Susie é invisível?",
  [1143563228831744] = "Por exemplo, você não pode ver Susie agora, mas ela realmente está deitada a seus pés, aproveitando a soneca.",
  [1143563228831488] = "O nome Sequência “Espectador” faz as pessoas pensarem erroneamente que este é um Caminho bom apenas para observação e apoio. Mas, na realidade, isto também é um disfarce, um disfarce que faz com que as pessoas subestimem ainda mais o inimigo.",
  [1143563228831232] = "<P_Heart> (Sorrisos) </> Não, tenho muitas identidades no mundo real. Se quiser me encontrar, você pode ir ao Loen Charity Fund. Quanto à psicoterapia, essa é uma habilidade extraordinária do 'Espectador' Caminho .",
  [1143563228830976] = "Senhorita Audrey, sua identidade no mundo real é de psicóloga?",
  [1143563228830720] = "Sim, as bicicletas disponíveis para alugar na rua foram uma ideia que apresentei anteriormente.",
  [1143563228830464] = "Na verdade, você é acionista da empresa de bicicletas!",
  [1143563228830208] = "Você só precisa pagar uma ou duas semanas de juros, cerca de duzentas ou trezentas libras, para adquirir dez por cento das ações da empresa de bicicletas.",
  [1143563228829952] = "Depois disso, penhore o estoque de bicicletas ao banco e use o empréstimo para pagar o empréstimo anterior.",
  [1143563228829696] = "Primeiro, penhore minhas ações da transportadora ao banco por um curto prazo e, depois de obter o empréstimo, compre as ações das bicicletas.",
  [1143563228829440] = "Meu primeiro investimento bem-sucedido foi em ações de uma empresa de bicicletas. Eu não tinha dinheiro suficiente para comprar ações na época, mas meu pai me ensinou uma técnica de investimento.",
  [1143563228829184] = "Senhorita Audrey, além da propriedade da família, você investe?",
  [1143563228828928] = "Não posso lhe dar uma quantia em dinheiro diretamente todas as vezes, mas posso lhe dizer como investir. O Imperador Roselle disse que dar um peixe a alguém não é tão bom quanto ensiná-lo a pescar!",
  [1143563228828672] = "De qualquer forma! Se você não tiver dinheiro no futuro, pode vir até mim.",
  [1143563228828416] = "Talvez... porque nunca me faltou dinheiro, sempre esqueço o quanto o dinheiro é importante para um novo Beyonder .",
  [1143563228828160] = "Na verdade, esta também foi uma revelação do Sr. Louco; Ele é sempre tão atencioso.",
  [1143563228827904] = "De nada, afinal você precisa de algum 'capital inicial'.",
  [1143563228827648] = "Senhorita Audrey, obrigado pelo dinheiro que você me deu antes.",
  [1143563228827392] = "Aguardarei sua chegada, {{PlayerName}}.",
  [1143563228827136] = "Como esperado do Sr. Tolo, ele está realmente se preocupando com a vida das pessoas que estão na base. Louvado seja o Louco! Se eu tiver oportunidade, devo visitar pessoalmente a fundação.",
  [1143563228826880] = "“O que fazemos parece simples, mas afeta verdadeiramente a vida de uma criança após a outra, por isso devemos começar o mais rápido possível e não podemos perder tempo.”",
  [1143563228826624] = "Lembro que uma vez Ele disse esta frase.",
  [1143563228826368] = "Além disso, promover a existência da fundação antes da época de exames para que quem realmente precisa dela possa obter ajuda atempada.",
  [1143563228826112] = "No início da sua criação, propôs muitas sugestões muito práticas: por exemplo, simplificar o processo de revisão e vincular a distribuição do fundo da bolsa à conta do indivíduo.",
  [1143563228825856] = "Louvado seja o tolo. Você está certo; O Sr. Tolo tem um coração gentil.",
  [1143563228825600] = "A filosofia da fundação é verdadeiramente excelente. Deve ter ajudado muitas crianças pobres a prosseguirem os seus estudos. Louvado seja o Sr. Tolo.",
  [1143563228825344] = "Você parece muito interessado na fundação. Foi fundada pelo Sr. Fool, localizada na Rua Pesez, 22, no bairro norte de Backlund. Se você tiver oportunidade, pode ir lá e dar uma olhada.",
  [1143563228825088] = "Sim, a identidade que separei permaneceu em Backlund para cuidar dos assuntos da fundação e acompanhar minha família.",
  [1143563228824832] = "Senhorita Audrey, ouvi dizer que você também é diretora do Loen Charity Fund.",
  [1143563228824576] = "(Rindo) Senhorita Susie é realmente incrível!",
  [1143492898233344] = "O roteiro desapareceu",
  [1143563228619264] = "Eu já tinha preparado aquele terreno. Não porque você usou o Artefato Selado para me influenciar, mas porque é o que você merece.",
  [1143563228823296] = "Susie era originalmente apenas um Golden Retriever com linhagem não tão pura, um presente que recebi quando meu pai comprou um Foxhound. Mas ela agora é minha família, minha assistente.",
  [1143563228823040] = "Senhorita Audrey, por que a Sra. Susie pode falar? Ela é... uma criatura mágica?",
  [1143563228822784] = "Entendido, obrigado. Aprendi mais alguns Beyonder conhecimentos.",
  [1143563228822528] = "Um nome honorífico de três partes não é apenas um nome; está mais próximo de um olhar de divindade, um feitiço para convocação.",
  [1143563228822272] = "No mundo Extraordinário, entoar nomes honoríficos desconhecidos provavelmente evocará perigos desconhecidos. Exceto pelos nomes honoríficos dos Deuses Verdadeiros e seus Clube do Tarô companheiros, você não deve cantar nenhum outro nome honorífico.",
  [1143563228821760] = "Portanto, sua segunda linha do nome honorífico é Abençoado do Rei do Amarelo e do Preto.",
  [1143563228821248] = "Meu nome honorífico é – O Espírito Santo que tudo vê, o Abençoado do Rei Amarelo e Preto, o viajante dos sonhos e dos corações.",
  [1143563228820992] = "Senhorita Audrey, você tem um nome honorífico? Se eu quiser orar pedindo ajuda, o que devo cantar?",
  [1143563228820736] = "<P_Heart> (Pausa) </> Extremamente raramente, as pessoas nos sonhos, as coisas ditas nos sonhos, me deixam atordoado sem saber se é realidade ou um sonho.",
  [1143563228820480] = "Não há realmente nenhum impacto?",
  [1143563228820224] = "<P_Heart> (Rindo) </> Não se preocupe, posso diferenciá-los.",
  [1143563228819968] = "Você será incapaz de distinguir entre verdadeiro e falso?",
  [1143563228819712] = "O sonho e a realidade estão profundamente interligados; às vezes pode ser um pouco confuso.",
  [1143563228819456] = "Quais são as desvantagens?",
  [1143563228819200] = "É apenas mais fácil encontrar pistas do que acordado. Essa habilidade... tem seus prós e contras.",
  [1143563228818944] = "Então você é muito bom em investigações?",
  [1143563228818688] = "Num sonho, as informações que a outra parte deseja esconder não terão onde se esconder.",
  [1143563228818176] = "Por exemplo, puxar as pessoas à força para um sonho e ver o interior de seus corações.",
  [1143563228817920] = "Semelhante. Posso fazer muitas coisas em um sonho que não posso fazer enquanto estiver acordado.",
  [1143563228817664] = "Como sonhar?",
  [1143563228817408] = "Você pode entendê-lo como a capacidade de agir dentro dos sonhos.",
  [1143563228817152] = "Capitão Dunn, que tipo de habilidades um 'Pesadelo' tem?",
  [1143563228816896] = "Desculpe, ser capaz de relembrar silenciosamente o passado talvez também seja uma... felicidade luxuosa.",
  [1143563228816384] = "De vez em quando penso no passado, naqueles companheiros que já partiram.",
  [1143563228816128] = "Sim, não há necessidade de fazer nada, basta pedir uma xícara de café Filmer e ouvir as pessoas ao meu redor conversando.",
  [1143563228815872] = "Apenas sente-se?",
  [1143563228815616] = "É por isso que me sento no café.",
  [1143563228815360] = "O trabalho de um Vigia Noturno é tenso e agitado na maior parte do tempo, mas também é preciso aprender a encontrar maneiras de relaxar.",
  [1143563228815104] = "<P_Heart> (Acena com a cabeça) </> O café Fermo é muito amargo, mas muito perfumado. Tomar uma xícara depois de resolver um missão é uma delícia.",
  [1143563228814848] = "Ouvi... um amigo mencionar isso.",
  [1143563228814592] = "Você sabe disso?",
  [1143563228814336] = "Café Filmer do Vale Pas?",
  [1143563228814080] = "<P_Heart> (Tirando um cachimbo) </> Fumando cachimbo ou tomando café.",
  [1143563228813824] = "Capitão Dunn, você tem algum hobby fora do trabalho?",
  [1143563228813568] = "A verdadeira proteção é permitir que as pessoas que estão na luz nunca saibam da existência das trevas.",
  [1143563228813312] = "É por isso que somos chamados de 'Vigias Noturnos'. Guardamos durante a noite e avançamos na escuridão.",
  [1143563228813056] = "Mas eles não sabem que os estamos protegendo.",
  [1143563228812800] = "Preservar essas coisas aparentemente simples é o significado.",
  [1143563228812544] = "Todas as manhãs, você vê cidadãos fazendo fila para comprar pão, crianças correndo na rua, comerciantes negociando, casais passeando à beira do rio...",
  [1143563228812288] = "Qual é o significado de fazer essas coisas?",
  [1143563228812032] = "Lidar com vários incidentes extraordinários e gerenciar esses perigosos artefatos selados.",
  [1143563228811776] = "Capitão Dunn, que tipo de trabalho Vigias Noturnos costuma fazer?",
  [1143563228811520] = "Ele vai ser um excelente Vigia Noturno... não, ele já é.",
  [1143563228811264] = "Você tem uma opinião elevada sobre ele?",
  [1143563228811008] = "Mais importante ainda, ele tem um coração bondoso.",
  [1143563228810752] = "Ter sorte não significa ser adequado para ser um Vigia Noturno , mas ele é um jovem muito talentoso – inteligente e cauteloso.",
  [1143563228810496] = "Você decidiu recrutá-lo por causa disso?",
  [1143563228810240] = "Ter encontrado tal incidente e não ter aceitado imediatamente nossa proteção, mas ainda estar vivo – isso foi o suficiente para provar sua sorte.",
  [1143563228809984] = "Foi além das minhas expectativas.",
  [1143563228809472] = "Como um 'Pesadelo', posso entrar nos sonhos de outras pessoas. Naquela época, ele acabara de vivenciar um incidente extraordinário e eu precisava confirmar se ele havia ocultado alguma informação.",
  [1143563228809216] = "Em um sonho?",
  [1143563228808960] = "A rigor, minha primeira conversa séria com ele foi durante um sonho.",
  [1143563228808448] = "Eu me lembrei dessa frase até agora.",
  [1143563228808192] = "Nasci em Tingen, cresci em Tingen e quero proteger este lugar.",
  [1143492898233088] = "Próxima cena",
  [1143563228619008] = "Alberto. Você nunca me fez nenhum pedido. Nem mesmo uma vez.",
  [1143563228806912] = "Até que fui arrastado para um incidente Beyonder.",
  [1143563228806656] = "Até...",
  [1143563228806400] = "É uma história muito comum. Naquela época, como a maioria das pessoas, eu só queria encontrar um emprego estável em Tingen.",
  [1143563228806144] = "Capitão, como você se juntou à Igreja da Noite Eterna?",
  [1143563228805888] = "Sim, essa é exatamente a expressão!",
  [1143563228805632] = "…………Eu acho que entendo.",
  [1143563228805376] = "E esta: 'As glicínias do lado de fora da janela, muito lindas, tão lindas assim - as glicínias do lado de fora da janela.'",
  [1143563228804864] = "Por exemplo, assim: 'As glicínias florescendo do lado de fora da janela, como cachos de uvas secas; quando penso nisso enquanto estou de plantão à meia-noite, sempre sinto muita fome.'",
  [1143563228804608] = "Não posso dizer que sou completamente incapaz. Na verdade, eu tentei muito, mas toda vez que terminava de recitar, os outros tinham uma expressão estranha no rosto.",
  [1143563228804352] = "Eh? Como a poção é digerida dessa maneira...",
  [1143563228804096] = "Eu... tosse, não sou muito bom em escrever.",
  [1143563228803840] = "Então você escreveu alguma antes?",
  [1143563228803584] = "Não inteiramente. De modo geral, os colegas do 'Vidente' Caminho escreverão poesia para digerir sua poção depois de se tornarem 'Poetas da Meia-Noite'.",
  [1143563228803328] = "Sr. Leonard, todos Vigias Noturnos precisam aprender a escrever poesia?",
  [1143563228803072] = "<P_Heart> (Aparentemente falando sozinho) </> Velho, você pode roubar um pouco da sorte para mim da próxima vez? Deixe-me ganhar uma vez...",
  [1143563228802816] = "Estou bem... Haha, acabei de lembrar de algo importante. Eu irei agora.",
  [1143563228802560] = "Sr. Leonardo? Sr. Leonardo?",
  [1143563228802048] = "(Depois de uma rodada do tutorial Fighting Evil), eu... ganhei? Joguei todas as cartas da minha mão.",
  [1143563228801792] = "......Tudo bem então.",
  [1143563228801536] = "<P_Heart> (Insistindo) </> Experimente. Vamos começar com um tutorial; não contará para dinheiro, independentemente de quem ganhar, <P_Heart> (Sussurrando) </> apenas deixe-me experimentar a sensação de vencer pelo menos uma vez...",
  [1143563228801280] = "Não, não, eu realmente não sei jogar...",
  [1143563228801024] = "Claro, é uma boa maneira de relaxar – afinal, um Vigia Noturno precisa de algumas diversões fora do trabalho. Você gostaria de jogar uma partida? Eu posso te ensinar.",
  [1143563228800768] = "Você ainda joga cartas agora?",
  [1143563228800512] = "Aquele cara, Luo Yao, é realmente incrível, sempre quieto e fazendo fortuna em silêncio.",
  [1143563228800256] = "<P_Heart> (Desamparado) </> Deve ter sido Rozanne quem te contou, certo? Isso está correto. O máximo que perdi foram 4 soli e 5 centavos em uma única noite – esse era todo o meu dinheiro na época.",
  [1143563228800000] = "Ouvi dizer que você perdeu muito dinheiro jogando cartas.",
  [1143563228799744] = "Mas não importa o quão longe eu vá, sempre me lembrarei de Blackthorn. Enquanto eu voltar aqui, estarei de volta em casa.",
  [1143563228799488] = "<P_Heart> (Movido) </> ...",
  [1143563228799232] = "…… <P_Heart> (Silêncio por um longo tempo) </> Porque eu quero me vingar do meu amigo, então escolhi sair daqui, para crescer, para me tornar mais forte.",
  [1143563228798976] = "Então por que você deixou Blackthorn?",
  [1143563228798720] = "Às vezes parece que ingressar na Blackthorn foi ontem, mas num piscar de olhos, tantos anos se passaram...",
  [1143563228798464] = "Lembro-me de como foi quando me tornei um Vigia Noturno , meu primeiro caso solo, meu primeiro salário e a primeira vez que perdi metade do dinheiro da refeição de um mês jogando cartas...",
  [1143563228798208] = "<P_Heart> (Com emoção) </> Blackthorn... é minha casa.",
  [1143563228797952] = "Sr. Leonard, o que Blackthorn significa para você?",
  [1143563228797696] = "Embora possamos emitir apenas uma pequena luz, desde que sejamos suficientes, sempre podemos iluminar um canto da noite escura.",
  [1143563228797440] = "Porque... ahem, embora eu tenha me juntado à Clube do Tarô , na verdade sou um Vigia Noturno da Igreja da Noite. 'A Estrela' não é apenas um símbolo da Deusa, mas também representa inúmeros Vigia Noturno companheiros.",
  [1143563228797184] = "A “Estrela” tem algum significado especial?",
  [1143563228796928] = "Sim, havia inúmeras cartas de Tarô na minha frente naquela época e, no escuro, escolhi 'A Estrela'. Agora parece que o arranjo do destino é verdadeiramente maravilhoso.",
  [1143563228796672] = "Sr. Leonard, você mesmo escolheu o codinome 'Star'?",
  [1143563228796416] = "Agora que realmente me tornei uma ‘Estrela’, entendo o significado de suas palavras.",
  [1143563228796160] = "Lembro-me do Reitor dizendo que, como crentes da Noite, somos ambos os vigias noturnos da escuridão e da luz das estrelas que a ilumina.",
  [1143563228795904] = "Talvez seja também por isso que entrei para a Igreja; parecia um lugar muito quente.",
  [1143563228795648] = "O diretor do orfanato, vovô, era muito gentil com todos, e os Vigia Noturno tios e tias muitas vezes vinham nos visitar e brincavam de 'tornar-se o maior Vigia Noturno' com a gente.",
  [1143563228795392] = "Mas eu era muito jovem naquela época, não me lembro. Só aprendi sobre isso depois de ler os arquivos, quando cresci.",
  [1143563228795136] = "Está tudo bem, foi há muito tempo. A rua inteira foi pega em um incidente Beyonder, e quando o Vigias Noturnos chegou, eu era o único que restou vivo...",
  [1143563228794880] = "Desculpe, eu não sabia...",
  [1143563228794624] = "Eu realmente nunca pensei sobre isso. Depois de deixar o orfanato da Igreja da Noite Eterna, ingressar na Igreja parecia a escolha natural.",
  [1143563228794368] = "Sr. Leonard, por que você se juntou originalmente à Igreja da Noite Eterna?",
  [1143563228794112] = "Você sente uma onda de tontura...",
  [1143563228793856] = "Um rangido de engrenagens mecânicas veio do palco.",
  [1143563228792576] = "Uma nevasca...",
  [1143563228791808] = "Onde aquele cara, Matthew, está indo? Agindo de forma sorrateira.",
  [1143563228791552] = "Afinal acabei comprando... Só não consigo engolir essa raiva.",
  [1143563228791296] = "Tomar cuidado! Se você tiver algum problema na cidade, basta mencionar o nome Matthew!",
  [1143563228791040] = "Tanta gente... O garçom ali parece estar explicando as regras do chá? Talvez haja uma pista, vamos ouvir.",
  [1143563228789504] = "Cuidado, porque tudo nesta cidade se repete.",
  [1143563228788992] = "Ontem? Fiquei ontem no hotel lendo e não saí.",
  [1143563228788736] = "......Você não perguntou ontem?",
  [1143563228788224] = "Então você encontrou! Obrigado.",
  [1143563228787968] = "Sra. Andy, você está procurando um caderno?",
  [1143563228787712] = "O personagem desta cena é... <P_Yellow> A garota de vestido longo </> . Você não pode errar ao escolhê-la.",
  [1143563228787200] = "Estou louco?!",
  [1143563228786944] = "Colocar de volta? Você deixou ele colocar de volta?!",
  [1143563228786688] = "Claro que peguei, mas ele colocou o castiçal de volta!",
  [1143563228786432] = "Você não recolheu o dinheiro?",
  [1143563228786176] = "Aquele castiçal, eu claramente o vi tirá-lo!",
  [1143563228785920] = "O que voltou aqui?",
  [1143563228785664] = "Impossível... como essa coisa voltou para cá?!",
  [1143563228785408] = "Você está me perguntando?! Você escondeu isso?",
  [1143563228785152] = "Na caixa! Foi só aqui!",
  [1143563228784896] = "Que dinheiro?",
  [1143563228784640] = "Onde está o dinheiro?!",
  [1143563228784384] = "<P_Heart> (Preciso ensinar-lhes uma lição.) </>",
  [1143563228784128] = "<P_Heart> (Na verdade, esses dois estão em conluio, fazendo um grande show para forçar os viajantes de coração mole a comprar o castiçal.) </>",
  [1143563228783872] = "Qual a pressa, o dinheiro está na caixa, não vai fugir. Vamos beber esta noite, haha!",
  [1143563228783616] = "Divida, divida, metade de cada, o suficiente para desfrutar por mais de meio ano.",
  [1143563228783360] = "Esses turistas são os mais fáceis de enganar, eles acreditam em tudo que eu digo. ‘Administrador do castelo’, hahahaha!",
  [1143563228783104] = "60 libras? Você é implacável, ainda mais caro do que eu estava vendendo!",
  [1143563228782848] = "Esqueça, você parece uma pessoa honesta. 60 libras, considere isso como pena de mim, pena de um pobre velho...",
  [1143563228782592] = "Mas eu não...",
  [1143563228782336] = "70 libras, não posso baixar mais. Levei muito esforço para tirar isso.",
  [1143563228782080] = "São duas coisas diferentes...",
  [1143563228781824] = "Espere! Já faz muito tempo que estou mostrando o local para vocês, certamente há uma taxa de serviço?",
  [1143563228781568] = "80 libras é muito caro, eu deixo passar.",
  [1143563228781312] = "Há até um brasão de família gravado na parte inferior. 80 libras, muito mais autêntico do que aquele golpista tinha, certo?",
  [1143563228781056] = "Veja este castiçal, foi passado do castelo.",
  [1143563228780800] = "Esse é o Castelo Lamud. Os turistas vêm aqui por causa deste antigo castelo.",
  [1143563228780544] = "Além desses caras, Lamud Small Town ainda merece uma visita. Deixe-me mostrar-lhe o lugar.",
  [1143563228780288] = "Moro aqui há quarenta anos, não há nada nesta cidade que eu não conheça. Eu simplesmente não suporto esses golpistas enganando as pessoas. Que tipo de lixo vale 40 libras!",
  [1143563228780032] = "Obrigado, você mora aqui?",
  [1143563228779776] = "Tudo bem, você está bem!",
  [1143563228779520] = "Esses vendedores ambulantes são especializados em enganar os transeuntes. Sr./Sra. {{|}}, não preste atenção nele.",
  [1143563228779264] = "Quem é você! Não cause problemas!",
  [1143563228779008] = "40 libras? Esse pedaço de lixo estava guardando batatas na minha casa na semana passada!",
  [1143563228778752] = "Você está procurando há muito tempo, não pode simplesmente sair assim, certo?",
  [1143563228778496] = "Não tenha tanta pressa de sair! É o destino que nos conhecemos hoje, 40 libras para você! Sinta a textura, o material!",
  [1143563228778240] = "Obrigado, mas não sei muito sobre antiguidades, então vou passar.",
  [1143563228777984] = "Sr./Sra. {{|}}, olha isso! Talheres usados ​​pelo primeiro Barão Lamud! 50 libras!",
  [1143563228777728] = "<P_Heart> (O roteiro caiu em um silêncio mortal, depois falou mecanicamente) </>",
  [1143563228777472] = "……Não!! Meu vilão perfeito – meu banquete de sangue!!",
  [1143563228777216] = "Não... como isso é possível?!",
  [1143563228776960] = "Onde essa pobre presa entrou em <P_Yellow> onde </> ? Quando a história chegará ao fim em <P_Yellow> quando </> ? E quem estará lá para testemunhar sua morte <P_Yellow> quem </>?",
  [1143563228776704] = "Aproveitando a cobertura absoluta da noite, dois bandidos sacaram suas lâminas, preparando-se para colher suas presas na esquina à frente. Posso até sentir o cheiro do sangue!",
  [1143563228776448] = "A margem isolada e deserta do rio, acompanhada apenas pelo som da água corrente e do luar carmesim. Este é realmente um excelente lugar para ser enterrado, certo?",
  [1143563228776192] = "Não pense que você ganhou. No próximo ato, eu mesmo escreverei para você...",
  [1143563228775936] = "Essa façanha ridícula na verdade interrompeu o rastreamento, e ela, ainda abalada, foi finalmente resgatada na agitação deste <P_Yellow> crepúsculo </>.",
  [1143563228775680] = "<P_Yellow> O assistente do detetive </> de repente saiu correndo da multidão, bloqueando o caminho da garota.",
  [1143563228775424] = "Considere-se sortudo por realmente poder me encontrar...",
  [1143563228775168] = "……Espere. A trama realmente progrediu até este ponto...... Isso realmente me surpreende......",
  [1143563228774912] = "A garota de vestido longo fugiu em pânico, o cruel Estripador a seguindo como uma sombra...",
  [1143563228774656] = "O luar da noite atravessava o mercado, mascarando perfeitamente o mal nas sombras.",
  [1143563228774400] = "O segundo ato termina.",
  [1143563228774144] = "Porém, o súbito aparecimento do Estripador quebrou esse lindo momento...",
  [1143563228773888] = "Ela riu ao encontrar com precisão as crianças escondidas em todos os cantos do parque. Onde quer que a luz do sol chegasse, risadas inocentes transbordavam.",
  [1143563228773632] = "<P_Yellow> A garota de vestido longo </> pisou na grama, vencendo facilmente a brincadeira de esconde-esconde.",
  [1143563228773376] = "Convidado de honra, abra rapidamente o roteiro e veja quem está faltando.",
  [1143563228773120] = "Nossa, parece que falta um personagem nessa cena.",
  [1143563228772864] = "Eles cobriram a boca, prendendo a respiração, esperando que <P_Yellow> alguém </> viesse procurar?",
  [1143563228772608] = "Um grupo de crianças travessas corria animadamente em todas as direções, escondendo-se em todos os cantos.",
  [1143563228772352] = "O sol do meio-dia brilha sobre o parque tranquilo, dissipando toda a escuridão.",
  [1143563228772096] = "O primeiro ato termina com a estreia perfeita do Estripador.",
  [1143563228771840] = "O luar carmesim brilhou na poça de sangue, testemunhando esse crime sangrento.",
  [1143563228771584] = "Quando esses policiais ridículos finalmente reagiram, eles só viram um cadáver no local…",
  [1143563228771328] = "A figura ágil do Estripador acabara de escapar com sucesso da patrulha policial.",
  [1143563228771072] = "Tudo bem, então vamos começar...",
  [1143563228770816] = "《Jack, o Estripador》... A vítima nesta peça é a mais comovente. O que você acha?",
  [1143563228770560] = "Este não serve, o método de morte é muito comum. Vamos mudar para uma tragédia que destaque melhor o seu heróico resgate da 'donzela em perigo'.",
  [1143563228770304] = "Deixe-me ver qual peça devo escolher para um convidado tão honrado...",
  [1143563228770048] = "Obrigado a ambos. Por me enviar o sol junto com esse carinha.",
  [1143563228769792] = "Foi o solo, o vento ou a Árvore Dourada que ouviu minhas palavras...",
  [1143563228769536] = "Não estará mais vazio.",
  [1143563228769280] = "Então você pode me seguir. A cadeira vazia e a tigela vazia em casa serão perfeitas para você.",
  [1143563228769024] = "Haha, concordou.",
  [1143563228768768] = "Uau... Uau!",
  [1143563228768512] = "Qual o seu nome? Que tal eu te chamar de... Pudimzinho?",
  [1143563228768256] = "Pudding também tinha um tufo de pelos brancos na cauda... mas seu rosto era pontudo, e o rosto de Pudding era redondo. Parece Pudim, mas não é. Mas isso veio até mim.",
  [1143563228767744] = "<P_Heart> (Voz trêmula) </> Pudim?",
  [1143563228767488] = "De onde veio esse carinha? Não parece um cachorro da aldeia.",
  [1143563228766976] = "Eu fui muito ganancioso? Pensando que isso se transformaria em alguma coisa.",
  [1143563228766720] = "Não parece que nada mudou. A árvore ainda é a mesma árvore, a terra ainda é a mesma terra.",
  [1143563228766208] = "Então vamos deixar aqui. Comparado com minha casa quebrada, Pudding deve gostar mais daqui.",
  [1143563228765952] = "O sol, Pudim era quem mais gostava de tomar sol...",
  [1143563228765696] = "Sim. Às vezes é o vento, às vezes é a chuva, às vezes é o calor do sol nas suas costas. Se você sente que é ele, então é ele.",
  [1143563228765440] = "Então... ainda posso sentir o Pudim?",
  [1143563228765184] = "Mas ele/ela {{|}} está certo. Minha avó faleceu há dez anos, mas sempre sinto que ela está lá, arejando as colchas em um dia bonito, e quando o vento sopra, é como se ela estivesse dando tapinhas na minha cabeça.",
  [1143563228764928] = "Eu deveria saber que era assim. Mas eu ainda queria ver com meus próprios olhos...",
  [1143563228764672] = "As pessoas aqui acreditam que a vida não desaparece verdadeiramente; ele irá acompanhá-lo de outra forma.",
  [1143563228764416] = "Você está tentando dizer... que as lendas são todas falsas? Pudim não vai voltar... certo?",
  [1143563228764160] = "Sra. Ella, na verdade...",
  [1143563228763904] = "Há muito que estou acostumado com a morte, mas de agora em diante não tenho mais nada.",
  [1143563228763648] = "Depois que acabava, eu acordava de manhã e o cobertor ao lado da cama estava vazio...",
  [1143563228763392] = "Meu cachorrinho. Ficou comigo por quinze anos.",
  [1143563228763136] = "Pudim é...",
  [1143563228762880] = "Quando a criança foi embora, eu ainda tinha Pudim.",
  [1143563228762624] = "......Quando o velho foi embora, eu disse que ainda tinha filhos.",
  [1143563228762112] = "Sra. Ella, o que é que você não consegue abandonar?",
  [1143563228761856] = "Acreditamos na infinidade da vida; o solo sabe a resposta.",
  [1143563228761600] = "Mas à medida que esta história se espalhou, foi distorcida – primeiro era sobre a abundância de frutos, depois disse que esta terra poderia tornar as pessoas imortais, e agora, tornou-se ressurreição.",
  [1143563228761344] = "A terra aqui é mágica; dá frutos o ano todo.",
  [1143563228761088] = "Há algo de especial no Lago Golden Autumn?",
  [1143563228760832] = "Cresci aqui, nunca vi tal coisa e não acredito.",
  [1143563228760576] = "Qual é a ressurreição que Ayla mencionou?",
  [1143563228760320] = "<P_Heart> (Ressurreição? Poderia haver um poder extraordinário aqui... deixe-me verificar com Visão Espiritual .) </>",
  [1143563228760064] = "<P_Heart> (Suavemente) </> Sra. Ella, venha primeiro, vamos conversar sobre isso devagar.",
  [1143563228759808] = "Ajuda! Esta senhora quer ir ao centro do lago; ela ouviu que há uma lenda de ressurreição aqui.",
  [1143563228759552] = "Essa é a lendária Árvore Dourada? Por favor, deixe-me passar...",
  [1143563228759296] = "Sra. A água é muito funda aí, não continue andando!",
  [1143563228759040] = "......Ele se levantou do chão, a “Maldição” pode ser considerada levantada, certo?",
  [1143563228758784] = "Você realmente é... suspiro!",
  [1143563228758528] = "Então vamos jurar com o mindinho.",
  [1143563228758272] = "...... Um copo.",
  [1143563228758016] = "Não, minha querida Amy, dois copos por dia!",
  [1143563228757760] = "Ficou sóbrio? Se você está acordado, venha comigo agora. Vamos ver se deixo você beber de novo!",
  [1143563228757504] = "Você é... Am, Amy?!",
  [1143563228757248] = "Eu sou sua noiva!",
  [1143563228756992] = "Não, não me toque! Eu tenho uma noiva!",
  [813715108693248] = "Parece perigoso.",
  [1143563228756736] = "Levante-se, seu grande idiota.",
  [1143563228756224] = "<P_Heart> (Sussurrando) </> Ela é tão capaz e querida, e se um dia ela achar que sou muito inútil e me abandonar?",
  [813709740516608] = "O que aconteceu?",
  [1143563228755968] = "<P_Heart> (Sussurrando) </> Uísque, meu amor. E se eu não conseguir proporcionar uma vida boa para Amelia?",
  [1143563228755712] = "Senhorita Amelia, Henry parece ainda estar resmungando alguma coisa.",
  [1143563228755456] = "......É álcool? Vá viver sua vida com seu álcool!",
  [1143563228755200] = "Uísque?",
  [1143563228754944] = "<P_Heart> (Atordoado) </> Sobre o que você está resmungando? Onde está meu uísque? Meu amado, meu irmão—",
  [813709740342016] = "De fato.",
  [813709740138240] = "Obrigado...",
  [813709739963136] = "OK.",
  [813709740004608] = "O que você está fazendo aqui?",
  [1143563228754688] = "Sr. Henry, dê uma boa olhada. Esta é Amelia, sua noiva.",
  [1143563228754432] = "Espere, senhorita, deve haver um mal-entendido aqui. Deixe-me falar com ele!",
  [1143563228754176] = "Você... você se apaixonou por outra pessoa na véspera do nosso casamento?",
  [1143563228753920] = "Um beijo de amor verdadeiro pode me fazer esquecer todos os meus problemas!",
  [1143563228753664] = "O que você disse? Vinho Henrique! Diga isso de novo!",
  [1143563228753408] = "<P_Heart> (Resmungando) </> ...Isso não é um beijo de amor verdadeiro.",
  [1143563228753152] = "A maldição foi levantada?",
  [1143563228752896] = "Gulu... não, não durma, é uma maldição.",
  [1143563228752640] = "<P_Heart> (Zombaria) </> Dormindo profundamente.",
  [1143563228752384] = "E um forte tapa na cara!",
  [1143563228752128] = "Me leve até lá, vou dar um beijo nele.",
  [1143563228751872] = "Então, você decidiu?",
  [1143563228751616] = "Ontem à noite ele abraçou uma cerveja South Wales e gritou 'Baby' dezessete vezes, mas para mim ele só disse 'Boa noite' uma vez!",
  [1143563228751360] = "Ele está bêbado de novo?",
  [1143563228751104] = "Sim, essas foram as palavras exatas.",
  [1143563228750848] = "Uma maldição? Um beijo de amor verdadeiro?",
  [1143563228750592] = "Olhar.",
  [1143563228750336] = "Repetindo?",
  [1143563228750080] = "<P_Heart> (Voz baixa) </> Cuidado, esta cidade não está certa. Tudo está se repetindo.",
  [1143563228749824] = "<P_Heart> (Observador) </> Eu nunca vi você na cidade antes... Você é de fora, certo?",
  [1143563228749568] = "Então foi aí que caiu! Muito obrigado.",
  [1143563228749312] = "Isto é o que encontrei à beira do lago.",
  [1143563228749056] = "Você me reconhece?",
  [1143563228748800] = "Com licença, você é a senhorita Andy?",
  [1143563228748032] = "Dizem que os segredos estão escondidos na floresta do outro lado do lago. Você quer dar uma olhada?",
  [1143563228747776] = "Exatamente! Eu investiguei e parece estar relacionado à Fada do Nenúfar.",
  [1143563228747520] = "E ainda dizem isso?",
  [1143563228747264] = "Falaram isso no primeiro dia que cheguei, e no segundo, terceiro, quarto dia...",
  [1143563228746240] = "É um acordo. Vou voltar e me preparar, vejo você na beira do lago amanhã!",
  [1143563228745984] = "<P_Heart> (Parece que está relacionado a Beyonders ...) </> Claro.",
  [1143563228745728] = "Ontem terminei de ler a trilogia sobre ela. Dizem que os segredos estão todos escondidos na floresta do outro lado do lago. Você quer dar uma olhada?",
  [1143563228745472] = "Repete-se como um ciclo, é muito estranho! Eu investiguei e parece estar relacionado à Fada do Nenúfar.",
  [1143563228745216] = "Falaram isso no primeiro dia que cheguei, e no segundo, terceiro, quarto dia... continuam falando a mesma coisa.",
  [1143563228744960] = "Adeus, décimo terceiro! Algo ainda mais interessante nos espera.",
  [1143563228744704] = "Você pode até roubar a consciência de estar vivo? Você é realmente apenas um carteiro?",
  [1143563228744448] = "Agora que o experimento terminou, devolvi-lhes essa consciência.",
  [1143563228744192] = "Eles não morreram; Eu simplesmente roubei a consciência deles de estarem “vivos” e os enganei fazendo-os acreditar que estavam amaldiçoados.",
  [1143563228743936] = "O que? Esta foi apenas a sua brincadeira? Você causou a morte de onze pessoas?",
  [1143563228743680] = "Apenas o décimo segundo superou minhas expectativas, então o experimento acabou.",
  [1143563228743424] = "Apenas uma experiência, brincando com eles. Os onze primeiros foram todos muito chatos.",
  [1143563228743168] = "O que está acontecendo? Ele não completou o missão , mas a maldição desapareceu?",
  [1143563228742912] = "<P_Heart> (Realização) </> Isso mesmo! Eu não morri, como pude pensar que estava morto! Eu estou livre!",
  [1143563228742656] = "O décimo segundo, você pode ir embora e não morreu.",
  [1143563228742400] = "Foi ele quem me lembrou que eu estava amaldiçoado, obrigado. Posso perguntar, posso realmente sair agora?",
  [1143563228742144] = "Agora sou muito habilidoso em montar; Eu até andei até a Montanha Nevada!",
  [1143563228741888] = "O décimo segundo, fim do jogo. Você pode ir agora.",
  [1143563228741632] = "Sim... pelo menos... ninguém mais morrerá aqui...",
  [1143563228741376] = "Você quer que a maldição pare com você e bloqueie o portão do desastre?",
  [1143563228741120] = "Também não vou mais sair por aí mentindo para as pessoas, ou minha consciência estará condenada...",
  [1143563228740864] = "Você deveria ir. Na verdade, não haverá nevasca hoje; Eu menti para você.",
  [1143563228740608] = "Fugindo? Um enorme bando de corvos virá comer sua carne; é muito assustador!",
  [1143563228740352] = "Então a maldição estará sobre você para sempre. Você já tentou fugir?",
  [1143563228740096] = "Se eu nunca completar o missão , ninguém mais se machucará novamente.",
  [1143563228739840] = "Sim, às vezes penso, por que passar a maldição um por um?",
  [1143563228739584] = "Você ainda tem um bom coração. Das cerca de uma dúzia de pessoas antes de você, você estaria livre se tivesse matado qualquer uma delas.",
  [1143563228739328] = "Por que eu iria querer matar alguém? Mesmo que eu realmente queira ir embora, não posso simplesmente matar pessoas.",
  [1143563228739072] = "Se você não quiser, então esqueça. Já se passou um mês e toda vez que chego à etapa final, simplesmente não consigo fazer isso...",
  [1143563228738816] = "<P_Heart> (Isso é muito bizarro, preciso ver o que exatamente aconteceu com você...) </>",
  [1143563228738560] = "Você me enganou aqui para me tornar um bode expiatório para acabar com sua maldição?",
  [1143563228738304] = "Pedi para eles pularem, mas ninguém quis, todos fugiram.",
  [1143563228738048] = "Já levei mais de uma dúzia de pessoas à beira do precipício, mas a minha consciência não permite; Não suporto machucar ninguém.",
  [1143563228737792] = "Todas as onze pessoas antes de mim completaram o missão e foram libertadas. Mas eu... é muito difícil.",
  [1143563228737536] = "Eu sou o décimo segundo; somente encontrando um bode expiatório poderei me livrar da maldição.",
  [1143563228737280] = "Estou morto. Para ser mais preciso, fui morto pela pessoa que foi morta pela maldição após a décima vítima!",
  [1143563228737024] = "Problemático? O que você quer dizer? Por que eu pularia de um penhasco?",
  [1143563228736768] = "Deveria ter sido eu empurrando você para baixo, mas não quero machucar ninguém... é problemático.",
  [1143563228736512] = "O que você quer dizer? Você está... me pedindo para pular de um penhasco e cometer suicídio?",
  [1143563228736256] = "……Me siga. Não se surpreenda, este não é um caminho comum.",
  [1143563228736000] = "Não se preocupe, já liderei mais de uma dúzia de pessoas, nada deu errado.",
  [1143563228735744] = "Tempo é vida, e a nevasca não espera por ninguém!",
  [1143563228735488] = "Não seria mais perigoso fazer um pequeno caminho com este tempo?",
  [1143563228735232] = "Tenho dez anos de experiência como guia, conheço um caminho pequeno, podemos descer a montanha em meia hora.",
  [1143563228734976] = "O vento está muito forte, há sinais de nevasca, devemos sair rapidamente.",
  [1143563228734720] = "Porque estamos esperando por Godot.",
  [1143563228733952] = "Vamos.",
  [1143563228733696] = "Se esperarmos por ele!",
  [1143563228733184] = "Vamos!",
  [1143563228732928] = "<P_Heart> (Levantando a voz) </> Se Godot vier, diga a ele para não se atrasar de novo!",
  [1143563228732672] = "E eles... parecem ser eternamente jovens, eternamente incapazes de partir.",
  [1143563228732416] = "Eles estão esperando pelo jovem Godot, não por mim, trinta anos depois.",
  [1143563228732160] = "Mas você...",
  [1143563228731904] = "Não, não sou Godot, vim ao lugar errado.",
  [1143563228731648] = "Você está indo embora agora, Sr. Godot?",
  [1143563228731136] = "Se você o vir, diga que estamos esperando por ele.",
  [1143563228730880] = "Nem ontem, nem amanhã, nem trinta anos depois.",
  [1143563228730624] = "Não importa, o Godot que esperamos disse que viria hoje.",
  [1143563228730368] = "Trinta anos? O Godot daquela época ainda é o Godot que esperamos?",
  [1143563228730112] = "Trinta anos? Parece que foi só um pouco.",
  [1143563228729856] = "Mas... trinta anos se passaram...",
  [1143563228729600] = "Esperando por Godot do mesmo jeito? Sim.",
  [1143563228729344] = "<P_Heart> (Tremendo) </> Você... você é o mesmo que era naquela época...",
  [1143563228729088] = "Ah! Ele está vindo!",
  [1143563228728576] = "<P_Heart> (Em uníssono) </> Isso mesmo, esperando por Godot!",
  [1143563228728320] = "......Por causa de esperar por Godot?",
  [1143563228727808] = "Mas não podemos.",
  [1143563228727552] = "Alguém está vindo, talvez devêssemos perguntar a ele.",
  [1143563228727296] = "Ele prometeu que não mentiria para nós.",
  [1143563228727040] = "Vamos esperar, amanhã é hoje e hoje é ontem.",
  [1143563228726784] = "Multar. Ele definitivamente virá amanhã, ele prometeu.",
  [1143563228726528] = "Talvez ele tenha se atrasado por alguma coisa.",
  [1143563228726272] = "Godot pode não vir hoje.",
  [1143563228726016] = "Definitivamente não o vi, caso contrário você teria trazido Godot de volta com você.",
  [1143563228725760] = "Ah! Você está de volta! Você viu Godot?",
  [1143563228725504] = "Não tem problema... só não jogue muito bem!",
  [1143563228725248] = "Haha, você está certo. Parece que tenho meu próprio talento! Sr. Gardener, eu aceito o trabalho!",
  [1143563228724992] = "Isso não é incrível? Existem tantos músicos de casamento, mas você é o único que consegue assustar os pássaros.",
  [1143563228724736] = "Acho que não podem, nem meu avô e meu pai conseguiram.",
  [1143563228724480] = "Não desanime. Sua música afugentou os corvos e ajudou o casal a resolver o conflito. Um músico de casamento comum pode fazer isso?",
  [1143563228724224] = "Eu... devo estar feliz? Estou cada vez mais longe de ser um músico de casamento...",
  [1143563228723968] = "...... Por favor, me dê algum tempo, deixe-me pensar sobre isso novamente.",
  [1143563228723712] = "Que tal! Interessado em ser um espantador de pássaros aqui?",
  [1143563228723456] = "Jovem, seu violino pode não apenas assustar os pássaros, mas também ajudar as pessoas a se apaixonarem!",
  [1143563228723200] = "Obrigado por afastar os corvos e o nosso mau humor.",
  [1143563228722944] = "Agora mesmo, quando você tocava violino, os corvos voaram de repente. Ficamos naquele tranquilo campo de flores, olhando a paisagem, e de repente nos sentimos muito melhor. Nós até nos abrimos um para o outro.",
  [1143563228722688] = "Já estávamos em desacordo e ficar constantemente irritados com esses corvos fazia com que achássemos tudo desagradável.",
  [1143563228722432] = "Estamos bem, estamos bem. Queríamos vir e agradecer.",
  [1143563228722176] = "<P_Heart> (Nervoso) </> Você está... você está bem?",
  [1143563228721920] = "Mas eu quero ser um músico de casamentos, não um espantador de pássaros...",
  [1143563228721664] = "Por que você está indo embora? Ficar! Aqueles corvos vêm toda semana estragar minhas tulipas, e agora mesmo todas voaram embora! 3 soli por dia, você está dentro?",
  [1143563228721408] = "<P_Heart> (Nervoso) </> Eu... eu assustei os pássaros? Sinto muito, vou embora imediatamente—",
  [1143563228721152] = "Jovem, você fez isso?",
  [1143563228720896] = "Huh, os corvos aqui...",
  [1143563228720640] = "Que é aquele! Serrar madeira no meio do dia...",
  [1143563228720384] = "Então vamos experimentar 'Twinkle Twinkle Little Star' do Imperador Roselle.",
  [1143563228720128] = "Tente tocar músicas mais simples? E você não precisa necessariamente limitar o tema da sua música aos casamentos.",
  [1143563228719872] = "Mas que outras músicas podem ser tocadas em um casamento?",
  [1143563228719616] = "Voltando à sua apresentação, a 'Marcha Nupcial' é muito complexa?",
  [1143563228719360] = "Você está certo, {{PlayerName}}! Agora não é hora de ficar deprimido!",
  [1143563228719104] = "Não fique tão deprimido ainda, ainda temos um caminho! Não foi por isso que você veio até mim!",
  [1143563228718848] = "<P_Heart> (A 'Marcha Nupcial' poderia ser muito complexa? Deixe Albert tentar algo mais simples.) </>",
  [1143563228718592] = "Um músico de casamentos se tornou um mestre em separações.",
  [1143563228718336] = "<P_Heart> (Deprimido) </> Não, meu violino foi o gatilho...",
  [1143563228718080] = "Não é sua culpa; eles já tiveram conflitos.",
  [1143563228717824] = "...... Meu piano pode fazer as pessoas se separarem?",
  [1143563228717568] = "Tudo bem, vamos terminar!",
  [1143563228717312] = "De novo? Já estou farto, vamos terminar!",
  [1143563228717056] = "Não era essa sua peça favorita? Agora você está me culpando?",
  [1143563228716800] = "Se você não tivesse insistido em ir ao teatro, teríamos pegado o trem.",
  [1143563228716544] = "Meu Deus... que som é esse? Como aquela apresentação no teatro da última vez, foi terrível!",
  [1143563228716288] = "<P_Heart> (Música indescritível...) </>",
  [1143563228715776] = "Você está certo, eu conheço um lugar muito bom, siga-me!",
  [1143563228715520] = "Que tal experimentar um lugar diferente? Uma mudança de cenário pode ajudar na performance.",
  [1143563228715264] = "Não tenho grandes exigências; Eu só quero poder me apresentar em casamentos. Você estaria disposto a ouvir minha performance e me dar alguns conselhos?",
  [1143563228715008] = "Três gerações da minha família foram músicos da corte; meu avô era o concertino e meu pai se apresentava para a Rainha. Da minha geração...",
  [1143563228714752] = "...... O nível é bastante único.",
  [1143563228714496] = "Esqueci de me apresentar, meu nome é Albert e sonho em ser músico de casamentos!",
  [1143563228714240] = "Sim, está certo! Esta peça é a 'Marcha Nupcial'.",
  [1143563228713984] = "É você quem está tocando violino aqui?",
  [1143563228713472] = "Não - a margem deserta do rio... a localização original <P_Yellow></> era perfeita; Eu te aviso para não agir precipitadamente!",
  [1143563228713216] = "Pare imediatamente! A noite escura é o momento perfeito <P_Yellow></> ; Eu nunca permitirei que você estrague esta excelente atmosfera!",
  [1143563228712960] = "Não são permitidas alterações! Tire suas mãos! Todos os <P_Yellow> caracteres </> estão em posição; ninguém está autorizado a interromper esta execução perfeita!",
  [1143563228712448] = "Preparação do palco em andamento...",
  [1143563228712192] = "<P_Heart> (O horário desta cena é...) </>",
  [1143563228711936] = "<P_Heart> (O personagem desta cena é...) </>",
  [1143563228711680] = "A próxima história é...",
  [1143563228711424] = "A comunicação com o motorista da carruagem revela que o Estripador provavelmente foi morto <P_Yellow> fora da delegacia </>; registre-o no script.",
  [1143563228711168] = "Qual é o local onde o Estripador termina?",
  [1143563228710912] = "A julgar pela conversa dos moradores, o horário em que a trama acontece deveria ser <P_Yellow> uma noite tão clara quanto o dia </> ; registre-o no script.",
  [1143563228710656] = "Qual é a hora em que o Estripador termina?",
  [1143563228710400] = "A julgar pela conversa da equipe, o personagem que acabou com o Estripador deveria ser <P_Yellow> o capitão da polícia </> ; registre-o no script.",
  [1143563228710144] = "Quem é o personagem que acaba com o Estripador?",
  [1143563228709888] = "O detetive me disse a hora certa; o horário em que a trama ocorre deve ser <P_Yellow> dusk </> ; registre-o no script.",
  [1143563228709632] = "Quando a garota é salva?",
  [1143563228709376] = "Segundo a conversa entre o detetive e o adivinho, o papel de quem salva a menina deveria ser <P_Yellow> o assistente do detetive </> ; registre-o no script.",
  [1143563228709120] = "Quem é o personagem que salva a garota?",
  [1143563228708864] = "De acordo com as dicas do roteiro, o papel do fantasma deveria ser <P_Yellow> a garota de vestido longo </> ; registre-o no script.",
  [1143563228708608] = "Quem é aquele que faz o papel do fantasma no esconde-esconde?",
  [1143563228707584] = "Preste atenção às microexpressões dos convidados, observe anomalias no ambiente e observe se há algo que “não pareça muito certo”.",
  [1143563228707328] = "Observar. Embora esta seja uma habilidade básica para o Espectador Caminho , para um Beyonder , simular um espectador em um ambiente desconhecido é uma escolha segura e sábia.",
  [1143563228706304] = "Tudo bem, eu notei isso. Definitivamente trarei de volta '2-327' com segurança.",
  [1143563228706048] = "O baile está cheio de pessoas complexas, então observe com atenção e não tire conclusões precipitadas muito cedo. Lembre-se, um Espectador não sobe ao palco.",
  [1143563228705792] = "Você é um Beyonder do Espectador Caminho ; não há ninguém mais adequado do que você. Preste atenção nas microexpressões dos convidados, perceba eventuais anomalias no ambiente e fique atento a tudo que ‘não parece muito certo’.",
  [1143563228705536] = "Não se preocupe, preparamos uma identidade para você: um comerciante de comércio exterior de Port Enmat. Um jantar de investimento será realizado hoje à noite em Heywood Manor, e você pode usar este convite para entrar no baile da mansão.",
  [1143563228705280] = "Qual é a situação de Heywood Manor e há alguma informação disponível? Como devo me infiltrar na mansão?",
  [1143563228705024] = "Esta é a informação em '2-327'.",
  [1143563228704768] = "Preciso rastrear o outro Artefato Selado com Mira e Evan, então devo localizá-lo o mais rápido possível. Portanto, quero confiar a você a missão de trazer de volta “2-327”.",
  [1143563228704512] = "O outro, numerado “2-327”, um Artefato Selado chamado “See Me”, tem um traço espiritual mais claro. Depois de repetir adivinhação , confirmamos que está em Heywood Manor nos subúrbios de Tingen.",
  [1143563228704256] = "Nas últimas três semanas, rastreamos o paradeiro dos Artefatos Selados. O mais perigoso esconde flutuações espirituais, e só podemos confirmar que está em Tingen.",
  [1143563228704000] = "Partimos de Backlund e escolhemos especificamente uma rota interior. Mas a outra parte foi muito clara sobre nossa rota e configuração de pessoal e armou uma emboscada no caminho.",
  [1143563228703744] = "Esses dois são Vigia Noturno colegas de Enmat Port, Mira e Evan. Há três semanas, os dois Artefatos Selados que eles eram responsáveis ​​pelo transporte foram roubados no caminho.",
  [1143563228703488] = "Ela parece ser capaz de usar palavras para manipular as emoções dos outros. Não parece uma habilidade social comum; é uma habilidade Beyonder. Poderia ser o Instigador do Assassino Caminho?",
  [1143563228703232] = "O cavalheiro que conversa com ela parece muito agitado. Espere... ela só disse uma frase; por que a senhora ao lado deles está chorando?",
  [1143563228702976] = "O anel tem um mecanismo... é uma arma escondida? Ela está procurando uma chance de atacar? Por que ela ainda não agiu?",
  [1143563228702720] = "Mas sob o anel, uma pequena ponta de agulha era vagamente visível, brilhando sob a luz.",
  [1143563228702464] = "Ela era sem dúvida a pessoa mais atraente da sala. Suas feições eram lindas a ponto de serem irreais, e seus olhos verde-acinzentados carregavam um distanciamento casual – como se ela estivesse aproveitando o baile, mas também observando a todos com fria indiferença.",
  [1143563228702208] = "Albert: Por favor, descanse em paz... Vou encontrar um lugar para você descansar...",
  [1143563228701952] = "Albert: Jovem Mestre, fique atrás de mim!",
  [1143563228701696] = "Albert: Depois que o fogo estiver aceso, não estará mais escuro.",
  [1143563228701440] = "Albert: Obrigado... obrigado a ambos.",
  [1143563228701184] = "<P_Heart> (Vira um cartão - O Eremita, na posição vertical) </> Ela entende o significado de adivinhação melhor do que qualquer um de nós.",
  [1143563228700928] = "<P_Heart> (Abaixa o jornal) </> O quê?",
  [1143563228700672] = "<P_Heart> (Senta-se) </> Ela é uma verdadeira Vidente.",
  [1143563228700416] = "Como foi? Ela estava falando bobagens?",
  [1143563228700160] = "Você está de volta? Você encontrou essa fraude?",
  [1143563228699904] = "Volte. Essas pessoas do clube devem estar esperando que você traga de volta meu destino miserável. Você pode contar a eles sobre meu encontro na Montanha Nevada para deixá-los felizes.",
  [1143563228699648] = "Eu vou lembrar disso.",
  [1143563228699392] = "Lembre-se, um Vidente é uma testemunha do destino, não um juiz.",
  [1143563228699136] = "<P_Heart> (Sorrisos) </> Você é um bom Vidente agora.",
  [1143563228698880] = "Às vezes, precisamos expressar o que vemos de uma maneira diferente.",
  [1143563228698624] = "Nada mal, o que mais?",
  [1143563228698368] = "O que é visto em adivinhação é apenas o caminho mais provável. Como interpretá-lo e como percorrê-lo está, na verdade, em suas próprias mãos.",
  [1143563228698112] = "<P_Heart> (Olha para você) </> Você aprendeu muito bem! Jovem/mulher {{|}}!",
  [1143563228697856] = "<P_Heart> (Enxuga as lágrimas) </> Seguiremos em frente.",
  [1143563228697600] = "Obrigado a ambos. Eu... vamos nos lembrar disso.",
  [1143563228697344] = "Esta era está mudando: máquinas a vapor, impressoras, novas máquinas aparecem todos os dias. Aqueles que podem aprender coisas novas não serão deixados para trás pela época.",
  [1143563228697088] = "O Valete de Espadas olha para o céu, procurando a direção do vento.",
  [1143563228696832] = "As coisas que você aprende acabarão por se tornar a espada em sua mão.",
  [1143563228696576] = "<P_Heart> (Pega o Valete de Espadas) </> Esta é a sua carta. Segurando uma espada na mão, os olhos voltados para as alturas.",
  [1143563228696320] = "Quando sua habilidade for boa o suficiente, haverá pessoas dispostas a pagar mais por seu trabalho artesanal.",
  [1143563228696064] = "<P_Heart> (Assume) </> O artesão não está apenas esculpindo pentáculos; ele também está desenvolvendo sua própria habilidade.",
  [1143563228695808] = "Mas olhe para a parede – já há seis pendurados lá. Cada vez que ele esculpe um, há mais um na parede. Um dia, a parede estará coberta de pentáculos.",
  [1143563228695552] = "<P_Heart> (Pega o Oito de Ouros) </> Esta é a sua carta. Mãos de artesão, esculpindo uma por uma. Muito lento, um trabalho muito árduo.",
  [1143563228695296] = "<P_Heart> (Olha para você) </> Desta vez, faremos isso juntos.",
  [1143563228695040] = "Queremos nos casar, mas não sabemos o que o futuro nos reserva.",
  [1143563228694784] = "Meu nome é Anna e trabalho como empregada doméstica para uma família rica. Ele é Peter e trabalha em uma gráfica.",
  [1143563228694272] = "<P_Heart> (Sussurrando) </> Que tal? Viu como você aprendeu bem?",
  [1143563228694016] = "<P_Heart> (Olha para você) </> Este é meu novo companheiro. Faremos o adivinhação para você juntos.",
  [1143563228693760] = "Senhora Hali, gostaria de lhe pedir que adivinhasse o nosso futuro.",
  [1143563228693504] = "Esse cara tem um cheiro azedo e ruim; o olfato de um gato é muito sensível! Comparado com a dor dele, estou mais preocupado com a dor do gato!",
  [1143492898235648] = "Ribeira deserta",
  [1143563228620032] = "Mas você não é um servo, Albert. Você é minha família.",
  [1143563228692224] = "Temperança.",
  [1143563228691968] = "<P_Heart> (Segura o gato com força) </> Nosso relacionamento está rompido?",
  [1143563228691712] = "Um jovem veio até você hoje adivinhação, carregando um gato.",
  [1143563228691456] = "Senhora Hailey! Você está de volta!",
  [1143563228691200] = "<P_Heart> (Risos) </> Na minha idade, é melhor ficar em uma baia quente adivinhação; não é adequado para escalar montanhas.",
  [1143563228690944] = "Bom. Ver você significa que a carta da Torre daquela época já foi jogada por você como uma Torre invertida. Não vou mais me preocupar.",
  [1143563228690688] = "O destino não é apenas uma pessoa lutando sozinha? Não se preocupe, tia Hali!",
  [1143563228690432] = "Cuide-se aqui sozinho...",
  [1143563228690176] = "<P_Heart> (Aponta para longe) </> Siga esta estrada até o fim e você poderá sair da Montanha Nevada. Ainda tenho que ficar na Montanha Nevada por alguns dias, então não vou continuar me despedindo de você.",
  [1143563228689920] = "Obrigado, Irene.",
  [1143563228689664] = "<P_Heart> (Coça o nariz) </> Eu sou realmente incrível? Então devo tirar todos vocês em segurança.",
  [1143563228689408] = "A pequena Aileen é minha verdadeira professora no caminho de adivinhação .",
  [1143563228689152] = "Uma carta de Tarô não é apenas uma carta? Não importa qual seja o cartão; o que importa é como você joga.",
  [1143563228688896] = "Se for invertida – o significado da Torre invertida é “reconstrução após destruição”.",
  [1143563228688640] = "Invertida... A Torre.",
  [1143563228688384] = "<P_Heart> (Inverte a posição da carta do Tarô) </> Então vou apenas mudar sua posição.",
  [1143563228688128] = "Irene, é muito perigoso para uma menina como você explorar. A Torre é uma carta que prediz desastre.",
  [1143563228687872] = "Não vou me assustar com este cartão.",
  [1143563228687616] = "Vislumbramos fragmentos do destino futuro através de adivinhação , mas ficamos intimidados pelos fragmentos, perdendo a possibilidade de um destino completo.",
  [1143563228687360] = "Foi que depois que ela acreditou, ela nunca mais avançou.",
  [1143563228687104] = "Antes de morrer, ela segurou minha mão e disse: a coisa que ela mais se arrependeu na vida foi não acreditar em adivinhação.",
  [1143563228686848] = "Na verdade, não foi.",
  [1143563228686592] = "Eu sei que você sempre se sentiu culpado. Você acha que foi o seu adivinhação que matou minha mãe.",
  [1143563228686336] = "Tosse tosse... Achei que você iria me repreender algumas vezes quando me visse novamente.",
  [1143563228686080] = "Me ajude. Use seu adivinhação para encontrar a localização de Aileen.",
  [1143563228685824] = "Procurando por alguém. Uma garota chamada Aileen. Ouvi dizer que ela era ativa nas Montanhas Nevadas, mas meu adivinhação talento não é tão bom quanto o seu. Só consegui calcular uma direção geral; Não sei quando ela vai passar por aqui.",
  [1143563228685568] = "Em um momento como este, você ainda está com vontade de brincar... o que exatamente você está fazendo vindo para a Montanha Nevada?",
  [1143563228685312] = "Quase morri! Suspirar! Parece que ainda não consigo interpretar cegamente para mim mesmo.",
  [1143563228685056] = "Não fale ainda. Eu vou te tirar.",
  [1143563228684800] = "<P_Heart> (Sorriso fraco) </> Verdadeiramente... talentoso.",
  [1143563228684544] = "Eu adivinhei que você estava em perigo!",
  [1143563228684288] = "<P_Heart> (Abre os olhos fracamente) </> É você... como você veio aqui...",
  [1143563228684032] = "<P_Heart> (Corre para frente) </> Haley!",
  [1143563228683776] = "Ela não foi ver ninguém... ela é...",
  [1143563228683520] = "Montanha nevada de Hornacis.",
  [1143563228683264] = "Quando usei Pendulum Adivinhação para descobrir o paradeiro dela, além do Golden Autumn Lake, houve outro lugar que teve uma forte reação.",
  [1139165182639104] = "Eu acredito em você.",
  [1143563228683008] = "Isso não está certo. Agora mesmo, em frente à lápide, ela não parava de falar sobre a morte de Catherine e sua própria culpa.",
  [1143563228682752] = "A Torre... destruição e colapso.",
  [1143563228682496] = "Adeus, Catarina.",
  [1143563228682240] = "<P_Heart> (Olha para longe) </> Não, vou ver alguém. Alguém por quem esperei muito tempo.",
  [1143563228681984] = "Obrigado. Você vai voltar para Tingen?",
  [1143563228681728] = "Você é um adivinho talentoso. Lembre-se do que eu disse hoje. Eu deveria ir.",
  [1143563228681472] = "O cartão ainda é o mesmo cartão. Mas como contar aos outros — essa é a verdadeira habilidade de um adivinho.",
  [1143563228681216] = "Não alterando o adivinhação em si. Está mudando a forma como “interpreto” o Tarot.",
  [1143563228680960] = "<P_Heart> (Silêncio) </> Então você mudou a maneira como você se apresenta adivinhação .",
  [1143563228680704] = "Desde o dia em que Catherine morreu, parei apenas de ler as cartas. Aprendi a olhar para a pessoa por trás das cartas.",
  [1143563228680448] = "<P_Heart> (Olha para você) </> Mas esse foi o destino \"eu vi\"; Falei deles como o “único” destino.",
  [1143563228680192] = "Sim. Isso mesmo. O destino deles foi de fato o mesmo que eu vi.",
  [1143563228679936] = "……O resultado do seu adivinhação está correto?",
  [1143563228679680] = "Amy pediu a alguém que me trouxesse uma carta. Tinha apenas uma frase - \"Acho que todos os dias, se eu não tivesse deixado você fazer isso adivinhação naquele dia.\"",
  [1143563228679424] = "Alguns anos depois, Catherine morreu de doença em uma cabana à beira do lago. Joanna caiu e se machucou durante uma apresentação e nunca mais conseguiu ficar de pé.",
  [1143563228679168] = "<P_Heart> (Abaixa a cabeça) </> Catherine começou a beber muito. Joanna desistiu de praticar. Amy se casou com um homem que ela não amava.",
  [1143563228678656] = "Amy desenhou o Cavaleiro de Copas invertido. Eu disse a ela que seu amor não teria resultado.",
  [1143563228678400] = "Joanna sacou o Dez de Espadas. Eu disse a ela que isso significava fim e fracasso, e que não importava quão bem ela praticasse, ela nunca chegaria ao palco da cidade grande.",
  [1143563228678144] = "Catarina desenhou o Cinco de Ouros. Eu disse a ela que a pobreza não tinha fim e que nossos sonhos nunca se tornariam realidade.",
  [1143563228677888] = "O que você viu?",
  [1143563228677632] = "Um dia, eles me importunaram para adivinhar seu futuro.",
  [1143563228677376] = "<P_Heart> (Silêncio por um momento) </> Quando eu era jovem, trabalhei em um circo. Catherine, Joanna, Amy – nós quatro espremidas numa caravana, praticando acrobacias juntas, partilhando um único pedaço de pão entre nós quatro.",
  [1143563228677120] = "<P_Heart> (Acaricia a lápide) </> O nome dela é Catherine. Costumávamos ser melhores amigos.",
  [1143563228676864] = "<P_Heart> (Pausa) </> Posso te ensinar o que é um bom adivinho. Me siga.",
  [1143563228676608] = "Um bom adivinho interpreta mais do que apenas as cartas.",
  [1143563228676352] = "Eu sei. É por isso que eu disse que você não é um bom adivinho.",
  [1143563228676096] = "Eu... não sabia disso.",
  [1143563228675840] = "<P_Heart> (Tom fica pesado) </> Se eu tivesse dito a ela \"recusando mudanças, incapaz de renascer\", ela teria entrado neste lago esta noite.",
  [1143563228675584] = "Aquela senhora agora há pouco. O marido dela morreu neste lago no inverno passado.",
  [1143563228675328] = "<P_Heart> (Atordoado) </> O que você quer dizer?",
  [1143563228675072] = "Mas você não é um bom adivinho.",
  [1143563228674816] = "Você conhece o Tarô muito bem. Na vertical, invertido, você pode recitar as interpretações de cada sistema.",
  [1143563228674560] = "<P_Heart> (Suavemente) </> Bom. Tenha cuidado no caminho.",
  [1143563228674304] = "Madame Haley, eu... eu voltarei primeiro.",
  [1143563228674048] = "<P_Heart> (Olha para você com calma) </> Terminou?",
  [1143563228673792] = "<P_Heart> (Inexpressivamente) </> Recusando mudança... estagnação...",
  [1143563228673536] = "Não prevê diretamente a morte.",
  [1143563228673280] = "<P_Heart> (Para a velha) </> No Tarot, a interpretação padrão da Morte invertida é uma recusa à mudança, estagnação e uma incapacidade de alcançar um novo começo.",
  [1143563228673024] = "<P_Heart> (Passos à frente) </> Morte, invertida.",
  [1143563228672768] = "Eu também sou um adivinho. Posso dar uma olhada no cartão que você tirou?",
  [1143563228672512] = "No entanto, ela demorou um pouco desta vez. Poderia ter acontecido alguma coisa?",
  [1143563228672256] = "Não, ela nunca menciona essas coisas para nós. Ela sai nesta época todos os anos, dizendo que vai visitar um velho amigo.",
  [1143563228672000] = "Você sabe para onde ela foi?",
  [1143563228671744] = "Aliás, ela está sempre cercada de gatos. E ratos também. Certa vez, um rato saiu do esgoto e subiu na mesa dela, como se a estivesse ouvindo falar.",
  [1143563228671488] = "Mas ela parece ter apenas vinte e poucos anos.",
  [1143563228671232] = "Ela faz adivinhação nesta rua há mais de uma dúzia de anos.",
  [1143563228670976] = "Você conhece Madame Haley há muito tempo?",
  [1143563228670720] = "Foram as palavras de Madame Haley que me fizeram decidir. Ela estava certa, contanto que você fique de pé, as espadas permanecerão no chão.",
  [1143563228670464] = "<P_Heart> (Suspiros) </> Naquele ano mandei meu filho de volta para o campo. Mais tarde, houve uma peste na nossa rua e várias crianças perderam-se.",
  [1143563228670208] = "Embora o céu esteja escuro, o amanhecer segue a noite. Esta pessoa está deitada, mas ainda está viva. Enquanto ele se levantar, as dez espadas permanecerão no chão e não poderão ser retiradas.",
  [1143563228669952] = "Ela disse: todas as espadas caíram, não haverá mais nenhuma.",
  [1143563228669440] = "Não, não. Não foi isso que Madame Haley disse.",
  [1143563228669184] = "O significado desta carta é... fim, fracasso, o pior final possível.",
  [1143563228668928] = "Dez de Espadas em pé. Uma pessoa deitada de bruços no chão com dez espadas enfiadas nas costas.",
  [1143563228668672] = "<P_Heart> (Sorri) </> Muito melhor. Ela pode sair da cama e andar por aí.",
  [1143563228668416] = "Como está sua esposa agora?",
  [1143563228668160] = "<P_Heart> (Voz mais baixa) </> No inverno em que minha esposa ficou doente, eu senti que não conseguiria aguentar. Foram as palavras de Madame Haley que me impediram de desistir.",
  [1143563228667904] = "As luzes da igreja estão acesas e a porta não está trancada. No inverno mais frio, duas pessoas caminhando amontoadas sempre encontram uma porta pela qual possam entrar.",
  [1143563228667648] = "Ela disse: olha essas duas pessoas, elas estão vestidas com trapos, mas estão apoiadas uma na outra.",
  [1143563228667392] = "O que ela disse?",
  [1143563228667136] = "<P_Heart> (Balança a cabeça) </> O que você disse é completamente diferente do que disse Madame Haley.",
  [1143563228666880] = "O significado desta carta é... a pobreza continuará, a situação é difícil e levará muito tempo para melhorar.",
  [1143563228666624] = "Cinco de Ouros invertidos. Duas pessoas esfarrapadas passando por uma igreja em uma noite de neve.",
  [1143563228666368] = "Sim, também quero ver quem é mais preciso, você ou Madame Haley.",
  [1143563228666112] = "<P_Heart> (Tira uma moeda) </> Já que Madame Hali não está aqui, que tal você fazer um adivinhação para mim?",
  [1143563228665856] = "Você tem esse temperamento. Madame Haley também tem isso: ficar parada ali faz as pessoas quererem contar a ela seus problemas.",
  [1143563228665600] = "Como você sabia que eu era um adivinho?",
  [1143563228665344] = "<P_Heart> (Avalia você) </> Você também é um adivinho? Você parece um pouco diferente das pessoas do clube.",
  [1143563228665088] = "Difícil dizer. Às vezes ela vem duas vezes por semana, às vezes ela fica fora por meio mês.",
  [1143563228664832] = "Quando ela estará de volta?",
  [1143563228664576] = "Procurando por Madame Haley? Ela não está aqui hoje.",
  [1143563228664320] = "<P_Heart> (Olha ao redor) </> Não está aqui?",
  [1143563228664064] = "<P_Heart> (balança a cabeça) </> Adivinhação é uma questão de precisão. O fato de ela falar bobagens como essa é uma blasfêmia contra o Tarô.",
  [1143563228663808] = "Ela disse a um peixeiro que sua esposa iria melhorar – a carta era claramente o Cinco de Ouros invertido, pobreza e doença. Ela insistiu em dizer “duas pessoas apoiadas uma na outra podem esperar pela primavera”. Se isso não é uma farsa, o que é?",
  [1143563228663552] = "Por que você quer ir procurá-la? Eu aconselho você a não fazer isso. Um verdadeiro adivinho não consegue aprender seu tipo de bobagem.",
  [1143563228663296] = "Acho que o nome dela é Hali. Bem na esquina da Iron Cross Street, debaixo de um plátano.",
  [1143563228663040] = "Qual é o nome do adivinho de quem você está falando? Onde ela monta sua barraca?",
  [1143563228662784] = "Eu a vi uma vez de longe. Ela tinha vários gatos vadios deitados a seus pés e um rato agachado em sua mesa. Essas feras eram tão obedientes quanto animais de estimação na frente dela.",
  [1143563228662528] = "O mais irritante é que ela é especializada em adivinhação para os pobres. Esses vendedores ambulantes, empregadas domésticas e condutores de carruagens - o que eles sabem sobre adivinhação? Eles acreditam em tudo o que ela diz.",
  [1143563228662272] = "É tudo culpa daquela mulher da Rua Cruz de Ferro! Ela roubou todos os negócios!",
  [1143563228662016] = "<P_Heart> (Suspiros) </> Apenas dois clientes vieram hoje. Se isso continuar, não poderei pagar o aluguel.",
  [1143563228661760] = "Pelo menos ele pagou. Melhor do que alguns clientes.",
  [1143563228661504] = "<P_Heart> (Esfrega as têmporas) </> Deusa... que tipo de mundo é esse.",
  [1143563228661248] = "<P_Heart> (Abraça o gato com força) </> A lei não é importante. O importante é que a Deusa saiba que estamos apaixonados.",
  [1143563228660992] = "É isso que a carta significa. Mas... a lei não permite que humanos e gatos se casem.",
  [1143563228660736] = "<P_Heart> (Olhos brilhando) </> Sério? Podemos nos casar?",
  [1143563228660480] = "A carta dos Amantes. A bênção de um anjo, uma união perfeita.",
  [1143563228660224] = "<P_Heart> (Nervoso) </> O que isso significa?",
  [1143563228659968] = "<P_Heart> (Suprimindo um sorriso) </> Deixe-me fazer isso.",
  [1143563228659712] = "Este é o Adivinhação Clube, não um asilo!",
  [1143563228659456] = "<P_Heart> (Sério) </> Sim. Eu a amo mais do que tudo. Ela se esfrega na minha mão e deita no meu colo quando estou triste. Quero saber se nosso relacionamento tem futuro.",
  [1143563228659200] = "<P_Heart> (Barba tremendo) </> Mary Ann... esse gato é?",
  [1143563228658688] = "Meu nome é Dennis. Estou com pressa! Rápido, me ajude a calcular! <P_Heart> (segura o gato bem alto) </> Mary Ann e eu podemos nos casar?",
  [1143563228658432] = "......Eu não sei, está muito quieto aqui, não precisa pensar.",
  [1143563228658176] = "Isso já é muito impressionante. Há quanto tempo você está agachado aqui?",
  [1143563228657920] = "O que isso tem a ver com...",
  [1143563228657664] = "Mas você sabe. Você mesmo caminhou até aqui e optou por se agachar, certo?",
  [1143563228657408] = "Os cogumelos não precisam de nada.",
  [1143563228657152] = "……Não vai.",
  [1143563228656896] = "<P_Heart> (Ele abaixa a cabeça, parecendo um pouco triste.) </>",
  [1143563228656640] = "...... Não preciso de nada.",
  [1143563228656384] = "Então, do que os cogumelos precisam?",
  [1143563228656128] = "……Cogumelos não precisam de fotossíntese.",
  [1143563228655872] = "Você sabe que não pode fotossintetizar enquanto está agachado, certo?",
  [1143563228655360] = "Olá, você é um... cogumelo?",
  [1143563228655104] = "Eu sou o mesmo. Atrás de mim estão aqueles que precisam ser protegidos.",
  [1143563228654848] = "Pelo bem de pessoas importantes, qualquer um pode se tornar corajoso...",
  [1143563228654592] = "Vou procurar minha irmã agora, adeus!",
  [1143563228654336] = "Obrigado por me dar coragem para saber que na verdade não sou tão fraco. Posso proteger minha irmã agora, haha!",
  [1143563228654080] = "Eu também não pensei muito. Quando vi alguém sendo intimidado, simplesmente corri.",
  [1143563228653824] = "Pensei, não posso deixar você subir sozinho, tenho que fazer alguma coisa também.",
  [1143563228653568] = "Quando acabei de correr, de repente não tive mais medo. Antes eu sempre tinha medo que eles retaliassem, medo que minha irmã se machucasse...",
  [1143563228653312] = "Você é muito corajoso!",
  [1143563228653056] = "Ha... eu consegui!",
  [1143563228652800] = "Eu... eu também vou!",
  [1143563228652544] = "Esses caras... ainda não aprenderam a lição?",
  [1143563228652288] = "Eles estão de volta!",
  [1143563228652032] = "E aquele cara de antes? E aquele pirralho!",
  [1143492898195456] = "Vamos parar aqui",
  [1143492898202624] = "Deixe isso em paz",
  [1143563228651776] = "Cada vez que vejo alguém como você aparecer, sinto... bem, esse lugar ainda não é tão ruim assim. Eu quero ser alguém assim também.",
  [1143563228651520] = "Para poder afastar esses bandidos e tornar este lugar um pouco mais seguro.",
  [1143563228651264] = "……Assim?",
  [1143563228651008] = "É tão bom ser como você.",
  [1143563228650752] = "Está tudo bem, contanto que você esteja bem.",
  [1143563228650240] = "Hmph, espere!",
  [1143563228649984] = "Pare com o absurdo! Entregue!",
  [1143563228649728] = "Esta é a mensalidade da minha irmã!",
  [1143563228649472] = "Bom, desejo-lhe sucesso.",
  [1143563228649216] = "Embora eu tenha que passar fome por mais alguns dias, irei procurar trabalho novamente!",
  [1143563228648960] = "É a única coisa que resta da nossa família; as memórias que carrega são mais preciosas do que qualquer outra coisa.",
  [1143563228648704] = "Mas alguém o guardou por tantos anos por causa de uma promessa...",
  [1143563228648448] = "Para outros, esta é apenas uma casa em ruínas; não vai render muito dinheiro.",
  [1143563228648192] = "Ele se foi. Você ainda vai vender esta casa?",
  [1143563228647936] = "Você já cumpriu seu voto e pode seguir em frente. Eu irei guiá-lo com o poder da luz.",
  [1143563228647680] = "Você se parece um pouco com o Mestre.",
  [1143563228647424] = "Eu... obrigado por guardá-lo por tanto tempo.",
  [1143563228647168] = "Não, esta casa ainda está aqui e os descendentes daquele mestre ainda estão aqui.",
  [1143563228646912] = "Então, durante todos estes anos, a minha missão... nunca será concluída?",
  [1143563228646656] = "<P_Heart> (Suavemente) </> Ele já se foi e não voltou daquela guerra. Você se lembra?",
  [1143563228646400] = "Mestre, mas o Mestre disse que eu deveria esperar.",
  [1143563228646144] = "Só sei que a família sofreu um duro golpe uma vez e muitas pessoas morreram.",
  [1143563228645888] = "Guerra? Algum de seus ancestrais participou da guerra?",
  [1143563228645632] = "Devo ficar, guardar a casa, proteger a patroa e o jovem patrão e esperar que ele volte.",
  [1143563228645376] = "Sim, o Mestre teve que ir para a guerra. Quando partiu para a campanha, confiou-me a casa, dizendo que eu era o servo em quem ele mais confiava.",
  [1143563228645120] = "Você está esperando por esse “Mestre”?",
  [1143563228644864] = "Velho... que velho mestre? Deusa, vou molhar as calças...",
  [1143563228644608] = "O Mestre me disse para guardar a casa e esperar seu retorno, então estive esperando...",
  [1143563228644352] = "Não tenha medo, ele não parece ter más intenções. Ele está... esperando por alguém?",
  [1143563228644096] = "<P_Heart> (Aterrorizado) </> Existem realmente fantasmas? Um fantasma! Um fantasma!",
  [1143563228643840] = "Esperar o quê?",
  [1143563228643584] = "Mestre... me disse para esperar aqui...",
  [1143563228641280] = "Haha, de nada.",
  [1143563228641024] = "Eu te amo!",
  [1143563228640768] = "Eu te causei problemas, muito obrigado!",
  [1143563228640512] = "Vamos. Pegue seu “querido”, agradeça a esse irmão/irmã {{|}} que me ajudou a encontrar você e vamos para casa.",
  [1143563228640256] = "......Você realmente sabe como nomear as coisas.",
  [1143563228640000] = "......Hehe.",
  [1143563228639744] = "Querido!",
  [1143563228639488] = "Diga-me, qual é o nome do papagaio?",
  [1143563228639232] = "Da próxima vez, diga-me diretamente. Mamãe promete não repreender você.",
  [1143563228638976] = "Eu sou sua mãe e uma mãe sempre estará ao seu lado.",
  [1143563228638720] = "Estou com raiva, com raiva por você ter escondido isso de mim.",
  [1143563228638464] = "Tive medo que você não me deixasse ficar com ele... e medo que você me repreendesse...",
  [1143563228638208] = "Você disse que odiava coisas sujas... ele está mudando recentemente, deixando cair pó de penas por toda parte, então eu estava ajudando ele a se arrumar no beco...",
  [1143563228637952] = "Me desculpe, eu não deveria ter escondido isso de você... você está com raiva?",
  [1143563228637696] = "Por que você não me contou antes que estava criando um papagaio? Eu pensei que você estava... eu estava morrendo de preocupação!",
  [1143563228637440] = "Então, todos estes dias, as coisas nas tuas roupas estavam...",
  [1143563228637184] = "Mãe?!",
  [1143563228636928] = "Zoé!",
  [1143563228636672] = "Muito bem, querido, você engordou de novo.",
  [1143563228636416] = "Delicioso-",
  [1143563228636160] = "Trouxe algo delicioso hoje... vamos, diga alguma coisa.",
  [1143563228635904] = "Você está com saudades de mim? Hum?",
  [1143563228635392] = "Querido, estou aqui.",
  [1143563228635136] = "...... Bem aqui?",
  [1143563228634624] = "<P_Heart> (Use a navegação com haste radiestesia para encontrar o local de encontro!) </>",
  [1143563228634368] = "Você tem uma maneira de encontrá-la? Olha, ela nem terminou o dever de casa da escola...",
  [1143563228634112] = "Você gostaria de... segui-la e dar uma olhada?",
  [1143563228633856] = "Senhora, não se preocupe. A senhorita Zoe não está em perigo por enquanto e precisamos confirmar os fatos com nossos próprios olhos.",
  [1143563228633600] = "Um encontro secreto?!",
  [1143563228633344] = "......Este é um encontro secreto.",
  [1143563228633088] = "<P_Heart> (Experimente o pêndulo mais comum Adivinhação para um Vidente!) </>",
  [1143563228632832] = "Senhora, não fique ansiosa. Deixe-me fazer um adivinhação para você.",
  [1143563228632576] = "Ela tem apenas quatorze anos. Ela escapou de casa novamente mais cedo e estou muito preocupado. Ela está se associando com algumas pessoas más?",
  [1143563228632320] = "Ela fica dizendo \"querido\" sempre que fala com as amigas... mas não me conta nada quando eu pergunto!",
  [1143563228632064] = "Suas roupas estão sempre cobertas de escamas de pele; Receio que apenas um homem adulto teria flocos tão grandes! Que pessoa imunda!",
  [1143563228631808] = "Meu nome é Jolene e minha filha Zoe está agindo de forma estranha!",
  [1143563228631552] = "Oh Deusa, por favor, você deve tentar!",
  [1143563228631296] = "Eu também sei um pouco sobre adivinhação . Se você não se importa, posso ajudá-lo a dar uma olhada, totalmente gratuito.",
  [1143563228631040] = "Bem-vindo ao Heywood Manor, Sr./Sra. {{PlayerName}}{{|}}. Por favor entre; a bola está prestes a começar.",
  [1143563228630784] = "É necessário re-racionalizar esses pontos suspeitos.",
  [1143563228630528] = "O velho mordomo protege o Barão por instinto; como ele poderia estar usando um Artefato Selado para controlá-lo?",
  [1143563228630272] = "Este tipo de reação instintiva não pode ser falsificada.",
  [1143563228630016] = "Sua reação é real. Ele está realmente protegendo o Barão com sua vida.",
  [1143563228629760] = "Jovem Mestre... contanto que você esteja bem... contanto que você esteja bem...",
  [1143563228629504] = "Ele acenou com a cabeça para Elena agora há pouco... Elena foi arranjada por ele?",
  [1143563228629248] = "A expressão do Barão é muito calma. Alguém que está sendo assassinado, por mais refinado que seja, deveria demonstrar surpresa e raiva.",
  [1143563228628992] = "Ela recuou imediatamente após o ataque sem desferir um golpe final. Não parece um assassinato; é uma performance.",
  [1143563228628736] = "Não há intenção de matar em seus olhos. O grito foi muito deliberado, como se ela estivesse criando pânico intencionalmente.",
  [1143563228628480] = "Deixe-me analisar...",
  [1143563228628224] = "Espere... por que Elena não está fugindo e por que ela está sorrindo enquanto assiste tudo isso?",
  [1143563228627968] = "Você se lembra? Quando eu tinha sete anos, você bloqueou na minha frente assim.",
  [1143563228627712] = "Outra vez?",
  [1143563228627456] = "Sim, estou bem. Você me protegeu mais uma vez.",
  [1143563228627200] = "Jovem Mestre... você está bem?",
  [1143563228626944] = "Ela fez um movimento!",
  [1143563228626688] = "Guilherme, morra!",
  [1143563228626432] = "Não... agora não é a hora. Um espectador não sobe ao palco. Vamos ver o que acontece a seguir.",
  [1143563228626176] = "O velho mordomo está usando \"See Me\"... é ele quem está usando o Artefato Selado para controlar o Barão?",
  [1143563228625920] = "Foi cortado e polido e embutido na armação dos óculos.",
  [1143563228625664] = "Os arquivos dizem que \"See Me\" é um pedaço de cristal transparente. Mas agora, não tem mais a forma de um cristal!",
  [1143563228625408] = "Esse par de óculos... as lentes são de cristal. Não é um cristal comum; há uma flutuação de espiritualidade .",
  [1143563228625152] = "Que baile animado... Vou observar primeiro e ver se há alguma anomalia.",
  [1143563228624896] = "Eu entendo. Este é o significado de eu estar aqui esta noite – para testemunhar tudo isso.",
  [1143563228624640] = "Alguns espectadores perdem o lugar na observação interminável, esquecem-se de si mesmos e perdem a qualificação como testemunhas.",
  [1143563228624384] = "“See Me” origina-se da habilidade Hipnotizador do Espectador Caminho Sequência 6.",
  [1143563228624128] = "Mais importante ainda, como Espectador, somos espectadores e também testemunhas.",
  [1143563228623872] = "Um espectador nunca sobe ao palco. Depois de subir ao palco, você se torna parte do drama e não consegue mais ver a verdade.",
  [1143563228623616] = "Você suspeitou de Albert, você suspeitou de Elena. Mas você não parou na primeira impressão. Você continuou a observar, corrigiu seu julgamento, até ver a verdade.",
  [1143563228623360] = "Sim. Você não tirou conclusões precipitadas.",
  [1143563228623104] = "Porque não tive pressa em agir?",
  [1143563228622848] = "Você é um espectador muito qualificado.",
  [1143563228622336] = "Eu vou. O Artefato Selado precisa ser recuperado. Esta é uma operação legítima de recuperação de um Artefato Selado roubado. O mentor foi eliminado.",
  [1143563228622080] = "{{PlayerName}}, você poderia relatar os acontecimentos desta noite à Igreja com sinceridade?",
  [1143563228621824] = "<P_Heart> (Silêncio por um momento) </> Muito bem.",
  [1143563228621568] = "Assim... seus nomes não serão esquecidos.",
  [1143563228621312] = "Eles deveriam ter um cemitério onde todos pudessem prestar suas homenagens.",
  [1143563228621056] = "Meus camaradas... eles fizeram isso pela família Heywood, por Loen.",
  [818107787014912] = "Godot... quem?",
  [818107787078400] = "Eu admito... fui eu. Fui eu quem assassinou o mestre.",
  [1143563228620288] = "Jovem Mestre... essa terra... não me doe.",
  [818107786911488] = "Esta loja foi aberta por Eleanor e Thomas juntos, já faz décadas.",
  [818107786973952] = "Seus olhos ocasionalmente examinam uma determinada direção – sem olhar para as pessoas, como se confirmassem algo.",
  [1143563228692480] = "Marian sente que seu amor por ela é muito estranho; o que ele precisa não é apenas do seu amor, mas do seu próprio espaço.",
  [1143563228561408] = "Hum? Precisa de algo? Sinto uma aura incomum e grande em você.",
  [1143563228299264] = "Esses idiotas não sabem que não deveriam enterrar as lápides de outras pessoas?",
  [818107786558720] = "Meu noivo pediu ao funcionário da editora que os adicionasse.",
  [1143563229085696] = "Naquela época, Terry estava no período feliz de ser pai e todas as cartas começavam com “Para Olivia”.",
  [1143563228955648] = "Além disso, não compre pão que acabou de sair do forno. O pão que ficou parado por uma noite é um quarto mais barato; corte e toste, tem o mesmo gosto.",
  [1143563228823552] = "Quanto ao motivo pelo qual ela consegue falar, isso se deve a... um pequeno erro, um pequeno erro que todos os donos de cães cometem: esquecer que seu cachorro pode abrir portas.",
  [1143563228807168] = "No dia em que fui convidado para me tornar funcionário civil, a ex-capitã Carol me levou para visitar o Vigias Noturnos 'arsenal, que estava repleto de armas raramente vistas no dia a dia.",
  [1143563228618752] = "Jovem Mestre, então você sabia o tempo todo. Jovem Mestre... me desculpe.",
  [1143563228618496] = "Não tive escolha a não ser organizar um baile para atrair o cérebro por trás dele.",
  [1143563228618240] = "A princípio, pensei que Albert tivesse desenvolvido uma doença relacionada à idade... mais tarde, descobri que ele estava sendo influenciado pelo Artefato Selado.",
  [1143563228617984] = "O mais importante para um Espectador é observar. Quando você estava me observando, eu também estava observando você.",
  [1143563228617728] = "Barão, você sabia que eu era da Igreja o tempo todo? E que Albert tinha o Artefato Selado?",
  [1143563228617472] = "{{PlayerName}}, obrigado por recuperar este Artefato Selado para a Igreja.",
  [1143563228617216] = "Isso não foi culpa sua. É o efeito colateral do Artefato Selado, a conspiração de outra pessoa.",
  [1143563228616960] = "Então comecei a esquecer de você, a esquecer esta casa. Só me lembrei daquela terra. Só me lembrei de querer pegá-lo.",
  [1143563228616704] = "Mais tarde, esqueci os nomes dos meus camaradas. Lembrei-me de querer erguer um monumento, mas esqueci quem eram.",
  [1143563228616448] = "Mas cada vez que os usei, esqueci um pouco. No início, eram apenas pequenas coisas: esquecer o café da manhã, esquecer quem vi ontem.",
  [1143563228616192] = "Aquele par de óculos... quando o encontrei, pensei que fosse um presente da Deusa. Achei que usá-lo faria com que você concordasse \"naturalmente\" em doar o terreno.",
  [1143563228615936] = "Não. Eu sei o que fiz.",
  [1143563228615680] = "Você não esqueceu. Você simplesmente não conseguia se lembrar por um tempo.",
  [1143563228615424] = "Você cresceu tanto... que quase esqueci tudo.",
  [1143563228615168] = "Os nomes dos meus camaradas - Tom, Velho John, o ruivo Billy... o capitão se chamava Herman, que sempre dizia que voltaria para abrir uma padaria depois da guerra...",
  [1143563228614912] = "Jovem Mestre... lembro agora.",
  [1143563228614656] = "Tudo bem. Eu me lembro de tudo.",
  [1143563228614400] = "Esqueci seu aniversário... esqueci que você tinha medo do escuro quando era pequeno, e todas as noites você precisava que eu acendesse uma vela para te acompanhar...",
  [1143563228614144] = "Parece que... esqueci muitas coisas. Lembro-me de querer um pedaço de terra... para meus camaradas... mas esqueci seus nomes...",
  [1143563228613888] = "Alberto, você está bem?",
  [1143563228613632] = "Espectador Caminho , Sequência 5—Andarilho dos Sonhos.",
  [1143563228613376] = "Porque eu também sou um... Espectador.",
  [1143563228613120] = "Você me conhece?",
  [1143563228612864] = "{{PlayerName}}, ajude-me a proteger Albert!",
  [1143563228612608] = "Você... como sua mente está tão clara?",
  [1143563228612352] = "Ouvi dizer que Earl Howard tem um Beyonder animal de estimação. Parece que é você, um Sequência 8, Malandro?",
  [1143563228612096] = "O maior uso de “See Me” é, na verdade, controle!",
  [1143563228611840] = "E daí se você descobrisse? Você já foi 'visto' muitas vezes...",
  [1143563228611584] = "Você estava muito impaciente. O efeito colateral de 'See Me' é a perda de memória. Cada vez que Albert o usa, sua memória diminui. Mas a sua obsessão pelos seus camaradas é demasiado profunda; mesmo que esqueça tudo, ele ainda se lembra de querer aquela terra.",
  [1143563228611328] = "<P_Heart> (Squeak) </> Como você descobriu?",
  [1143563228611072] = "Você ainda não podia esperar.",
  [1143563228610560] = "Guilherme, me obedeça! Obedeça-me!",
  [1143563228610304] = "Sim! Preciso de um cemitério maior para meus camaradas!",
  [1143563228610048] = "Camaradas... cemitério? O mouse está repetindo essas palavras, o que isso significa?",
  [1143563228609792] = "Camaradas... cemitério... camaradas... cemitério... ofereçam o terreno ao meu Senhor...",
  [1143563228609536] = "<P_Heart> (Observe com atenção, mantenha a identidade de um Espectador e evite ser descoberto por ele.) </>",
  [1143563228609280] = "<P_Heart> (Esse rato é um Beyonder!) </>",
  [1143563228609024] = "Ainda bem que não agi agora. Um Espectador... precisa continuar observando para ver o verdadeiro final desta peça.",
  [1143563228608768] = "Por que? O que o mordomo quer fazer? E o que o Barão está fazendo?",
  [1143563228608512] = "Em segundo lugar, o “assassinato” de Elena é falso; é uma performance arranjada pelo Barão.",
  [1143563228608256] = "Primeiro, \"See Me\" está nas mãos do velho mordomo, moldado em um par de óculos.",
  [1143563228608000] = "Reorganizar.",
  [1143563228607744] = "Isso é o resultado de ser controlado por um Artefato Selado? Eu deveria observar o velho mordomo.",
  [1143563228607488] = "O Barão anunciou a doação do terreno. Os convidados dizem que William tem se comportado de maneira anormal recentemente.",
  [1143563228607232] = "Por meio desta anuncio: o terreno no lado leste da Mansão Heywood será doado incondicionalmente ao meu mordomo, Sr.",
  [1143563228606976] = "Convidando todos vocês esta noite, além de compartilhar amizade, há também um assunto importante a anunciar.",
  [1143563228606720] = "Distintos convidados, permitam-me dizer algumas palavras.",
  [1143563228606464] = "Não posso ser precipitado. Frye disse que a coisa mais importante para um Espectador é observar. Vamos esperar mais um pouco.",
  [1143563228606208] = "Sinto que algo está errado...",
  [1143563228605952] = "Terceiro, o comportamento do Barão é rígido, como um fantoche sendo controlado.",
  [1143563228605696] = "Segundo, mulher de cabelos castanhos, anel escondendo uma agulha, discurso emocionado. Assassino?",
  [1143563228605440] = "Primeiro, alguém está prestando atenção especial à psicologia e à memória.",
  [1143563228605184] = "Três anomalias.",
  [1143563228604928] = "Suspiro, confiança é uma coisa boa, mas... você deve pensar nisso devagar!",
  [1143563228604672] = "<P_Heart> (Confuso) </> E os outros? O cachorro do vizinho?",
  [1143563228604416] = "Antes de ser um galã, você é médico, Sr. Hope.",
  [1143563228604160] = "Con... consulta?",
  [1143563228603904] = "Já pensou que ela está olhando para você, talvez só para saber quando é a vez dela da consulta?",
  [1143563228603648] = "Impossível! Ela claramente vem com frequência! E ela continua olhando para mim!",
  [1143563228603392] = "……EM. Margaret não pensa absolutamente nada sobre você; ela está pensando no valor da consulta e no bolo.",
  [1143563228603136] = "Como é? Quanto ela me ama?",
  [1143563228602880] = "Aham!",
  [1143563228602624] = "<P_Heart> (Este Sr./Sra. {{|}} que acabei de conhecer está olhando para mim desde agora, poderia ser—) </>",
  [1143563228602368] = "<P_Heart> (O cachorro do vizinho também latiu para mim a manhã toda, deve querer me seguir, até cachorros como eu.) </>",
  [1143563228602112] = "<P_Heart> (O olhar da Srta. Margaret para mim agora há pouco era muito apaixonado. Suspiro, o fardo do charme.) </>",
  [1143563228601856] = "<P_Heart> (Algo não está certo, vamos entender melhor os pensamentos de Hope.) </>",
  [1143563228601600] = "<P_Heart> (...É isso? Ela não está pensando no médico, então por que o médico acha que ela gosta dele?) </>",
  [1143563228601344] = "<P_Heart> (O bolo daquela loja ontem estava muito bom, vou comê-lo de novo hoje.) </>",
  [1143563228601088] = "<P_Heart> (A taxa de consulta é muito cara, espero melhorar logo.) </>",
  [1143563228600832] = "<P_Heart> (Ela parece apenas uma paciente comum? Deixe-me tentar usar minhas habilidades de Espectador.) </>",
  [1143563228600576] = "Obrigado pela sua preocupação, estou bem.",
  [1143563228600320] = "Senhorita Margaret, parece que você vem a esta clínica com bastante frequência. Sua saúde está bem?",
  [1143563228600064] = "Vou falar com ela primeiro.",
  [1143563228599808] = "Suspirar! Aqui vamos nós outra vez! Não tenho ideia do que fazer!",
  [1143563228599296] = "Primeiro sente-se um pouco, tenho outro paciente aqui.",
  [1143563228599040] = "Como de costume, meu peito está muito apertado, você poderia me dar outra olhada?",
  [1143563228598784] = "Senhorita Margaret, qual parece ser o problema hoje?",
  [1143563228598528] = "<P_Heart> (Esta não é a primeira vez que um paciente confessa a Dra. Hope?) </>",
  [1143563228598272] = "<P_Heart> ('Tom, não consigo responder aos seus sentimentos', 'Senhorita Jessie, não temos futuro'?) </>",
  [1143563228598016] = "Ótimo! Me siga!",
  [1143563228597760] = "Então vou tentar!",
  [1143563228597504] = "Eu sei um pouco sobre psicologia...",
  [1143563228597248] = "Sim, ela deveria vir hoje, talvez você possa conversar com ela?",
  [1143563228596736] = "Você pode me ajudar a testar as águas?",
  [1143563228596480] = "<P_Heart> (Abaixa a voz) </> Suspeito que ela... uh, desenvolveu algum tipo de afeição especial por mim.",
  [1143563228596224] = "Há uma senhorita Margaret que vem à clínica com frequência, duas ou três vezes por semana.",
  [1143563228595968] = "Doutor, parece que você tem algo em mente. Há problemas na clínica?",
  [1143563228595712] = "{{PlayerName}}, tenha cuidado.",
  [1143563228595456] = "Então a resposta é Tingen. Simples, direto - realmente deixa a pessoa nostálgica.",
  [1143563228595200] = "Tingen é pequena – pequena o suficiente para que segredos não possam ser escondidos, e pequena o suficiente para que você possa ver as pessoas que deseja apenas andando alguns passos.",
  [1143563228594944] = "Há. Mas a metrópole é muito grande, as pessoas estão muito distantes umas das outras e todos falam usando máscara.",
  [1143563228594688] = "Tem gente boa em Backlund também, certo?",
  [1143563228594432] = "Em Tingen, quando vou ao mercado comprar cristais brancos, o Velho Lawrence sempre me dá um extra. Em Backlund, se você entrar em uma loja de departamentos vestindo uma túnica preta, os funcionários olharão para você como se tivessem visto um fantasma.",
  [1143563228594176] = "O velho Neil murmurava para si mesmo enquanto lia, Dunn sempre protegia seus companheiros de equipe atrás dele e Frye mantinha a cara séria enquanto secretamente tratava todos com cerveja.",
  [1143563228593920] = "Você quer dizer...",
  [1143563228593664] = "Hehe... tem pessoas que conheço.",
  [1143563228593408] = "Mmhmm, não há como negar que Backlund é uma metrópole — movimentada, cheia de casos diversos e com muitos recursos da Igreja. Mas eu não preciso disso. Tingen tem rio, neblina e ruas tranquilas. E também...",
  [1143563228593152] = "Por que? Backlund é uma metrópole, certamente existem mais oportunidades?",
  [1143563228592896] = "Tingen, é claro.",
  [1143563228592640] = "Sra. Daly, prefere Tingen ou Backlund?",
  [1143563228592384] = "Desperdice bem o seu talento.",
  [1143563228592128] = "E por falar em gênios, acho que você também é um. Um verdadeiro gênio.",
  [1143563228591872] = "Mas não me arrependo. Enquanto estava vivo, usei todas as habilidades que deveria ter usado e tomei toda a vingança que precisava. Comparado com aqueles Beyonders que apenas lutam para sobreviver e não conseguem nada, vivi uma vida que vale a pena ser vivida.",
  [1143563228591616] = "Se eu pudesse ter vivido, talvez já pudesse ter sido um santo.",
  [1143563228591360] = "Isso também não está errado. Só que depois surgiram mais gênios, como Leonard, como Klein. Mas no início eu era de fato considerado o mais inteligente. Eu mesmo percebi o Método de atuação.",
  [1143563228591104] = "Avançar para Sequência 8 em um ano, Sequência 7 em outro e Sequência 6 em três anos - isso é um Beyonder muito talentoso.",
  [1143563228590848] = "<P_Heart> (Risos) </> Eles disseram isso?",
  [1143563228590592] = "Sra. Daly, ouvi dizer que você foi chamada de 'gênio' entre os Vigias Noturnos ?",
  [83769847451136] = "O Louco que não pertence a esta época, o misterioso governante acima da névoa cinzenta, o Rei do Amarelo e do Preto que exerce a boa sorte.",
  [1143563228590336] = "Dunn não se tornou objeto da minha Mediunidade Espiritual, haha... Quando eu soube, seu espírito já havia se dissipado há muito tempo. Não consegui encontrar em lugar nenhum.",
  [1143563228589824] = "Mas há uma coisa feliz.",
  [1143563228589568] = "<P_Heart> (Suavemente) </> Esse sentimento é mais doloroso do que enfrentar qualquer Espírito Maligno.",
  [1143563228589312] = "Às vezes você pode deixar o espírito descansar, mas não pode continuar vivendo. Já vi muita morte, muitas almas se dissipando... No final, até mesmo muitos dos meus ex-companheiros de equipe se tornaram objetos nos quais eu precisava para realizar a Mediunidade Espiritual.",
  [1143563228589056] = "Você pode ouvir as vozes dos falecidos, mas está se tornando cada vez mais difícil ouvir os vivos. Eles temem você, sentindo que você carrega a aura da morte.",
  [1143563228588800] = "<P_Heart> (Silêncio por um momento) </> É solitário.",
  [1143563228588544] = "Qual é a sensação de ser um médium espírita?",
  [1143563228588288] = "O trabalho de um Mentor de Necromancia é comunicar-se com os mortos. Não se trata apenas de invocar almas e adivinhação , mas também de ouvir seus ecos no Mundo Espiritual e enviá-los para um descanso completo.",
  [1143563228588032] = "Alguém que lida com cadáveres todos os dias, ainda tem medo disso?",
  [1143563228587776] = "Você não acha isso assustador?",
  [1143563228587520] = "“Um espírito vagando na falsidade, uma criatura do reino superior dirigida por outros, o mensageiro pertencente exclusivamente a Daly Simone”...... Hehe, você não acha legal?",
  [1143563228587264] = "Não tem sobrancelhas, nem olhos, nem nariz, apenas uma boca, uma língua vermelha brilhante coberta de presas e cinco dedos crescendo na ponta...",
  [1143563228587008] = "<P_Heart> (Risos) </> Você quer dizer aquela língua?",
  [1143563228586752] = "Sra. Daly, você pode me falar sobre seu mensageiro? Ouvi dizer que parece bastante único?",
  [1143563228586496] = "<P_Heart> (Encolhendo os ombros) </> Estou acostumado com isso. Depois de perder minha família aos dezenove anos, fiquei amarrado à morte. Em vez de fingir que ainda posso ser uma pessoa comum, é melhor viver como um Beyonder do Colecionador de Cadáveres Caminho deveria.",
  [1143563228586240] = "Você gosta desse estilo?",
  [1143563228585984] = "Além disso, há uma vantagem em se vestir assim: ninguém se atreve a me atacar casualmente. Aqueles cavalheiros hipócritas veem a sombra azul e as vestes pretas e fazem um desvio, poupando-me muitos problemas.",
  [1143563228585728] = "Bem dito, isso é atuação. O Colecionador de Cadáveres Caminho precisa lidar com a morte e o Mundo Espiritual. Se você se vestir como uma pessoa comum, os mortos não confiarão em você.",
  [1143563228585472] = "Quando Klein me conheceu, ele pensou o mesmo: 'Vestido como um verdadeiro médium espírita, ele está agindo como ele mesmo?'",
  [1143563228585216] = "<P_Heart> (Risos) </> Inteligente.",
  [1143563228584960] = "Você sabe, é que me sinto... um pouco parecido demais com um?",
  [1143563228584704] = "O quê, não parece um médium espírita?",
  [1143563228584448] = "Sra. Daly, por que você sempre se veste assim? Túnicas pretas, sombra azul, correntes de prata...",
  [1143563228584192] = "Vamos deixar por isso mesmo. Isso é tudo que há a dizer.",
  [1143563228583936] = "É uma pena que o próprio cara não soubesse até morrer.",
  [1143563228583680] = "Ele havia me prometido enquanto estava vivo, mas nunca cumpriu. A música naquele dia era muito longa, os passos de dança eram muito lentos... Sempre senti que ele finalmente ouviu as palavras que eu não havia dito em voz alta.",
  [1143563228583424] = "No final... aquela criança Klein se transformou em sua aparência e dançou a última dança comigo.",
  [1143563228583168] = "E no final...",
  [1143563228582912] = "No final, quem foi covarde nunca foi ele.",
  [1143563228582656] = "Eu só usaria essas palavras absurdas para provocá-lo, chamando-o de covarde, chamando-o de antiquado... como se assim pudesse esconder um pouco melhor os pequenos pensamentos em meu coração.",
  [1143563228582400] = "Então você nunca disse nada?",
  [1143563228582144] = "É que naquela época sempre senti que, ao lado dele, ainda estava longe de ser suficiente. Sua limpeza, sua gentileza, aquelas coisas nele que nunca se curvariam — elas me fizeram sentir que alguém como eu estava longe de ser qualificado.",
  [1143563228581888] = "Mais tarde... observei-o cuidar de todos os casos, confortando todos que perderam um ente querido. Ele se lembrou do aniversário de todos no time.",
  [1143563228581632] = "E então o que aconteceu?",
  [1143563228581376] = "Ele sempre dizia naquela época: 'Daly, você tem muito talento'.",
  [1143563228581120] = "Você... não gostou... uh.",
  [1143563228580864] = "<P_Heart> (Levanta as sobrancelhas) </> Meu negócio com ele? Não parece que há muito a dizer.",
  [1143563228580608] = "Lady Daly, posso perguntar sobre você e o capitão Dunn?",
  [1143563228579840] = "Por que sinto vagamente... que o Sr. Emlyn provavelmente vai ficar acordado a noite toda esta noite.",
  [1143563228579584] = "<P_Heart> (Murmurando para si mesmo) </> Eu deveria voltar e tentar também. Talvez com o poder emitido pelo ritual da ‘descida divina’, eu também possa invocar algo bom.",
  [1143563228579072] = "Tosse, ainda tenho que parabenizá-lo. Poucas pessoas podem ser escolhidas por uma criatura tão poderosa do Mundo Espiritual. Louvado seja o Sr. Tolo e valorize a montaria espiritual que você obteve.",
  [1143563228578816] = "Invejoso? Eu, eu só... acho que é realmente muito bom. Comparado com o que eu convoquei antes... é realmente um pouco melhor, sim, só um pouquinho...",
  [1143563228578560] = "Sr. Emlyn, sua expressão... parece de muita inveja.",
  [1143563228578304] = "Suspiro, convocar criaturas do Mundo Espiritual realmente depende do destino.",
  [1143563228577792] = "Depois que todos os materiais para o ritual da “descida divina” estiverem preparados, irei acompanhá-lo para iniciar o ritual e testemunhar o momento milagroso da descida divina.",
  [1143563228577536] = "No entanto, você tem o favor do Sr. Tolo. Completando o ritual sob a proteção e olhar de um Deus poderoso, não haverá problemas.",
  [1143563228577280] = "Então o que devo fazer?",
  [1143563228577024] = "<P_Heart> (Pensando por um momento) </> De modo geral, para criaturas tão poderosas do Mundo Espiritual, é muito fácil falhar.",
  [1143563228576768] = "Hmm... Sr. Emlyn, ainda estou um pouco preocupado. Você disse que ao invocar uma criatura tão poderosa do Mundo Espiritual... haverá problemas?",
  [1143563228576256] = "Sr. Emlyn, onde devo realizar o ritual da 'descida divina'?",
  [1143563228576000] = "Use o ritual de 'descida divina' para orar ao Louco por boa sorte e, em seguida, use o ritual de invocação de criaturas do Mundo Espiritual. O material principal é este contrato divino, mais o material secundário, a poeira estelar do Mundo Espiritual.",
  [1143563228575744] = "O que eu preciso fazer?",
  [1143563228575488] = "Uma montaria, ou talvez seja mais apropriado chamá-la de montaria espiritual. Criaturas amigáveis ​​do Mundo Espiritual podem ser usadas como montarias. Parece que você realmente quer tentar? Como veterano nesse aspecto, não me importo de dar algumas dicas.",
  [1143563228575232] = "Então o que isso pode convocar?",
  [1143563228574976] = "Isso mesmo, sou um Marquês Sanguíneo. Correspondendo ao Sequência 3 Mestre de Invocação, posso trazer criaturas poderosas das profundezas do Mundo Espiritual para o mundo real. Você pode tentar este recado; ainda deve ser utilizável.",
  [1143563228574720] = "Sr. Emlyn já é uma potência de Sequência 3?",
  [1143563228574464] = "Isso mesmo, eu já tenho a força de um Sequência 3. Porém, para criaturas poderosas do Mundo Espiritual como esta, sem a orientação correspondente, mesmo se você tentar milhares e milhares de vezes, você falhará.",
  [1143563228574208] = "Criatura do Mundo Espiritual?",
  [1143563228573952] = "Este é um contrato de convocação para uma criatura do Mundo Espiritual? E é um contrato muito antigo, conectando-se a uma criatura poderosa do Mundo Espiritual, muito além do que você ou eu podemos imaginar.",
  [1143563228573696] = "Eu consegui isso. Você sabe o que é isso?",
  [1143563228573440] = "Hum? Por que existe uma poderosa flutuação de poder de criatura no Mundo Espiritual? O que você está segurando?",
  [1143563228572672] = "…… <P_Heart> (Murmurando baixinho) </> …… Onde diabos você conseguiu os materiais? Eu também quero muito um par de asas assim.",
  [1143563228572416] = "Agora que o ritual acabou e você conseguiu o que queria, eu deveria ir embora também.",
  [1143563228572160] = "Com meu senso estético, eu mentiria para você? Como esperado das asas abençoadas pessoalmente pelo Sr. Louco... a textura é realmente diferente.",
  [1143563228571648] = "...... Como poderia ser tão lindo e requintado? Anteriormente, eu pensava que asas personalizadas de alta qualidade eram perfeitas o suficiente, mas agora elas parecem vulneráveis ​​​​na frente deste par de asas.",
  [1143563228571136] = "<P_Heart> (Olhando para as asas por um longo tempo) </> ...Tsk.",
  [1143563228570624] = "Depois que tudo estiver pronto, irei acompanhá-lo para iniciar o ritual e presenciar o momento milagroso da descida divina.",
  [1143563228569344] = "Na praça da igreja, use o ritual da 'descida divina' para rezar ao Sr. Quando Deus descer com graça e um milagre nascer, seu desejo será realizado.",
  [1143563228569088] = "E então?",
  [1143563228568832] = "A pena do Anjo é o material principal, e a Areia Espiritual Perseguidora do Vento é o material secundário. Para itens rituais, coisas como adagas de prata servem.",
  [1143563228568576] = "Não é de admirar. O Sr. Louco realmente valoriza você, para realmente conceder uma coisa tão preciosa a você... Então, o que você precisa fazer a seguir é preparar os materiais rituais.",
  [1143563228568320] = "Eu queria obter um par de asas.",
  [1143563228568064] = "Mas um item tão precioso geralmente não apareceria do nada. Você orou ao Louco por alguma coisa recentemente?",
  [1143563228567808] = "Uma verdadeira criatura mítica. Quando o Louco dá bênçãos a outros, bênçãos de nível angelical podem aparecer, fazendo com que tais penas caiam.",
  [1143563228567552] = "Anjo?",
  [1143563228567296] = "Isto é uma pena de anjo? ...Não, é uma aura muito além de um anjo.",
  [1143563228567040] = "Pode ser por causa da pena que obtive. Você sabe o que é isso?",
  [1143563228566784] = "Em seus termos humanos, é uma flutuação de poder no nível dos Anjos.",
  [1143563228566528] = "Duque? O que é aquilo?",
  [1143563228566272] = "Hum? Por que sinto vagamente um poder que excede em muito o nível do Duque?",
  [1143563228565504] = "Vamos parar aqui por hoje; Eu deveria ir. <P_Heart> (Murmurando para si mesmo) </> ...Onde ele conseguiu esse tipo de material? Quero um conjunto também.",
  [1143563228565248] = "Agora, é seu. O Sr. Louco concedeu pessoalmente o milagre da descida divina a esta vestimenta. Valorize-o bem.",
  [1143563228564992] = "......Para ser tão lindo e requintado, é completamente incomparável com minhas roupas e acessórios preciosos...... Não, é só um pouco pior...... Tudo bem, é um pouco pior.",
  [1143563228564480] = "Depois que estiver pronto, irei acompanhá-lo para iniciar o ritual e presenciar o momento milagroso da descida divina.",
  [1143563228564224] = "Contudo, devo lembrar-lhe que o ritual da “descida divina” também requer outros materiais; lembre-se de coletar todos eles antes de iniciar o ritual.",
  [1143563228563968] = "Ao realizar o ritual de 'descida divina', você pode coletar o poder daqueles ao seu redor que também acreditam no Louco e, através do ritual, transmitir esse poder de fé ao Sr. Louco para ajudá-lo a estabilizar Sua Âncora.",
  [1143563228563712] = "Seu item não é um objeto comum, então naturalmente o ritual deve ter um nível correspondente. Além disso, sinto vagamente que isso pode ajudar o Sr. Louco a acordar mais cedo do seu sono.",
  [1143563228563456] = "É tão grandioso?",
  [1143563228563200] = "Prepare as oferendas, vá até a praça em frente à Igreja e reze ao Louco. Quando Deus descer com graça e um milagre nascer, seu desejo será realizado.",
  [1143563228562944] = "Lembre-se, como o nível do seu item é muito alto, este pode ser um ritual de “descida divina”.",
  [1143563228562688] = "Então... posso tentar também?",
  [1143563228562432] = "A grandeza de Deus está muito além do que você ou eu podemos imaginar. Certa vez, orei a Ele por uma peça de roupa requintada. Então, Ele respondeu. Essa roupa é exatamente como você viu antes.",
  [1143492898235392] = "Bandido malvado",
  [1143563228561152] = "A comissão da Sra. “Mágica” está completa, eu deveria sair daqui também.",
  [1143563228560896] = "Meu amor, estou indo!",
  [1143563228560640] = "<P_Heart> (Animadamente) </> Vou procurar meu Senhor Vampiro novamente.",
  [1143563228560384] = "Pessoal da igreja... que chato. Não tenho interesse em monges ascetas.",
  [1143563228560128] = "E essa pessoa não é o Duque de Silver Moon, mas um diácono de alto escalão da Igreja da Mãe Terra.",
  [1143563228559872] = "Meu? Como isso é possível!",
  [1143563228559616] = "<P_Heart> (Com raiva) </> Você... você acabou de sair com o duque?",
  [1143563228559360] = "Se ao menos os humanos fossem tão quietos quanto marionetes; é melhor ficar em casa.",
  [1143563228559104] = "Mais um torcedor Sanguine chegou...",
  [1143563228558848] = "O vampiro é apenas um interlúdio; a corrupção da Mãe Terra ainda precisa ser investigada.",
  [1143563228558592] = "Sua investigação chegou ao fim?",
  [1143563228558336] = "Ele está escondido em um dos caixões deste cemitério.",
  [1143563228558080] = "Pedi à Sra. Mágica que encontrasse o manuscrito original, e os vestígios espirituais do assassino ainda permaneciam nele.",
  [1143563228557824] = "Essas criaturas odiosas usam romances para atrair meninas para a morte.",
  [1143563228557568] = "E os vampiros são em sua maioria monstros humanos que sofreram mutações trágicas após consumirem certas poções específicas do 'Boticário' Caminho ; eles são apenas escravos sedentos de sangue.",
  [1143563228557312] = "Os Sanguinários são uma raça antiga nascida do luar; temos nossa própria história, orgulho e modo de vida.",
  [1143563228557056] = "Imitação?",
  [1143563228556800] = "A imitação é repugnantemente desajeitada. Isso não é algo que o Sanguíneo faria.",
  [1143563228556544] = "Ah! Ah! É isso! Coisas como “A Luxúria do Duque da Lua Prateada”, enfeites de prata, rosas espalhadas, pequenos ferimentos no pescoço…",
  [1143563228556288] = "A Sra. “Mágico” me pediu para trazer este livro para você.",
  [1143563228556032] = "Você nasceu sob o olhar dos Clube do Tarô membros, então é claro que eu conheço você.",
  [1143563228555776] = "Senhor “Lua”, você me conhece?",
  [1143563228555520] = "<P_Heart> (Extasiado) </> Ah... a maneira como você fica quando está feroz é ainda mais emocionante!",
  [1143563228555264] = "<P_Heart> (Viciosamente) </> Saia imediatamente, ou você será enterrado aqui para sempre.",
  [1143563228555008] = "Mas você tem a pele como o luar, olhos vermelhos como pedras preciosas...",
  [1143563228554752] = "<P_Heart> (Animadamente) </> Eu não sou um vampiro!",
  [1143563228554496] = "<P_Heart> (Excitado) </> Não consigo ficar calmo. Vendo um vampiro tão poderoso, lindo e frio como você, meu sangue está fervendo.",
  [1143563228554240] = "Senhora, por favor, acalme-se.",
  [1143563228553984] = "<P_Heart> (Obcecado) </> Oh, frio Conde, você vai beijar meu pescoço?",
  [1143563228553728] = "Não. Mas você pode me chamar de Conde.",
  [1143563228553472] = "<P_Heart> (Apaixonado) </> Você é... você é o Duque de Silver Moon?",
  [1143563228553216] = "Talvez você devesse ler o jornal primeiro.",
  [1143563228552960] = "Claro! Lord Vampire e eu definitivamente iremos romper as algemas do mundo e compor uma canção de sangue e amor proibido!",
  [1143563228552704] = "Você quer se casar com um vampiro também?!",
  [1143563228552448] = "<P_Heart> (Corado) </> Então eu posso ter Lord Vampire só para mim!",
  [1143563228552192] = "<P_Heart> (Animadamente) </> Ela se foi, agora sou o único que sobrou!",
  [1143563228551936] = "O que você quer dizer?",
  [1143563228551680] = "Hmph, covardes não merecem ser a noiva do Lorde Vampiro!",
  [1143563228551424] = "Você é realmente uma pessoa sábia e gentil. Deixar uma jovem ver sangue verdadeiro é mais eficaz do que reportagens de assassinato no jornal.",
  [1143563228551168] = "Não se preocupe, isso foi apenas o sangue de matar um pato ontem. Eu só estava assustando eles.",
  [1143563228550912] = "Onde está o sangue?",
  [1143563228550656] = "Eles viram uma poça de sangue sob a treliça de uvas e fugiram com medo.",
  [1143563228550400] = "Posso perguntar para onde foram aquela mãe e filha?",
  [1143563228550144] = "Jovem, você poderia me ajudar <P_Yellow> a rasgar um jornal do quadro de avisos </> para mim? Minha filha só lê romances e não acredita em nada nessas notícias...",
  [1143563228549888] = "Mãe! Não atrapalhe minha felicidade!",
  [1143563228549632] = "Mas já saiu nos jornais que muita gente já foi prejudicada!",
  [1143563228549376] = "Diz a lenda que um belo vampiro assombra este lugar, e muitas garotas vêm aqui na esperança de topar com ele.",
  [1143563228549120] = "Com licença, quem é o vampiro de quem você está falando?",
  [1143563228548864] = "<P_Heart> (Teimosamente) </> Não, eles não vão! Lorde Vampiro só vai me beijar gentilmente; ele não vai me machucar!",
  [1143563228548608] = "Esses romances são todos mentiras; vampiros vão machucar as pessoas!",
  [1143563228547840] = "(Sentindo-se deprimido) Rugido...",
  [1143563228547584] = "Você foi intimidado por isso?",
  [1143563228547328] = "Rugido, rugido, rugido! Rugido, rugido, rugido!",
  [1143563228546816] = "Suspiro, conseguir algumas garrafas de Beyonder poções conta como um ganho. Vamos deixar este lugar primeiro.",
  [1143563228546560] = "Então tudo isso foi apenas uma questão interna do Sanguine?",
  [1130369089365248] = "Tudo bem.",
  [1143563228546304] = "O resto dessas poções é sua. Divirta-se.",
  [1143563228546048] = "Eles não poderão voltar atrás por um tempo, e eu posso continuar pesquisando aquelas poções que ‘desperdiçam talentos’.",
  [1143563228545792] = "Obrigado pela sua ajuda, estranho.",
  [1143563228545536] = "<P_Heart> (Sussurrando) </> Por favor, me ajude a escapar! Eu vou segurá-los, você vai pegar a poção na prateleira!",
  [1143563228545280] = "Você não ouviu esse ditado? Um pássaro enjaulado não tem valor.",
  [1143563228545024] = "O jogo acabou. Para a glória dos Sanguinários, volte comigo. Precisamos do seu talento.",
  [1143563228544768] = "Oros, suas habilidades de esconde-esconde são tão excelentes quanto quando você era criança.",
  [1143563228544512] = "Você os trouxe aqui!",
  [1143563228544256] = "Isso é... Droga!",
  [1143563228544000] = "Espere, que broche?",
  [1143563228543744] = "Hum? Que coincidência, ela tem o mesmo nome que eu.",
  [1143563228543488] = "Oros, este é o broche dela.",
  [1143563228543232] = "...... Que estranho, eu nunca deixo as pessoas passarem a noite, qual é o nome dela?",
  [1143563228542976] = "Na verdade, procuro a filha de um comerciante rico. Ela nunca mais voltou para casa depois de participar do seu chá.",
  [1143563228542720] = "Não se preocupe, desta vez só estou lhe dando chá comum. Você gostaria de alguma sobremesa?",
  [1143563228542464] = "Tosse! Nada! Sente-se rapidamente!",
  [1143563228542208] = "Velhos nevoeiros?",
  [1143563228541952] = "Não consigo parar quando começo a falar sobre poções; aqueles velhos idiotas sempre reclamam que sou barulhento...",
  [1143563228541696] = "Ah, certo, quase esqueci!",
  [1143563228541440] = "Tosse, se bem me lembro, deveria ter a chance de tomar uma bebida com você?",
  [1143563228541184] = "Alguns podem transformá-lo em bolhas, controlar seus próprios sonhos e outros podem até fazer flores.",
  [1143563228540928] = "Eu também fiz várias poções novas! Ajude-me a testar seus efeitos!",
  [1143563228540672] = "Sim, eles são interessantes, não são?",
  [1143563228540416] = "Fazer poções extraordinárias não é simples. A poção que você fez é só para... conseguir entender os gatos?",
  [1143563228540160] = "Então, você é um Beyonder ? Isso é incrível!",
  [1143563228539904] = "O chá que você me fez beber não é realmente um chá, mas uma poção Beyonder, certo?",
  [1143563228539648] = "É um prazer conhecê-lo, anfitrião da festa do chá.",
  [1143563228539392] = "Como você é uma pessoa decente, vou te levar lá! Acompanhe minha figura ágil.",
  [1143563228539136] = "Sim, você está aqui para encontrar o mestre, certo?",
  [1143563228538880] = "......Dentes afiados? Lutando contra o chá?",
  [1143563228538624] = "Só trancam o mestre no quarto para fazer aqueles chás de luta, não deixam nem brincar no jardim!",
  [1143563228538368] = "Nossa, miau, você realmente é um cara legal! Ao contrário daqueles idiotas de dentes afiados.",
  [1143563228537856] = "Dói, miau, estou com dor de barriga, miau.",
  [1143563228537600] = "Talvez a pista para o anfitrião da festa do chá esteja relacionada ao gato?",
  [1143563228537344] = "Posso realmente entender o que os gatos estão dizendo? Esse é o efeito do chá?",
  [1143563228537088] = "Deusa do Miau, sua criatura sem pelos realmente sabe como agradar um gato.",
  [1143563228536832] = "Tosse, é que seu pelo é muito lindo.",
  [1143563228536576] = "O que você está olhando! Que grosseria, continue procurando e eu arrumo um gato para cuidar de você!",
  [1143563228536320] = "...... Um gato? O gato está falando......?",
  [1143563228536064] = "Eu não me importo, miau. Eu só me importo quando o jantar é servido, miau.",
  [1143563228535552] = "Outra alma azarada veio tomar chá.",
  [1143563228535296] = "Ugh, o gosto é tão nojento, o que diabos—",
  [1143563228535040] = "Chá especial... vamos tentar encontrá-lo com Visão Espiritual .",
  [1143563228534784] = "Se eu encontrar o anfitrião da festa do chá, talvez possa perguntar diretamente sobre o paradeiro de Oros?",
  [1143563228534528] = "Pois bem, desejo a todos uma boa noite.",
  [1143563228534272] = "Quem beber aquela xícara terá a oportunidade de tomar um drink com o anfitrião do chá.",
  [1143563228534016] = "As regras são as mesmas de antes: entre todos os chás aqui servidos, há uma xícara especial.",
  [1143563228533760] = "Bem-vindo à Festa do Chá da Meia-Noite. Parece que desta vez há alguns rostos novos.",
  [1143563228533504] = "<P_Heart> (Tente adivinhação com o broche; talvez eu consiga encontrar o local da festa do chá.) </>",
  [1143563228533248] = "Não se preocupe, senhora, talvez eu possa ajudá-la a encontrá-la.",
  [1143563228532992] = "Ela não disse onde foi a festa do chá, apenas deixou este broche para trás.",
  [1143563228532736] = "Existem outras pistas?",
  [1143563228532480] = "<P_Heart> (Chá mágico... parece que envolve um poder extraordinário, vamos dar uma olhada.) </>",
  [1143563228532224] = "Sim, diz-se que o chá que fornecem tem efeitos mágicos, permitindo controlar sonhos, produzir fogo nas palmas das mãos e alguns até permitem ver fantasmas.",
  [1143563228531968] = "Chá da meia-noite?",
  [1143563228531712] = "Meu pobre Oros, ela nunca mais voltou para casa depois de ir ao Chá da Meia-Noite.",
  [1143563228531456] = "Pode me contar o que aconteceu, senhora?",
  [1143563228531200] = "Você está... Minha filha está desaparecida, você a viu?",
  [1143563228530944] = "Deixe isso de lado por enquanto e explore outros lugares. \n <P_Yellow> (Colocado no inventário: Manual do quebra-cabeça da cabana mecânica) </>",
  [1143563228530688] = "Parece estar... registrando alguns quebra-cabeças e soluções. Parece algum tipo de padrão resumido?",
  [1143563228530432] = "Exceto por essas duas páginas, o restante da caligrafia não é muito claro.",
  [1143563228530176] = "O \"Manual do quebra-cabeça da casa mecânica\"? Deixa eu abrir e dar uma olhada...",
  [1143563228529920] = "As portas do Mundo Extraordinário se abrirão ainda mais para você. Lembre-se de permanecer cauteloso.",
  [1143563228529664] = "Por fim, devo parabenizá-lo pelo seu avanço bem-sucedido.",
  [1143563228529152] = "Se aparecer algum sinal de perda de controle – como jargões, dores de cabeça ou instabilidade espiritual – venha me encontrar a qualquer momento.",
  [1143563228528896] = "Vá com calma e adapte-se nos próximos dias; você ficará bem em breve.",
  [1143563228528640] = "Na minha opinião... parece que há novos conhecimentos e novas habilidades...",
  [1143563228528384] = "Felizmente, a sensação desta vez não foi tão ruim quanto antes.",
  [1143563228528128] = "Se necessário, você pode procurar novamente a Psicoterapia da Sra. Justiça.",
  [1143563228527872] = "Eu vi aquele 'eu' de novo...",
  [1143563228527616] = "Tosse, tosse... Aconteceu a mesma coisa de antes...",
  [1143563228527360] = "De acordo com os materiais e medidas da fórmula, primeiro prepare a poção para avançar para a próxima Sequência .",
  [1143563228526848] = "Eles estão todos reunidos. (Sussurrando) Como esperado, quanto maior o Sequência , mais difícil será coletar as fórmulas e materiais...",
  [1143563228526592] = "Hmm, a fórmula e os materiais da poção estão prontos?",
  [1143563228526336] = "Então posso avançar para o próximo Sequência ?",
  [1143563228526080] = "Muito bom, você conseguiu. Louvado seja o tolo.",
  [1143563228525824] = "Naquele momento, minha intuição me disse que a poção havia sido completamente digerida.",
  [1143563228525568] = "Primeiro, houve um som ilusório de quebra, depois senti algo se dissolvendo e lentamente se fundindo com meu espírito...",
  [1143563228525312] = "Essa foi realmente uma sensação estranha; aconteceu de repente.",
  [1143563228524800] = "Já faz um tempo, {{PlayerName}}.",
  [1143563228523520] = "Você está bem preparado, então vamos começar a preparar a poção.",
  [1143563228523264] = "Isso é bom. Lembre-se de restringir sua dissipação espiritualidade . Vamos lá, ainda tem comissões te esperando lá fora.",
  [1143563228523008] = "Muito bom... sinto muito poder surgindo de dentro do meu corpo; Parece que me tornei muito mais forte novamente.",
  [1143563228522752] = "Você está de volta? Como você está se sentindo?",
  [1143563228522496] = "A poção está pronta. Beba e segure-se. Estarei aqui até você acordar.",
  [1143563228522240] = "Bom, então podemos preparar a poção. Relaxe, acredito que você certamente terá sucesso nesse avanço também.",
  [1143563228521984] = "Está tudo pronto, Sr. Leonard.",
  [1143563228521728] = "Além disso, você se saiu melhor do que eu imaginava. Você nunca decepcionou ninguém com as comissões do Blackthorn. Os materiais da poção estão prontos?",
  [1143563228521472] = "Afinal, o avanço não é pouca coisa; o caminho Beyonder é sempre acompanhado de loucura, e estou preocupado que você não consiga lidar com isso sozinho.",
  [1143563228521216] = "Sr. Leonard, você voltou especificamente para isso?",
  [1143563228520960] = "{{PlayerName}}, ouvi dizer que você acumulou mérito suficiente para avançar.",
  [1143563228520704] = "......De qualquer forma, tudo está claro agora. Vamos deixar este lugar.",
  [1143563228520448] = "Esta Cabana Mecânica pode realmente compartilhar a mesma pulsação de seu antigo mestre agora.",
  [1143563228520192] = "Esse manual de quebra-cabeças deve ter sido seu registro dos testes para a ativação gradual da Cabana Mecânica. Felizmente, os dados restantes salvaram minha vida.",
  [1143563228519936] = "Esse amor excessivo acabou se transformando em paranóia... Ele provavelmente perdeu a vida aqui devido à perda de controle.",
  [1143563228519680] = "Parece que minha dedução está correta... Este 'Artesão' Oswald derramou todo seu coração e alma nesta Cabana Mecânica. Ele não poupou nada para torná-lo vivo.",
  [1143563228519424] = "Ufa... felizmente... está tudo bem...",
  [1143563228519168] = "Hmm... por exemplo, começar com esses cadernos?",
  [1143563228518912] = "Minha intuição espiritual me diz que há um problema aqui; talvez eu deva investigar minuciosamente.",
  [1143563228518656] = "Eu ouvi claramente o som de engrenagens girando na porta agora há pouco, mas desapareceu neste momento...",
  [1143563228518400] = "Olhando de perto, a sala está cheia de produtos mecânicos requintados, mas parece que ninguém mora aqui há muito tempo.",
  [1143563228518144] = "Ahem... sinto que tem muita poeira no ar...",
  [1143563228517888] = "Não, o que aconteceu?!",
  [1143563228517632] = "Poderia ser?!",
  [1143563228517376] = "Esse \"isso\" é precisamente...",
  [1143563228517120] = "Aquele que me trouxe os boatos que ouvi, e muito provavelmente, como diz o diário, possui a característica de estar “vivo”...",
  [1143563228516864] = "Aquela que não será vendida, aquela que acompanhará para sempre o “Artesão”.",
  [1143563228516608] = "Deduzindo até este ponto, parece que resta apenas uma resposta...",
  [1143563228516352] = "Sendo assim, resta apenas uma última questão: o que exatamente é “aquilo” que sempre poderia acompanhar Oswald, mas não foi encontrado por mim...",
  [1143563228516096] = "Isso mesmo, não encontrei nenhum e o conteúdo do registro de vendas está todo riscado. Os itens místicos deveriam ter sido todos vendidos.",
  [1143563228515840] = "Mas... sobrou realmente algum item místico nesta sala? Essas evidências parecem sugerir o oposto...",
  [1143563228515584] = "A caligrafia no quadro negro e o fragmento do diário apontam para “isso”. Este é claramente um item místico e que “não será vendido”.",
  [1143563228515328] = "Este “Artesão” claramente tinha uma obsessão importante... pode-se dizer por essas coisas.",
  [1143563228515072] = "Isso mesmo. Um 'artesão' chamado Oswald. Ele era hábil em fazer itens místicos e muitos clientes procuravam comprá-los dele.",
  [1143563228514816] = "Primeiro, o nome e a identidade do proprietário anterior, acho que essas duas coisas explicam isso com bastante clareza...",
  [1143563228514560] = "Acho que entendo um pouco o mistério desta sala...",
  [1143563228514304] = "Ufa... a seguir, preciso organizar meus pensamentos adequadamente. Sinto vagamente que a verdade está bem diante dos meus olhos...",
  [1143563228514048] = "Nada... Procurei em todos os lugares e não há itens místicos nesta sala. \n <P_Yellow> (Obteve uma pista: Nenhum item místico encontrado) </>",
  [1143563228513792] = "Ainda tenho uma hipótese importante que precisa ser verificada.",
  [1143563228513536] = "Depois de verificar cuidadosamente os arredores, encontrei algumas pistas...",
  [1143563228513280] = "Se isso pudesse ser combinado com outras coisas, as coisas deveriam ficar claras... \n <P_Yellow> (Obteve uma pista e colocou-a no Inventário: Carta de Pedido de Item Místico) </>",
  [1143563228513024] = "Esta carta foi enviada ao proprietário anterior? Ainda não é bem certo...",
  [1143563228512768] = "“Artisan”… Este é Sequência 6 do “Savant” Caminho, capaz de criar maravilhas mecânicas e itens místicos.",
  [1143563228512512] = "Uma carta. Vamos abri-lo e dar uma olhada.",
  [1143563228512256] = "Eu me pergunto se 'isso' ainda está aqui... \n <P_Yellow> (Obteve uma pista e colocou-a no Inventário: Fragmento de Diário) </>",
  [1143563228512000] = "Acho que esta também deve ser a chave para resolver o mistério desta casa...",
  [1143563228511744] = "“Isso”...... Parece que esta é a coisa mais importante no coração do antigo dono.",
  [1143563228511488] = "Isto é um pedaço de papel, parece parte de um diário.",
  [1143563228511232] = "Os dados em cada linha foram riscados; muito provavelmente, o dinheiro e os bens já mudaram de mãos há muito tempo. \n <P_Yellow> (Obteve uma pista e colocou-a no Inventário: Registro de Vendas Antigo) </>",
  [1143563228510976] = "Então é isso... Beyonder características e itens místicos relacionados... Parece que este deve ser um recorde de vendas.",
  [1143563228510720] = "Esta é uma lista cheia de nomes e informações de contato... Espere, esta linha é... Característica de Beyonder ?",
  [1143563228510464] = "Parece que o antigo proprietário deste quarto tinha uma obsessão importante. O que... exatamente é \"isso\"? \n <P_Yellow> (Pista obtida: caligrafia no quadro negro) </>",
  [1143563228510208] = "Isso é tudo que pode ser identificado; o resto são apenas notas relacionadas à criação de Beyonder itens.",
  [1143563228509952] = "“...... <P_Yellow> 'Isso' </> nunca poderá ser vendido... nem será perdido.......”",
  [1143563228509696] = "“......Todos os itens místicos combinados não são tão magníficos quanto <P_Yellow> 'isso' </> ...…”",
  [1143563228509440] = "“…… <P_Yellow> É </> …… todo o sangue do coração… é para……”",
  [1143563228509184] = "A caligrafia no quadro-negro já está borrada, mas parte dela ainda pode ser vagamente identificada.",
  [1143563228508928] = "Esses materiais podem ser usados ​​para estabelecer um ritual de purificação.",
  [1143563228508672] = "Um baú de tesouro exalando uma aura sinistra.",
  [1143563228508416] = "Rezo pelo seu favor, rezo para que você purifique a corrupção aqui!",
  [1143563228508160] = "Você é o Rei do Amarelo e do Preto que exerce boa sorte.",
  [1143563228507904] = "Você é o governante misterioso acima da névoa cinzenta...",
  [1143563228507648] = "O Louco que não pertence a esta época...",
  [1143563228503296] = "Obrigado pelo presente, Sra. Audrey!",
  [1143563228503040] = "Esses tesouros agora são seus. Eles não são apenas recompensas materiais, mas também uma prova de seu domínio bem-sucedido de seu primeiro Ritual de Magia. O conhecimento não tem preço, mas o incentivo adequado também é necessário, não é mesmo?",
  [1143563228502784] = "Olha, o selo está quebrado. Você fez um excelente trabalho. Ter tanto sucesso em sua primeira tentativa mostra que sua percepção e controle espirituais são excelentes.",
  [1143563228502528] = "Rezo por seu favor, rezo para que você abra os itens aqui!",
  [1143563228501504] = "Sinta as conexões entre eles e encontre o caminho onde o ponto inicial e o ponto final podem se conectar perfeitamente enquanto atravessam todos os nós. Seu espiritualidade lhe dará dicas, mas lógica e foco são igualmente importantes. Comece quando estiver pronto.",
  [1143563228501248] = "Qualquer repetição ou omissão pode levar ao fracasso do ritual ou até mesmo desencadear uma reação negativa.",
  [1143563228500992] = "Estas áreas representam os nós e caminhos da energia do ritual. O sucesso do ritual depende do guia utilizar o próprio espiritualidade para ativar cada área sem repetição, completando a construção de todo o circuito energético.",
  [1143563228500736] = "Bom trabalho. A Parede de Espiritualidade é formada e o espaço ritual é inicialmente estabilizado. Agora começa o cerne do ritual. Olhe para essas áreas iluminadas.",
  [1143563228500480] = "Concentre sua mente, imagine seu espiritualidade jorrando sob seus pés, espalhando-se para formar uma área fechada que nos abrange, o altar ritual, as oferendas e o baú do tesouro alvo.",
  [1143563228500224] = "Muito bom. A seguir vem a etapa mais crítica: estabelecer um muro de Espiritualidade . Esta parede invisível isolará o interior do exterior, protegendo o ritual de interferências e evitando a dissipação desnecessária do poder interno.",
  [1143563228499968] = "Agora, vá até o altar ritual e configure o Ritual Mágico.",
  [1143563228499712] = "As velas simbolizam a luz de espiritualidade e orientação. A escolha das oferendas deve estar alinhada com o propósito do ritual e as preferências potenciais ou significados simbólicos da entidade que está sendo solicitada. Para quebrar um selo, estes elementos básicos são suficientes.",
  [1143563228499456] = "Primeiro, precisamos estabelecer a base do ritual – o altar e as oferendas.",
  [1143563228499200] = "Um baú de tesouro com um selo simples aplicado nele. Nosso objetivo é quebrá-lo. Este é um ritual de “desbloqueio” perfeito para iniciantes praticarem.",
  [1143563228498944] = "Como este.",
  [1143563228498688] = "Vamos começar com o básico.",
  [1143563228498432] = "aproveitando assim a realidade para alcançar objetivos específicos - seja orar, convocar, selar, adivinhação ou outros.",
  [1143563228498176] = "O núcleo da Magia Ritual reside no uso de procedimentos rituais específicos, símbolos, orações e oferendas para guiar o poder espiritual e construir um campo temporário que esteja em conformidade com certas regras.",
  [1143563228497920] = "Afinal, um ritual que leva à perda de controle pode ter consequências imprevisíveis na realidade.",
  [1143563228497664] = "Sim, um plano relativamente independente da realidade onde espiritualidade é mais ativo. Aprender e praticar Ritual Magic aqui permite uma percepção mais clara do fluxo de energia, e também é relativamente... mais seguro.",
  [1143563228497408] = "Isto é... o Mundo Espiritual? É realmente... incrível.",
  [1143563228497152] = "Por que não... experimentamos isso pessoalmente?",
  [1143563228496896] = "A Magia Ritual é de fato uma disciplina altamente prática. Requer não apenas uma compreensão de símbolos, encantamentos e procedimentos rituais, mas também o uso de espiritualidade para sentir e guiar.",
  [1143563228496640] = "De nada. Compartilhar conhecimento é uma virtude que deve ser mantida no caminho da exploração do misterioso.",
  [1143563228496384] = "Gostaria de perguntar como realizá-los corretamente e garantir sua eficácia e... segurança?",
  [1143563228496128] = "Sra. “Justiça”, desculpe incomodá-la, em relação à Magia Ritual...... Eu li muitos materiais, mas sempre sinto que é apenas conversa fiada, e é difícil compreender verdadeiramente sua essência.",
  [1143563228485376] = "Vista-se de garçom, coloque um pouco de maquiagem... assim Rozanne não deveria ser capaz de me reconhecer.",
  [1143563228483072] = "Espero muito poder testemunhar ela encontrando a felicidade com meus próprios olhos, conhecendo alguém que a acompanhe, um parceiro com quem vale a pena passar a vida toda e, o mais importante, estar com ele pode fazer Rozanne ansiar pela chegada de um novo dia.",
  [1143563228482304] = "Parece que já existe há alguns anos.",
  [1143563228482048] = "Sr. Leonardo?",
  [1143563228481792] = "<P_Heart> (Que neblina espessa, onde estão o Sr. Frye e os outros?) </>",
  [1143563228481536] = "Você-! Não estou mais falando com você!",
  [1143563228481280] = "Então você vai cumprir o compromisso?",
  [1143563228481024] = "É muito melhor do que você quebrar a cabeça e não conseguir inventar um novo poema! Estou falando sério!",
  [1143563228480768] = "E aí, já pensou em um lugar para o seu próximo encontro com Andor? Um restaurante seria um pouco clichê?",
  [1143563228480512] = "Tudo bem, na verdade, olhando para as cartas de pôquer que você deixou bagunçadas, a foto amarelada do grupo na parede e essas xícaras de café, parei de ficar com raiva há muito tempo.",
  [1143563228480256] = "Desculpe, com certeza pediremos sua opinião primeiro no futuro. Você pode nos perdoar desta vez?",
  [1143563228480000] = "Eu não sou mais uma criança. Também pensei muito sobre casamento. Você pode perguntar o que penso com mais frequência; Estou muito disposto a conversar com todos.",
  [1143563228479744] = "Assim como {{PlayerName}} disse, mesmo que fosse um encontro às cegas hoje, você não deveria ter organizado tantos testes absurdos.",
  [1143563228479488] = "Eu sei que você se preocupa comigo, mas a vida às vezes não precisa de “trabalho em equipe”; você não pode tomar decisões por mim.",
  [1143563228479232] = "Rozanne, você ainda está com raiva de nós?",
  [1143563228478976] = "Café acabado de fazer.",
  [1143563228478464] = "O trabalho de arrumação e limpeza de hoje também está feito.",
  [1143563228478208] = "……O que você está fazendo?",
  [1143563228477952] = "Rozanne, você deve estar cansada de andar o dia todo, certo? Sente-se.",
  [1143563228477696] = "Aham! Andor ainda está inconsciente, por que não voltamos primeiro para Blackthorn?",
  [1143563228477440] = "Também sinto muito, Rozanne. Mesmo se você estivesse em um encontro às cegas, não deveríamos ter interferido tanto, muito menos quando foi apenas um mal-entendido...",
  [1143563228477184] = "Tudo bem, Frye, seja um encontro às cegas ou um casamento, é completamente diferente de investigar Beyonder casos.",
  [1143563228476928] = "Desculpe, como capitão, eu deveria ter sido tão rigoroso quanto investigar um incidente Beyonder e esclarecido a verdade primeiro.",
  [1143563228476672] = "Achei que você era apenas tímido, então usou \"um amigo está me procurando\" como desculpa para encobrir...",
  [1143563228476416] = "Já te contei, um amigo tem algo para me procurar, preciso pedir um dia de folga e até escrevi um bilhete de licença para Frye!",
  [1143563228476160] = "Então entendemos mal? E até criamos tantos testes para você...",
  [1143563228475904] = "Você realmente achou que eu perguntaria à outra parte sobre o salário dela tão diretamente em um encontro às cegas!",
  [1143563228475648] = "Ah?! Então foi... procurar emprego? Não admira que você tenha perguntado sobre o salário dele no restaurante!",
  [1143563228475392] = "Ando é apenas o irmão mais novo do meu amigo, querendo encontrar um emprego administrativo em Tingen!",
  [1143563228475136] = "Estou lhe dizendo, vocês são todos grandes idiotas, assim como meu pai!",
  [1143563228474624] = "<P_Heart> (Sussurrando) </> Se você quer me ver feliz com seus próprios olhos, não faça coisas tão perigosas...",
  [1143563228474368] = "Encontro às cegas? Espere, que tipo de carta meu pai deixou para trás! Devo ver desta vez!",
  [1143563228474112] = "Desculpe, Rozanne, erramos por atrapalhar seu encontro às cegas.",
  [1143563228473856] = "Vocês de novo! {{PlayerName}} Você também está brincando com eles! Até o Velho Will estava envolvido nisso!",
  [1143563228473600] = "Eu sou um idiota! Na verdade, eu acreditava que um evento não relacionado ao restaurante poderia oferecer uma refeição grátis!",
  [1143563228473088] = "\"Arranjo\"? Espere, será que tudo hoje foi organizado por vocês de novo?",
  [1143563228472832] = "Acabei de descobrir que houve um incidente Beyonder perto da configuração da \"Casa Assombrada\", então chamei todo mundo.",
  [1143563228472576] = "Como poderia haver um espírito oculto aqui?",
  [1143563228472320] = "(Aqui se conecta a Sequência: Rozanne e Ando correm para a entrada, o morto-vivo chama Rozanne, todos aparecem para ajudar, Leonard hipnotiza Ando)",
  [1143563228472064] = "Você... ok, eu confio em você.",
  [1143563228471808] = "Algo não está certo, acredite em mim.",
  [1143563228471552] = "O que há de errado, Sra. Rozanne...",
  [1143563228471296] = "Andor! Corra, temos que sair pela entrada imediatamente!",
  [1143563228471040] = "A casa mal-assombrada deste evento é muito bem feita. É a primeira vez que vejo espíritos tão realistas; Sinto um arrepio nas costas.",
  [1143563228470784] = "......Morto-vivo?!",
  [1143563228470528] = "......Um erro? O que você quer dizer com... Rozanne está em perigo?!",
  [1143563228470272] = "O misterioso governante acima da névoa cinzenta, o Rei do Amarelo e do Preto que exerce boa sorte.",
  [1143563228470016] = "<P_Heart> (Sr. 'Tolo'?! O casamento de Rozanne realmente precisa ser consultado por um Deus Verdadeiro?!) </>",
  [1143563228469760] = "O tolo que não pertence a esta época—",
  [1143563228469504] = "<P_Heart> (De quem é a opinião do Sr. Leonard ainda precisa perguntar?) </>",
  [1143563228469248] = "<P_Heart> (Sussurrando) </> Não seja tão estúpido; dê-lhes algum tempo sozinhos.",
  [1143563228468992] = "<P_Heart> (Sussurrando) </> E Rozanne e os outros?",
  [1143563228468736] = "<P_Heart> (Sussurrando) </> A propósito, há mais uma opinião para perguntar. Venha me ajudar a me preparar.",
  [1143563228468480] = "<P_Heart> (Sussurrando) </> Tosse, pode ser a orientação da Deusa.",
  [1143563228468224] = "<P_Heart> (Sussurrando) </> O momento é muito coincidente; Pensei que você tivesse voltado especificamente para o encontro às cegas de Rozanne.",
  [1143563228467968] = "<P_Heart> (Sussurrando) </> Estou aqui em Tingen por alguns dias a negócios, como pude perder uma coisa tão interessante?",
  [1143563228467712] = "<P_Heart> (Sussurrando) </> Sr. Leonard? Por que você está aqui?",
  [1143563228467456] = "<P_Heart> (Não necessariamente, esta pode ser a casa mal-assombrada mais autêntica de toda Tingen.) </>",
  [1143563228467200] = "Não se preocupe, Sra. Rozanne, são todas pessoas e adereços disfarçados.",
  [1143563228466944] = "Uma neblina tão pesada... realmente não haveria espíritos aqui, não é?",
  [1143563228466688] = "<P_Heart> (...A aura nesta sala é um pouco estranha?) </>",
  [1143563228466432] = "Passar pela “Casa Assombrada” é o teste final; a saída está escondida no nevoeiro.",
  [1143563228466176] = "É assim mesmo...?",
  [1143563228465920] = "......Talvez você tenha andado na minha carruagem, senhora.",
  [1143563228465664] = "Você parece um pouco familiar. Nós nos conhecemos?",
  [1143563228465408] = "Por favor, leve-nos para a \"Casa Assombrada\".",
  [1143563228465152] = "O motorista da carruagem irá levá-lo ao seu destino. Boa sorte.",
  [1143563228464896] = "Ahem, é uma honra anunciar sua fase final – a Casa Assombrada!",
  [804913646963200] = "O que isso significa?",
  [822505833406208] = "Na verdade, apenas um Deus Verdadeiro pode usar um nome honorífico de três partes. Os nomes honoríficos meus e de outros Clube do Tarô companheiros emprestam o status de Deus Verdadeiro do Sr.",
  [822505833450240] = "Por favor, afaste-se do clamor atual e venha para o meu lado.",
  [1143563228464640] = "Que incrível, Andor! Eu sabia que você conseguiria!",
  [1143563228464384] = "Eu consegui! Sra. Eu consegui!",
  [1143563228464128] = "<P_Heart> (Sussurrando) </> Ufa... domine o ritmo, como encontrar o ritmo de uma máquina de escrever.",
  [1143563228463872] = "Muito obrigado.",
  [822505833021184] = "Esse...",
  [1143563228463616] = "Desde que você tenha coragem de desafiar, a recompensa será mantida, mas a dificuldade não será diminuída. Que tal?",
  [1143563228463360] = "Espere, gostaria de tentar novamente, isso é permitido?",
  [1143563228463104] = "Não se desculpe, só conseguimos passar da fase anterior graças a vocês! Vamos, estamos voltando para o restaurante do Velho Will!",
  [1143563228462848] = "Desculpe, Sra. Rozanne, parece que minha sorte não é boa o suficiente hoje.",
  [1143563228462592] = "O palhaço vence!",
  [804917673610752] = "Concordar",
  [1143563228461824] = "Parece que temos um desafiante. Você poderia se dar ao trabalho de ser o juiz, Guia?",
  [1143563228461568] = "Sra. Rozanne, permita-me aceitar este desafio.",
  [1143563228461312] = "Cuidado, paciência e perseverança são essenciais. Então, quem vai subir no palco?",
  [1143563228461056] = "Chegou a hora do Palhaço subir ao palco? Passe no desafio do malabarismo com a bola e você poderá obter a pista para o próximo nível!",
  [1143563228460800] = "A prova do Palhaço te espera pela frente, que a Deusa te proteja.",
  [1143563228460544] = "O cultivo e a percepção literária são as pontes de comunicação; continue em frente.",
  [1143563228460288] = "Evitando a luz do sol como um eremita.",
  [1143563228460032] = "Nutrida pelo orvalho da noite, a flor da lua desabrocha e se transforma em uma flor elegante e delicada.",
  [1143563228459776] = "Isso mesmo! Essa é a flor da lua!",
  [1143563228459520] = "Flores lunares, nutridas pelo orvalho noturno.",
  [1143563228459264] = "O poema que se segue é...",
  [1143563228459008] = "Este buquê é feito de flores do sono e prímula, e este é de flores do sono e grama com perfume noturno, ambas variedades que a Deusa adora.",
  [1143563228458752] = "Vocês dois têm um buquê escolhido?",
  [1143563228458496] = "Claro! Este é um hino à Deusa.",
  [1143563228458240] = "Você também já ouviu esse poema!",
  [1143563228457984] = "O orvalho adorna a lapela do crepúsculo... ou como estrelas acompanhando a lua.",
  [1143563228457728] = "Sempre que o sol se põe no oeste, o orvalho...",
  [1143563228457472] = "Não vou embora e não posso sair.",
  [1143563228457216] = "Nenhum sofrimento pode me fazer mover.",
  [1143563228456960] = "Há uma missão que me une.",
  [1143563228456704] = "A noite desce ao meu redor.",
  [1143563228456448] = "Meu teste é simples: recite os versos subsequentes do poema e escolha o buquê correspondente, depois peça ao guia que o entregue para mim.",
  [1143563228456192] = "Outro grupo de cordeiros perdidos entrou no meu jardim.",
  [1143563228455936] = "Olá, sou o guia do evento, trazendo eles aqui para participar.",
  [1143563228455680] = "Por favor, sigam-me, vocês dois.",
  [1143563228455424] = "Parece mais simples do que encontrar um emprego esta tarde. Vamos?",
  [1143563228455168] = "Fundos de caridade doados à Catedral de Santa Selena? Isso é ótimo, você está interessado, Ando?",
  [1143563228454912] = "Louvada seja a Deusa, nossa loja agora tem um evento; se você passar no teste, não só será dispensada a refeição de vocês dois, mas também doaremos uma quantia em dinheiro para a Catedral de Santa Selena.",
  [1143563228454656] = "Pense em como levá-los à praça da Catedral de Santa Selena e aceite as demais provas.",
  [1143563228454400] = "Ele parece bem, mas as pessoas sempre se disfarçam intencionalmente ou não em encontros às cegas. Preciso observar mais!",
  [1143563228454144] = "Veste-se adequadamente, fala gentilmente e consegue perceber coisas que Rozanne mencionou de passagem. No geral, ele é cavalheiresco e atencioso.",
  [1143563228453888] = "Ele não parava de falar de trabalho, meio chato, mas devia ser uma pessoa ambiciosa para ainda tentar viver depois de tantos contratempos.",
  [1143563228453632] = "Ufa, felizmente eu não entreguei. Endo, ele...",
  [1143563228453376] = "Ele estava, obrigado.",
  [1143563228453120] = "Sinto muito... Ele deve ter sido uma pessoa cuidadosa e gentil.",
  [1143563228452864] = "......Ele faleceu há alguns anos.",
  [1143563228452608] = "Costumava ser?",
  [1143563228452352] = "Meu pai também trabalhava nesta empresa. Ouvi dizer que ele achava que fazer isso poderia melhorar o relacionamento de todos.",
  [1143563228452096] = "Como você e seus colegas iniciaram o jogo de apostas mencionado anteriormente?",
  [1143563228451840] = "O pudim de limão está aqui, por que não comer alguns doces para clarear a cabeça primeiro?",
  [1143563228451584] = "Ótimo, garçom, por favor, sirva nossa comida!",
  [1143563228451328] = "Não, senhora, por favor, não se preocupe.",
  [1143563228451072] = "Ah, não, venho aqui muitas vezes para comer com os colegas, por isso costumo encomendar com antecedência! E você? Existe alguma coisa que você não pode comer?",
  [1143563228450816] = "Vamos pedir primeiro? Minha irmã disse que o pudim de limão deste restaurante é muito bom. Você tem alguma restrição alimentar?",
  [1143563228450560] = "Olá, Sra. Rozanne, meu nome é Ando, ​​desculpe incomodá-la hoje.",
  [1143563228450304] = "Use o que precisar na loja, basta me avisar se precisar de alguma coisa.",
  [1143563228450048] = "O Capitão Frye já me disse que a pequena Rozanne também atingiu esta idade!",
  [1143563228449792] = "Velho Sr. Will, sou {{PlayerName}} da Blackthorn Security Company, há algumas coisas—",
  [1143563228449536] = "Ah! Rozanne já saiu, devo chegar no restaurante antes dela para me preparar!",
  [1143563228449280] = "Você pode ir primeiro ao restaurante Old Will's e encontrar uma maneira de trazê-los aqui.",
  [1143563228449024] = "Xiga usará um Artefato Selado para ajudar todos a se disfarçarem e evitar que Rozanne nos reconheça.",
  [1143563228448768] = "Planejamos fazer um teste para seu encontro às cegas na praça da Catedral de Santa Selena.",
  [1143563228448512] = "Já que é para o encontro às cegas de Rozanne, há algo em que eu possa ajudar?",
  [1143563228448256] = "<P_Heart> (Na verdade, um candidato a um encontro às cegas pode não ser uma pessoa sincera, eu deveria ir e ficar de olho em Rozanne também.) </>",
  [1143563228448000] = "Os desejos de Rozanne são obviamente os mais importantes, estamos apenas verificando algumas condições básicas para garantir que ele não tenha más intenções.",
  [1143563228447744] = "Vigias Noturnos vindo ao veterinário? Isso é... muito exagerado, não é? Não seria melhor perguntar primeiro o que Rozanne pensa?",
  [1143563228447488] = "Desta vez preparamos um teste na praça para ver se ele tem a capacidade de dar felicidade a Rozanne.",
  [1143563228447232] = "Ela não disse nada, mas eu vi, o local do encontro às cegas é o restaurante Old Will's.",
  [1143563228446976] = "Para ir a um encontro às cegas. Depois que o Sr. Adelaide faleceu, sempre estivemos ao lado dela como família e também examinamos seus candidatos a encontros às cegas.",
  [1143563228446720] = "Então Rozanne estava com tanta pressa para sair agora, não é...?",
  [1143563228444672] = "<P_Heart> (Há outra página, parece haver mensagens de todos?) </>",
  [1143563228444416] = "Ele era o pai de Rozanne, um respeitável Vigia Noturno.",
  [1143563228444160] = "Parece que já se passaram alguns anos. A pessoa que escreveu a carta é... Adelaide?",
  [1143563228443904] = "Vá em frente, abra e você entenderá.",
  [1143563228443648] = "Na mesa.",
  [1143563228443392] = "E aquela carta?",
  [1143563228443136] = "{{PlayerName}}, preciso da sua ajuda em algo, siga-me.",
  [1143563228442880] = "......Onde está Rozanne com tanta pressa de ir?",
  [1143563228442624] = "{{PlayerName}}? Eu tenho que ir, até mais tarde!",
  [1143563228442368] = "Este é o terceiro parágrafo",
  [1143563228442112] = "Este é o segundo parágrafo",
  [1143563228441856] = "Teste o discurso do NPC",
  [1143563228441600] = "Teste a fala do jogador",
  [1143563228438016] = "Você notou que desde que aquela estranha chamada Sylvia chegou, coisas estranhas têm acontecido constantemente!",
  [1143563228437760] = "A profecia poderia estar se tornando realidade? Mas por que?",
  [1143563228437504] = "Especialmente quando está ventando? Droga, pensei que algo estava errado com meus ouvidos!",
  [1143563228437248] = "Também encontrei algo ainda mais assustador. Eu tenho ouvido suspiros vindos do lago recentemente!",
  [1143563228436992] = "Falando nisso, as frutas vermelhas da casa do Jon também se amontoaram em uma montanha...",
  [1143563228436736] = "Todos! Ontem descobri seiva vermelha na quebra de uma árvore de folha dourada. Droga, coisas estranhas têm acontecido cada vez mais ultimamente.",
  [1143563228436224] = "Na verdade, o propósito da minha viagem é resolver este mistério.",
  [1143563228435712] = "Uma misteriosa profecia também circulou na vila de Golden Autumn Lake: 'Quando o suspiro do Santo soar, as mudas douradas acordarão aqui e todas as coisas receberão a desolação.'",
  [1143563228435456] = "Você não sabe? Diz a lenda que o Lago Dourado do Outono recebeu a bênção da terra, por isso está em época de colheita o ano todo. No entanto-",
  [1143563228432384] = "Boa sorte para você também!",
  [1143563228432128] = "Boa sorte para você.",
  [1143563228431872] = "Aqui é assim... já estamos acostumados a conviver com todo tipo de absurdos. Nem todos são maliciosos, são tão comuns quanto tudo na montanha nevada.",
  [1143563228431616] = "Parece que o que você disse é verdade. Hehe, a intuição de nós, caçadores na montanha nevada, sempre foi terrivelmente precisa.",
  [1143563228431360] = "<P_Heart> (O som de um corvo) </> Caw—caw—",
  [1143563228430848] = "Aquele... soldado que você mencionou? Como ele está?",
  [1143492898235136] = "Noite",
  [1143563228430336] = "Está tudo bem?",
  [1143563228430080] = "<P_Heart> (Sua obsessão finalmente se dissipou completamente. Que ele se reúna com seus parceiros no reino de Deus...) </>",
  [1143563228429824] = "Independentemente disso, obrigado. Acho que vou me reunir com eles em breve...",
  [1143563228429312] = "Eu só... de repente não entendo...",
  [1143563228429056] = "Agora, os políticos apertaram as mãos e fizeram a paz, e tudo voltou ao normal. Mas e aqueles que morreram por isso?",
  [1143563228428800] = "Eu cresci em Backlund. Nesse ataque, perdi toda a minha família. O elenco era minha segunda casa, e agora eles também partiram...",
  [1143563228428288] = "Ouvi algumas pessoas dizerem que os dois países finalmente concordaram com uma trégua e regressaram ao estado anterior de relações.",
  [1143563228428032] = "<P_Heart> (Esta guerra parece impossível de discutir simplesmente em termos de vitória ou derrota...) </>",
  [1143563228427776] = "Pessoa gentil, tenho uma última pergunta. Ganhamos no final?",
  [1143563228427520] = "O fraco espiritualidade desse amuleto pode ser suficiente apenas para manter sua existência, mas não pode permitir que pessoas comuns sem Beyonder poderes percebam você.",
  [1143563228427264] = "Mas ninguém me viu. Acontece que eu também já estava morto...",
  [1143563228427008] = "Eu os ouvi falando Loen! Acenei minhas mãos desesperadamente! Achei que poderia salvar todo mundo e voltar para casa juntos...",
  [1143563228426752] = "Acordei de novo e me senti muito leve! Então comecei a correr... Continuei correndo e correndo, até não sentir a passagem do tempo, até não ouvir os bombardeios, até ver gente.",
  [1143563228426496] = "Lentamente, senti o calor ao meu redor.",
  [1143563228425984] = "Velho Nick... não durma...",
  [1143563228425728] = "......Você aprendeu a amarrar os cadarços? Ninguém está aqui para ajudá-lo desta vez... não se deixe enganar......",
  [1143563228425472] = "Você é o mais jovem entre nós, você deve voltar por nós.",
  [1143563228425216] = "...... Pegue, você irá para casa ...... criança.",
  [1143563228424960] = "Por que você... me deu... sua coisa mais preciosa...",
  [1143563228424704] = "Braden, bom filho... pegue isso.",
  [1143563228424192] = "Capitão... tanta fome... tanto frio...",
  [1143563228423936] = "Este era originalmente o Old Nick's.",
  [1143563228423680] = "Finalmente, há isto, o seu amuleto.",
  [1143563228423424] = "Ele era um bom capitão... e deveria ter sido um bom pintor.",
  [1143563228423168] = "Mas pelo menos ele não precisa ficar triste por não poder pintar pelo resto da vida, haha... suspiro...",
  [1143563228422912] = "Foi a primeira vez que o ouvi falar tanto... Mais tarde, sua mão direita foi arrancada por uma bala e ele nunca mais conseguiu segurar uma caneta.",
  [1143563228422656] = "Depois da guerra, pretendo ir para Backlund para ser pintor profissional. Se eu ficar famoso, cobrirei todas as suas despesas com refeições em Backlund; lembre-se de vir me encontrar!",
  [1143563228422400] = "É a taxa de manuscrito do Backlund Post. Enviei os desenhos que fiz para você e eles me deram uma taxa de manuscrito, uma quantia significativa – se não fosse pelo fato de que não posso gastar dinheiro nas montanhas, eu definitivamente lhe ofereceria uma grande refeição!",
  [1143563228421888] = "É o pagamento pelo meu trabalho.",
  [1143563228421632] = "Me desculpe... eu não deveria ter dito isso.",
  [1143563228421376] = "...... Não sobrou ninguém na minha família.",
  [1143563228421120] = "Uma carta de casa? Você é tão sortudo!",
  [1143563228420864] = "……Sim.",
  [1143563228420608] = "Capitão, o que é isso? Uma carta?",
  [1143563228420352] = "Este é o diário de Perry. Ele era o líder do nosso esquadrão. Se ele tivesse chegado em casa em segurança, talvez já fosse pintor.",
  [1143563228420096] = "Também encontrei um diário.",
  [1143563228419840] = "Que ele descanse em paz...",
  [1143563228419584] = "Sim, você está certo, sinto muito por ela. Rico, aquele cara, nunca mais vai pegar coisas emprestadas das pessoas.",
  [1143563228419328] = "Sendo tão mesquinha quanto você, aquela garota é realmente lamentável.",
  [1143563228419072] = "Muito melhor agora! Tilda definitivamente vai gostar. Hehe.",
  [1143563228418816] = "Você não entende, vou me casar quando voltar, então é claro que tenho que estar arrumado.",
  [1143563228418560] = "Não vá muito longe – nós três juntos não temos tantos botões quanto você!",
  [1143563228418304] = "Escondendo coisas de mim? Entregue!",
  [1143563228418048] = "<P_Heart> (Alerta) </> O que você está fazendo?",
  [1143563228417792] = "Você também é um cara que não tem nada. —Ei, Braden, você tem algum botão?",
  [1143563228417536] = "Meu? Minhas roupas estão amarradas com tiras de pano. Encontre um caminho sozinho.",
  [1143563228417280] = "Eu sabia. Velho Nick, você tem algum botão?",
  [1143563228416768] = "Capitão, você tem algum botão?",
  [1143563228416512] = "Rico é um incômodo! Ele não tem nada o dia todo e fica nos pedindo isso e aquilo.",
  [1143563228416256] = "Ah, é a carteira do Rich! Olha essa foto, é a noiva dele em quem ele não parava de pensar.",
  [1143563228416000] = "Eu também encontrei algumas coisas enquanto investigava agora há pouco. Talvez possamos colocá-los juntos. Olhe para esta carteira antiga.",
  [1143563228415744] = "Mas isso não importa. Podemos construir o túmulo aqui, como se todos lhe fizessem companhia.",
  [1143563228415488] = "Mais tarde, nós o enterramos no topo da colina, esperando que ele pudesse ver mais da paisagem nevada que ele adorava. Acontece que tanto tempo se passou e, como esperado, não foi possível encontrá-lo.",
  [1143563228415232] = "O projétil do inimigo foi surpreendentemente preciso naquele momento. Sherwood nunca mais se levantou.",
  [1143563228414720] = "<P_Heart> (Um estrondo alto) </> Boom—",
  [1143563228414464] = "Eu não posso mais lidar com você. Vou voltar para me aquecer perto do fogo.",
  [1143563228414208] = "Ah, não jogue neve no meu pescoço! Vou assistir por mais um tempo. Quando estiver em casa, provavelmente não verei isso pelo resto da minha vida!",
  [1143563228413952] = "Eu irei—hehe, está nevando!",
  [1143563228413440] = "Quem vai lhe ensinar uma lição?",
  [1143563228413184] = "Não importa ele. Esse cara nunca deixou Desi em sua vida. Deixe-o ganhar alguma experiência.",
  [1143563228412928] = "Frio, tão frio! É a primeira vez na minha vida que vou a um lugar tão frio. Meus dentes estão batendo!",
  [1143563228412672] = "Sherwood, economize sua energia. Você não está com frio lá fora?",
  [1143563228412416] = "Quero ver se consigo encontrar o túmulo de Sherwood.",
  [1143563228412160] = "Eu vou te ajudar... espere, onde você está indo?",
  [1143563228411904] = "Todo mundo não pode ficar aqui assim... Quero transformar esse lugar em um cemitério para enterrar todo mundo, e a mim também.",
  [1143563228411648] = "Sinto minhas forças se dissipando... talvez eu desapareça em breve.",
  [1143563228411392] = "eu já morri...",
  [1143563228411136] = "Braden, você... você está aqui.",
  [1143563228410880] = "Você está dizendo que eu já estou morto? Eu morri aqui mesmo?",
  [1143563228410624] = "Não sei, mas você é realmente muito especial. De certa forma, você está mais próximo de um espírito...",
  [1143563228410368] = "A guerra... terminou? Não entendo... mas por que estou aqui? Já ando há três anos?",
  [1143563228410112] = "Isso terminou há três anos.",
  [1143563228409856] = "......Braden, aquela guerra que você mencionou——",
  [1143563228409600] = "É isso mesmo, o Império Feysac lançou um ataque aéreo raide em Backlund, e uma de suas equipes se infiltrou nos subúrbios; nós os perseguimos até a montanha nevada...",
  [1143563228409344] = "Mais importante ainda, você disse que estava lutando contra o exército Feysac?",
  [1143563228409088] = "A carteira muito gasta, o diário que parou há três anos e a neve tão espessa...",
  [1143563228408576] = "Mas essas coisas devem ter acontecido há anos.",
  [1143563228408320] = "É tudo culpa minha, é tudo culpa minha por ter demorado tanto. Eu sou tão inútil!",
  [1143563228408064] = "Acho que sim, e você...",
  [1143563228407808] = "Todos eles morreram... Isso é verdade?",
  [1143563228407552] = "Todo mundo estava morrendo, então fui buscar ajuda. Aí eu te conheci e você me trouxe de volta para o acampamento... Ah, o acampamento! me lembrei agora...",
  [1143563228407296] = "Sou um soldado de Loen, e o esquadrão em que eu fazia parte foi separado da força principal...",
  [1143563228407040] = "Eu, eu...",
  [1143563228406784] = "Não tenha pressa, tente lembrar devagar.",
  [1143563228406528] = "Eu vi, vi os corpos de todo mundo... porque...",
  [1143563228406272] = "Braden, você está se sentindo melhor?",
  [1143563228405760] = "<P_Heart> (Ah, esse amuleto está brilhando!) </>",
  [1143563228405504] = "<P_Heart> (O que ele está procurando?) </>",
  [1143563228405248] = "G-dê para mim...",
  [1143563228404736] = "<P_Heart> (Ele parou... seu estado ainda é muito instável.) </>",
  [1143563228404480] = "Oh não, ele está perdendo o controle. Devo contê-lo primeiro!",
  [1143563228404224] = "Rico... como poderia... não, cheguei tarde demais... não!!",
  [1143563228403968] = "Ah... isso é!",
  [1143563228403712] = "<P_Heart> (Braden... é um corpo espiritual? O que está acontecendo!) </>",
  [1143563228403456] = "Abra Visão Espiritual para observar...",
  [1143563228403200] = "Certo, ele disse que ninguém prestou atenção nele? Pensando bem, aquele caçador também não parecia falar com ele...",
  [1143563228402944] = "As pistas indicam que o acampamento foi destruído anos atrás, mas Braden ainda está claramente pedindo ajuda...",
  [1143563228402688] = "Espere, Braden – a coisa mais estranha aqui é Braden!",
  [1143563228402432] = "Vá e reúna as pistas com Braden...",
  [1143563228402176] = "“Nada é estranho aqui” – o que ele está insinuando?",
  [1143563228401920] = "Nas duas vezes que encontrei aquele caçador, ele parecia querer dizer alguma coisa.",
  [1143563228401664] = "A carteira velha, seja o troco ou as fotos, está desgastada e um tanto frágil, como se ninguém a tocasse há muito tempo; o diário registra apenas a situação desesperadora de perda de suprimentos há três anos.",
  [1143563228401408] = "Quanto tempo levaria para uma mudança tão grande? Além disso, não há sinais do exército Feysac aqui...",
  [1143563228401152] = "O acampamento parece ter sido soterrado pela neve há muito tempo; mesmo Braden não consegue reconhecer o ambiente circundante.",
  [1143563228400896] = "Vamos organizar as informações que temos até agora. O problema é...",
  [1143563228400640] = "Talvez haja pistas por baixo. Vamos limpar isso e ver.",
  [1143563228400384] = "<P_Heart> (O resultado dos adivinhação pontos subterrâneos; o proprietário original do item poderia...) </>",
  [1143563228400128] = "Mas além da neve, não há nada aqui.",
  [1143563228399872] = "A orientação termina aqui. Mas...",
  [1143563228399616] = "Ah... eu quero! O amuleto que o Velho Nick me deu; ele costumava usá-lo o tempo todo.",
  [1143563228399360] = "Não tenha pressa; você tem algum item intimamente relacionado a eles? Talvez eu possa encontrá-los através de adivinhação .",
  [1143563228399104] = "Eu sou tão estúpido! Já nem consigo reconhecer o caminho!",
  [1143563228398848] = "Acho que estou perdido... A neve aqui é muito mais espessa e limpa do que quando cheguei.",
  [1143563228398592] = "Eu vou mostrar o caminho!",
  [1143563228398336] = "Obrigado, vou manter isso em mente. Vamos.",
  [1143563228398080] = "<P_Heart> (Isso... o que significa?) </>",
  [1143563228397824] = "Admiro sua gentileza. No entanto, devo dizer que não há nada de estranho aqui, então você deve ter cuidado.",
  [1143563228397568] = "Salvar vidas é o que importa. Basta levá-los.",
  [1143563228397312] = "Senhor, muito obrigado. Quanto devo a você por isso?",
  [1143563228397056] = "Não é nada. Vá rápido e encontre o que você precisa.",
  [1143563228396288] = "Senhor, agradeço em nome dos meus camaradas!",
  [1143563228396032] = "Os camaradas deste soldado estão presos na montanha e quero enviar-lhes primeiro alguma comida e agasalhos.",
  [1143563228395776] = "Você pode dar uma olhada no meu galpão. O que aconteceu?",
  [1143563228395520] = "Olá, senhor, você tem - ou há algum lugar próximo com comida e itens quentes?",
  [1143563228395008] = "Conheci um caçador agora há pouco; talvez ele não tenha ido longe, vamos perguntar juntos.",
  [1143563228394752] = "Isso, eu também não tenho comida...",
  [1143563228394496] = "Os meus camaradas estão presos nas montanhas, sem comida nem roupas, e estão prestes a morrer. Por favor me ajude, salve meus companheiros, eu realmente não sei o que fazer...",
  [1143563228394240] = "Tempestade, a Tempestade acima, finalmente alguém está disposto a parar!",
  [1143563228393728] = "<P_Heart> (Olhando para o traje dele, ele é um soldado?) </>",
  [1143563228393472] = "<P_Heart> (Esta voz é... alguém pedindo ajuda?) </>",
  [1143563228393216] = "<P_Heart> (Voz fraca) </> Tem alguém aí? Ajuda-",
  [1143563228392960] = "Não vamos falar sobre esses assuntos antigos, Sr./Sra. {{|}}, não deixe que isso afete sua apreciação da paisagem no sopé da montanha.",
  [1143563228392704] = "Tantas pessoas lutaram pelo seu país, mas qual foi o resultado? Os ministros assinaram um acordo de armistício, hmph! Tudo parece uma piada...",
  [1143563228392448] = "Há três anos, quando o mundo inteiro foi arrastado para a guerra, este lugar não foi exceção.",
  [1143563228392192] = "Hornacis... esta terra é inerentemente incomum e, estando na fronteira, é sempre turbulenta. Assim como a guerra de alguns anos atrás...",
  [1143563228391680] = "No entanto, não é surpreendente que isso tenha acontecido nesta montanha nevada.",
  [1143563228391424] = "Caça? Não, estou apenas indo embora. Os corvos são necrófagos sociais; encontrar alguém solitário como esse geralmente não é um bom sinal.",
  [1143563228391168] = "Você está caçando corvos? Isso é realmente raro.",
  [1143563228390912] = "Um tiro ecoou pelas silenciosas planícies nevadas. O corvo não caiu, mas também não voou para longe, como se não tivesse ouvido, olhando em volta no lugar.",
  [1143563228390656] = "Olhe ali.",
  [1143563228390400] = "Senhor, você está...",
  [1143563228390144] = "O Fragmento de Barreira é o símbolo e fonte de poder do Clube do Tarô , e também é a testemunha de Beyonders que se junta oficialmente ao clube para assinar contrato com o Clube do Tarô .",
  [1143563228389888] = "O Sr. “Tolo” usou fragmentos da Barreira como pedra angular para abrir um espaço seguro no Mundo Espiritual, estabelecendo o Clube do Tarô aqui.",
  [1143563228389632] = "Dentro do alcance de seu brilho, os materiais da poção podem estabilizar seu estado e Beyonder criaturas acelerarão seu crescimento.",
  [1143563228389376] = "O Pulse of Life, um dispositivo de cultivo de poções trocado pelo Sr. Moon de dentro do clã Vampiro, foi feito por um antigo alquimista usando a Pedra da Vida.",
  [1143563228389120] = "Esta cidade é dividida em duas partes pelo rio Tasso, que deságua no estuário no sudeste, conectado pela ponte Backlund e balsas. Tem uma população de mais de cinco milhões e é a metrópole mais próspera dos continentes Norte e Sul.",
  [1143563228388864] = "Backlund, a capital do Reino de Loen, é conhecida como a “Terra da Esperança” e a “Cidade das Cidades”.",
  [1143563228388608] = "O “Anjo do Tempo”, Ele serve ao Senhor com Sua carne e sangue, é um crente devoto do Senhor, uma vez serviu ao Senhor com Sua carne e sangue, e o Senhor lhe concede a autoridade do tempo, permitindo-lhe servir ao Senhor por toda a eternidade.",
  [1143563228388352] = "O “Anjo do Castigo”, Ele é o trovão do Senhor, a ira do Senhor, a palma do Senhor, e o Senhor concede-Lhe a autoridade para julgar todos os caídos e impuros em Seu nome.",
  [1143563228388096] = "O “Anjo da Vida”, Ele é o esplendor da sabedoria do Senhor, o imortal espiritualidade dentro de todos, e o presente que o Senhor dá à terra.",
  [1143563228387584] = "O “Anjo da Redenção”, Ele transmite a voz do Senhor ao mundo, o Senhor lhe concede o milagre da ressurreição, e Ele redime a cidade-estado perdida abandonada pelos deuses em nome do Senhor.",
  [1143563228387328] = "O “Anjo da Morte”, Certa vez, caiu na maldição da amnésia, gradualmente se encontrou com a ajuda do Senhor e se tornou as asas do Senhor, desde os tempos antigos até a eternidade.",
  [809242974021632] = "Pequeno babuíno, o que há de errado com você?",
  [1143563228387072] = "O “Anjo de Mercúrio”, é perseguido pelo Ouroboros, renasce ao encontrar o Senhor, salvo pela fé, e assim cumpre o milagre do destino.",
  [1139165182847232] = "Você é o governante misterioso acima da névoa cinzenta",
  [1143563228386816] = "A história abriu um novo capítulo.",
  [1143563228386560] = "A Presidente Bernadette convidou o Sr. Sun, Derrick Berg, do Clube do Tarô, e o sacrificado Chefe da Cidade de Prata, Colin Ilíada, para se juntarem ao Clube do Tarô, servindo como mentores na forma de projeções históricas para ensinar os alunos.",
  [1143563228386304] = "O olhar será lançado do céu estrelado e a terra será dilacerada. A fim de reunir a força de todos para resistir ao apocalipse, o Clube do Tarô foi estabelecido.",
  [1143563228386048] = "Bem-vindo ao mundo de luz prometido por Deus!",
  [1139165182286080] = "Quanto a mim?",
  [1143563228385792] = "Sob a orientação do Louco, o mensageiro divino Danitz levou todos a deixar aquela terra amaldiçoada, cruzar o mar dourado e brilhante e se estabelecer na 'Cidade da Generosidade', Bayam, para reconstruir suas casas.",
  [1143563228385536] = "Abrindo as pesadas portas do grande salão, depois de mil anos, a luz do sol refletiu mais uma vez nos olhos dos moradores da Cidade de Prata.",
  [1139165181860096] = "Eu entendo.",
  [1143563228385280] = "Lamentavelmente, o Chefe Colin Iliad e a Anciã Lovia Tiffany caíram antes do amanhecer.",
  [1143563228385024] = "Ele é o chifre do Senhor, em nome da redenção, trazendo novos alimentos para a Cidade de Prata, trazendo notícias do mundo exterior e liderando o povo da Cidade de Prata a trilhar o caminho para sair da 'Era das Trevas'.",
  [1139165182512384] = "Vou tentar.",
  [1143563228384768] = "O “Tolo” envia seu Abençoado, Gehrman Sparrow, para caminhar pela Terra Abandonada dos Deuses, espalhando o brilho do Senhor e trazendo luz e calor.",
  [1143563228384512] = "A esperança desceu novamente sobre a Cidade de Prata.",
  [1143563228384256] = "O então Chefe da Cidade de Prata, Colin Iliad, realizou uma cerimônia de oração com a ajuda de Derrick Berg. Dentro daquele antigo palácio com vista para a névoa cinzenta e para o Mundo Espiritual, o 'Tolo' respondeu à oração e concedeu uma bênção.",
  [1143563228384000] = "As orações de milhares de anos finalmente receberam resposta, e a grande existência acima da névoa cinzenta lançou seu olhar sobre esta terra perdida.",
  [1143563228383744] = "Geração após geração de pessoas persistiram, esperando que o Criador voltasse a lançar Seu olhar sobre este lugar que Ele havia abandonado.",
  [1143563228383488] = "Desde então, a Cidade de Prata tem sido governada pelo “Conselho dos Seis”, com o mais velho na posição mais alta homenageado como o “Chefe”, e os outros cinco sendo iguais em posição.",
  [1143563228383232] = "Os fortes restantes se reuniram, contando com sua força unida e dois itens mágicos, para resistir aos ataques dos monstros e construir uma cidade-estado que protegesse a última centelha da civilização humana – a Cidade de Prata.",
  [1143563228382976] = "A 'Era Negra' da humanidade havia chegado.",
  [1143563228382720] = "Quando o sol desapareceu do céu, quando as nuvens foram dilaceradas, quando os relâmpagos e os trovões se tornaram os mestres, os monstros escondidos nas profundezas da escuridão apareceram de repente, e as cidades do Reino de Prata foram destruídas uma após a outra…",
  [1143563228382464] = "Durante dois mil quinhentos e oitenta e três anos, as pessoas sombrias abandonadas por Deus viveram sob a maldição do destino.",
  [1143563228341504] = "Como esperado... é uma palavra que não pode ser falada...",
  [1143563228341248] = "Nada aconteceu.",
  [1143563228340992] = "A segunda metade da nota foi queimada e o texto não pode ser totalmente identificado. Só consigo ver que o primeiro caractere é 'Lie', será que...",
  [1143563228340736] = "Talvez tenha ligação com a família real, ou talvez seja um admirador do Conde de Lasting, o que você acha?",
  [1143563228340480] = "Sendo a única loja de departamentos sofisticada em Tingen, nunca soubemos quem é o investidor por trás dela.",
  [1143563228340224] = "Qual é a conexão entre isso e a loja de departamentos?",
  [1143563228339968] = "Nosso grande conde de Lasting sacrificou sua vida nesta guerra e seu nome era Harold.",
  [1143563228339712] = "Essa é a guerra que aconteceu depois da Guerra dos Vinte Anos e antes da Guerra dos Quebradores do Juramento. Isso permitiu que Loen derrotasse Intis e se tornasse forte novamente!",
  [1143563228339456] = "Há muito tempo queria compartilhar essa descoberta com alguém! Você sabe sobre a Guerra das Rosas?",
  [1143563228338944] = "Jovem, você quer saber por que se chama Harold Department Store?",
  [1143563228338688] = "Loja de departamentos Harold...",
  [1143563228338432] = "Esta é a loja de departamentos mais sofisticada de toda Tingen; mesmo quando está fechado, muitas pessoas estão assistindo!",
  [1143563228338176] = "Jovem, você não sabe o que significa Loja de Departamentos Harold?",
  [1143563228337920] = "A loja de departamentos Harold não está aberta, por que ainda há segurança?",
  [1143563228337408] = "Fazer trabalho voluntário pode equilibrar nossas contribuições trabalhistas, e ela e eu não discutimos mais por causa disso.",
  [1143563228337152] = "Como crente na Deusa, não posso ir contra os meus próprios pensamentos de igualdade.",
  [1143563228336896] = "Um crente na Tempestade, hein...",
  [1143563228336640] = "Não entenda mal, não é que ela pense que eu não limpo bem; minha esposa acredita na Tempestade.",
  [1143563228336384] = "Varrendo o chão. Minha esposa não quer que eu faça tarefas domésticas em casa, então só posso sair para fazer trabalho voluntário.",
  [1143563228336128] = "O que significa seguir a igualdade?",
  [1143563228335872] = "Mas para todo o reino, isto já está no caminho do progresso.",
  [1143563228335616] = "Embora limitados por alguns conceitos tradicionais, o seu trabalho é principalmente administrativo e existe um limite invisível para promoção...",
  [1143563228335360] = "Nos ensinamentos da Deusa da Noite Eterna, mulheres e homens têm o mesmo status social. Elas são incentivadas a sair de casa e as mulheres também podem ser policiais.",
  [1143563228335104] = "Todos notaram que há muitas mulheres entre os artistas e patrulheiros da praça? Isso não é comum em outras áreas.",
  [1143563228334848] = "Mas a curiosidade e o entusiasmo que você possui podem ajudá-lo em qualquer momento.",
  [1143563228334592] = "Sinto muito, eu não deveria ter tocado nisso.",
  [1143563228334336] = "Estudar arquitetura é meu sonho, mas infelizmente não passei na prova de desenho.",
  [1143563228334080] = "Você tem um conhecimento profundo de arquitetura; você está neste setor? Ou um estudante deste curso?",
  [1143563228333824] = "As pessoas que os projetaram são muito hábeis no uso de luz e sombra, concentrando a fonte de luz no altar para fazer as pessoas sentirem admiração do fundo do coração.",
  [1143563228333568] = "Estive na Igreja Estrelada e na Catedral de São Samuel em Backlund e é realmente assim.",
  [1143563228333312] = "A noite pertence à Deusa, e a escuridão profunda é a protagonista desta catedral. O estilo consistente da Igreja da Deusa da Noite Eterna é sombrio, silencioso e com poucas velas.",
  [1143563228333056] = "Esta catedral tem um estilo forte da Igreja da Deusa da Noite Eterna; é totalmente preto, com altos campanários, janelas pontiagudas e enormes contrafortes, que são suas características.",
  [1143563228332800] = "Todas elas se deram apelidos: Grande Selena, Pequena Selena, Blue Selena...",
  [1143563228332544] = "Meu Deus, como o professor os distingue?",
  [1143563228332288] = "Tenho cinco colegas de classe chamadas Selena, e suas famílias são todas crentes na Deusa!",
  [1143563228332032] = "Entre as pessoas que acreditam na Deusa da Noite Eterna, Selena também é um nome comum.",
  [1143563228331776] = "Linda senhora, por favor me diga.",
  [1143563228331520] = "Eu sei mais uma coisa!",
  [1143563228331264] = "Este santo está registrado em várias escrituras. Se você leu ‘Revelações da Noite’, certamente conhece esse nome.",
  [1143563228331008] = "Esta é a sede da Igreja da Deusa da Noite Eterna na cidade de Tingen, em homenagem a Santa Selena, uma crente da Deusa que atuou na antiga Terceira Época.",
  [1143563228330752] = "Ainda sou uma pessoa vulgar, ninguém entende a tempestade em meu coração...",
  [1143563228330496] = "Sem motivo, adeus.",
  [1143563228330240] = "Gehrman, o gatinho, Danitz, o cachorrinho, são minhas próprias obras-primas. Ah, pelúcia! Pelúcia elegante! Pelúcia é arte!",
  [1143563228329984] = "Vá direto ao ponto.",
  [1143563228329728] = "Você conhece o Grande Teatro Tingen? Você conhece a Padaria Backlund? Os dois uniram forças para lançar a série de mercadorias ‘Grande Aventureiro’; compre sobremesas e receba presentes de pelúcia!",
  [1143563228329472] = "Onde alguém pode apreciar seu trabalho?",
  [1143563228329216] = "Eu, um grande artista, sentado nesta parede, estou aqui para sentir a brisa da arte e acolher o orvalho romântico.",
  [1143563228328960] = "Muito bem, você é bastante persistente; Eu permito que você conheça minha identidade.",
  [1143563228328448] = "<P_Heart> (Olha para trás sem desviar os olhos.) </>",
  [1143563228328192] = "<P_Heart> (Olhando para você com um olhar minucioso.) </>",
  [1143563228327936] = "Por que você me pergunta por que eu pergunto por que você está sentado na parede?",
  [1143563228327680] = "<P_Heart> (Este ator parece uma máquina de gratidão...) </>",
  [1143563228327168] = "Não, obrigado.",
  [1143563228326912] = "<P_Heart> (Gentilmente) </> Você também precisa de uma assinatura?",
  [1143563228326400] = "Você é meu ator favorito que interpretou Gehrman! Você poderia assinar o pôster para mim?",
  [1143563228326144] = "Obrigado pela sua apreciação.",
  [1143563228325888] = "Mas na verdade somos apenas uma empresa de segurança.",
  [1143563228325632] = "Sua experiência anterior de aventura deve ser muito rica, você não está pensando em reviver uma vida emocionante?",
  [1143563228325376] = "Mas não procuro contratar acompanhantes, procuro um grupo de guarda-costas!",
  [1143563228325120] = "Somos uma empresa de segurança, não uma guilda de aventureiros.",
  [1143563228324864] = "Senhor, já recusamos muitas vezes.",
  [1143563228324608] = "Como ex-esquadrão mercenário, você realmente não está pensando em embarcar em uma aventura comigo?",
  [1143563228324352] = "Tenho um mau pressentimento sobre isso, melhor não.",
  [1143563228324096] = "Não olhe para dentro, Estranho; nem você consegue resistir a tal olhar.",
  [1143563228323840] = "Por que me sinto um pouco tonto?",
  [1143563228323328] = "Adeus, espero que gostem deste Clube.",
  [1143563228323072] = "Não importa, desculpe incomodá-lo.",
  [1143563228322816] = "......É uma pena que Deus não crie a mesma alma duas vezes.",
  [1143563228322560] = "E Klein! Ele é um verdadeiro Vidente! Ele salvou minha vida só de olhar para meu rosto!",
  [1143563228322304] = "Por exemplo, Sr. Haines Vincent; naquela época, as pessoas que faziam fila para pedir um adivinhação podiam ir de Tingen a Backlund!",
  [1143563228322048] = "Pessoas incríveis?",
  [1143563228321792] = "Angélica administra o Clube com muito carinho; se você tiver sorte, poderá até conhecer pessoas incríveis aqui.",
  [1143563228321536] = "Sou membro há vários anos, embora agora só venha sentar-me ocasionalmente por um tempo.",
  [1143563228321280] = "Parece que você conhece este clube muito bem?",
  [1143563228321024] = "Você pode encontrar Riana; ela é uma adivinha muito famosa, bem na Sala do Cristal Branco.",
  [1143563228320768] = "Haha, desculpe, faz muito tempo que não toco adivinhação para outras pessoas.",
  [1143563228320512] = "Quero te pedir um adivinhação .",
  [1143563228320256] = "Ah, olá, há algo em que eu possa ajudá-lo?",
  [1143563228320000] = "Feliz por poder servir.",
  [1143563228319744] = "Tudo bem, vou pensar sobre isso, obrigado.",
  [1143563228319488] = "Obrigado.",
  [1143563228319232] = "Haha, então por que não tomar uma xícara de café?",
  [1143563228318976] = "Estou no lugar errado.",
  [1143563228318720] = "Além disso... talvez você possa até encontrar alguns amigos aqui.",
  [1143563228318464] = "Todos os meses convidamos alguns adivinhos famosos para dar palestras para ajudar todos a aprender adivinhação melhor.",
  [1143563228318208] = "O Clube oferece diversas adivinhação ferramentas e adivinhação salas. Os membros também podem desfrutar de café e chá gratuitamente e comprar refeições, bebidas e alguns adivinhação livros didáticos a preço de custo.",
  [1143563228317952] = "Temos um sistema anual de taxas de adesão: 100 soli para o primeiro ano e 20 soli para cada ano subsequente.",
  [1143563228317696] = "Eu gostaria de aprender mais primeiro.",
  [1143563228317440] = "Você pode dar uma olhada no folheto ao seu lado; contém informações e preços para membros que desejam ajudar nas adivinhações.",
  [1143563228317184] = "Nossos membros podem usar as ferramentas do Clube para realizar adivinhações para outras pessoas gratuitamente.",
  [1143563228316928] = "Eu quero um adivinhação .",
  [1143563228316672] = "Olá Sr./Sra. {{|}}, você está procurando um adivinhação ou quer se juntar ao nosso Clube?",
  [1143563228316416] = "Se eu não tivesse vindo para a Hoy University a negócios, provavelmente não saberia que alguém estava desistindo de sua vaga novamente. Suspirar...",
  [1143563228316160] = "Mas se eles não planejam comparecer à entrevista, deveriam pelo menos nos avisar com antecedência. Esse tipo de comportamento nos causa muitos problemas.",
  [1143563228315904] = "É claro que muitas pessoas também desistem desse caminho depois de encontrar opções melhores.",
  [1143563228315648] = "Você sabe, as universidades de Loen têm uma tradição em que os graduados não permanecem diretamente na escola, então todos os anos os alunos recebem recomendações de seus mentores para entrevistas para cargos de professor em outras universidades.",
  [1143563228315392] = "Sou membro do corpo docente responsável pelo recrutamento na Universidade de Tingen.",
  [1143563228315136] = "O que há de errado, senhor?",
  [1143563228314880] = "Os estudantes hoje em dia realmente não têm boas maneiras.",
  [1143563228314624] = "Adeus, jovem.",
  [1143563228314368] = "Que seus camaradas descansem em paz...",
  [1143563228314112] = "Visitá-los ocasionalmente é a única coisa que posso fazer.",
  [1143563228313856] = "Já não sei se a minha sobrevivência é um golpe de sorte ou uma desgraça.",
  [1143563228313600] = "A guerra pode tirar a vida de centenas de camaradas em poucos minutos... mas o que é mais cruel é que nunca poderei vingá-los ou realizar os desejos que desejam para eles.",
  [1143563228313344] = "Ainda prefiro ficar aqui. O campo é tranquilo e simples... o mais importante é que meus ex-companheiros de armas também estão neste cemitério.",
  [1143563228313088] = "Você não planeja se mudar para a cidade? Seria mais próximo da delegacia e mais conveniente para tratar dos assuntos.",
  [1143563228312832] = "<P_Heart> (Devo dizer que uma vida como essa ainda é muito feliz...) </>",
  [1143492898195712] = "“Sua” ajuda?",
  [1143492898202880] = "Olhe para trás com calma",
  [1143563228312576] = "Recebo meu salário do departamento de polícia e também possuo um terreno que comprei no passado, então tenho uma renda de aluguel estável. Este nível de gastos é bom para mim. No mínimo, essas despesas valem a pena.",
  [1143563228312320] = "Isso... deve custar bastante caro, certo?",
  [1143563228312064] = "A cozinheira, a empregada doméstica e uma lavadeira que vem regularmente ajudam a liberar meu tempo.",
  [1143563228311808] = "A vida está em movimento. Entreguei os assuntos triviais a pessoas especializadas e o tempo restante pode ser usado livremente para exercícios.",
  [1143563228311552] = "É realmente admirável que você ainda possua um físico tão robusto na sua idade.",
  [1143563228311296] = "Você é um verdadeiro cavaleiro.",
  [1143563228311040] = "Espero que você ganhe não apenas as habilidades de um cavaleiro, mas também herde o espírito de um cavaleiro, tornando-se um farol nesta era caótica, usando sua força para iluminar aqueles ao seu redor.",
  [1143563228310784] = "Assim como há mais de vinte anos, nossos Cavaleiros Ahowe não temiam nada e atacaram os invasores da República Intis.",
  [1143563228310528] = "Talvez sejamos de facto os filhos abandonados desta época, mas espero que o espírito do cavaleiro possa ser herdado – insistindo na justiça, sendo sincero e corajoso, protegendo os fracos e defendendo o país.",
  [1143563228310272] = "Porque não quero que percam a herança. Essas habilidades são a base do sustento dos cavaleiros. Não sei se essas habilidades serão perdidas, se o cavalheirismo que aderimos também desaparecerá. Pessoas abandonadas pela época.",
  [1143563228310016] = "Para as pessoas comuns, de fato é. Então por que você ainda nos ensina essas artes tradicionais da cavalaria?",
  [1143563228309760] = "Porque não é mais a nossa era; é sua, e mais ainda, a era da tecnologia. Pense bem: atirar não é mais importante para vocês, policiais, do que o combate corpo a corpo?",
  [1143563228309248] = "Um nobre cavaleiro? Talvez eu estivesse no passado, mas agora somos apenas um monte de antiguidades descartadas pelo tempo.",
  [1143563228308992] = "Ouvi deles que você é um nobre cavaleiro!",
  [1143563228308736] = "Recentemente, o departamento de polícia enviou alguns recém-chegados para aprender o combate.",
  [1143563228308480] = "Adeus. Ah, certo, se você comprar vários itens de uma vez, posso te ajudar a conseguir um desconto!",
  [1143563228308224] = "Bem, parece que há uma divisão de classes mesmo após a morte.",
  [1143563228307968] = "Desculpe, o bairro rico atualmente não está aberto às pessoas comuns. Só estará acessível quando você atingir um determinado status.",
  [1143563228307712] = "<P_Heart> (Olha para você.) </>",
  [1143563228307456] = "Na verdade, estou bastante interessado no bairro rico!",
  [1143563228307200] = "Na verdade, é melhor que o bairro pobre.",
  [1143563228306944] = "Você está comprando um túmulo independente. Não haverá o problema de não conseguir encontrar a lápide depois de um tempo, e temos pessoas que a limpam regularmente.",
  [1143563228306688] = "Tão caro!",
  [1143563228306432] = "O distrito comum varia de 300 a 1000 soli, dependendo da localização específica.",
  [1143563228306176] = "E o distrito comum?",
  [1143563228305920] = "Esse é realmente o caso.",
  [1143563228305664] = "Nos dias de hoje, os pobres não vivem muito.",
  [1143563228305408] = "O bairro pobre tem um espaço tão pequeno, mas enterra a maior parte da população de Tingen; enterrá-los ao acaso tornou-se naturalmente a norma!",
  [1143563228305152] = "Existe tal coisa?",
  [1143563228304896] = "O distrito pobre custa 60 soli por pessoa. Você mesmo pode escolher o terreno, mas não os enterre na beira da estrada.",
  [1143563228304640] = "Bairro pobre?",
  [1143563228304384] = "O Cemitério Rafael pertence à Igreja da Meia Noite, então se você quiser ser enterrado aqui, primeiro você deve ser um crente da Deusa. Metade do custo será doado à Igreja. Você quer o distrito pobre, o distrito rico ou o distrito comum?",
  [1143563228304128] = "Mãe, estamos muito bem em Dici e as crianças são muito obedientes; você não precisa se preocupar. Espero que você encontre paz nos braços da Deusa.",
  [1143563228303872] = "Filhos, deixem o papai ficar sozinho um pouco.",
  [1143563228303616] = "Seu pirralho! Soluço...",
  [1143563228303360] = "Sozinho, vovó!",
  [1143563228303104] = "Vovó, é você?",
  [1143563228302848] = "A vovó sempre cantava: 'Vou virar um gatinho e rastejar até o seu berço'.",
  [1143563228302592] = "Miau-",
  [1143563228302336] = "Um gatinho!",
  [1143563228302080] = "Nick, não chore! A vovó disse que ela odeia mais quando as lágrimas dos outros caem diante de sua lápide. Ela quer que sejamos felizes!",
  [1143563228301824] = "Você disse que viria nos ver, mas mentiu, *soluço*—",
  [1143563228301568] = "Vovó, eu quero muito comer a torta de maçã que você fez.",
  [1143563228301312] = "Você saiu tão de repente; as crianças sempre esperaram vir a Tingen para passar as férias de verão com você.",
  [1143563228301056] = "Mãe, trouxe Sandy e as crianças para ver você.",
  [1143563228300800] = "Obrigado, é uma boa ideia.",
  [1143563228300544] = "Se ainda não conseguir encontrar, talvez você possa perguntar ao coveiro aqui.",
  [1143563228300288] = "Vocês dois parem de discutir; é raro voltar uma vez a Tingen. Por favor, desculpe o espetáculo.",
  [1143492898234624] = "Ajude a perguntar",
  [1143563228299008] = "Na verdade, acumulou-se um pouco mais; a lápide pode ter sido enterrada por outra sujeira de preenchimento.",
  [1143563228298752] = "Olhe com atenção novamente. Quem sabe quantas pessoas novas foram enterradas neste pequeno lugar nos últimos três anos.",
  [1143563228298496] = "Lembro-me de quando viemos para cá, há três anos, era aqui mesmo!",
  [1143563228298240] = "Não conseguimos encontrar a lápide da nossa mãe!",
  [1143563228297984] = "Você teve algum problema?",
  [1143563228297728] = "Tenha um dia agradável!",
  [1143563228297472] = "Estou muito interessado neste assunto; você pode coletar informações e trocá-las comigo!",
  [1143563228297216] = "Porém, você conhece a estátua do primeiro diretor da escola? Ouvi dizer que fazer um desejo muitas vezes se torna realidade...",
  [1143563228296960] = "Ocultismo é meu hobby; Eu posso fazer isso de graça.",
  [1143563228296704] = "Os nós de tempo específicos não contam – você sabe, as aulas de Tarot adivinhação não são tão precisas.",
  [1143563228296448] = "Os resultados amorosos não contam - sei que é com isso que todos estão mais preocupados, mas ainda não resolvi meus próprios problemas, muito menos atuar adivinhação para os outros.",
  [1143563228296192] = "Os resultados dos exames não estão incluídos – não importa se eu prevejo alto ou baixo, isso definitivamente afetará sua mentalidade.",
  [1143563228295936] = "Posso adivinhar qualquer coisa, exceto três coisas.",
  [646721411498752] = "Louvado seja o Louco!",
  [1143563228295680] = "O que você gostaria de saber?",
  [1143563228295424] = "Droga, sinto como se estivesse vivendo à sombra do Imperador Roselle. Por que é que minha inspiração está sempre um passo atrás de seus pensamentos!",
  [1143563228294144] = "Minha querida, escrevi um poema para você.",
  [1143563228293888] = "Olha, amigo! Este é o nosso espírito. Você está convidado a continuar acompanhando o Clube de Remo; vamos derrotar a equipe da Universidade Tingen na competição deste ano!",
  [1143563228293376] = "Dylan, mostre a todos sua especialidade!",
  [1143563228293120] = "A Hoy University sempre valorizou o desenvolvimento integral dos alunos... Vejam os membros da nossa equipe, cada um é saudável e espirituoso. Se você quer estudar acadêmicos, é claro, primeiro você deve ter um físico forte!",
  [1143563228292864] = "Sem condições nenhumas, desde que adore este desporto! Este é Hudson, este é Dylan. Eles vêm de origens completamente diferentes, mas a nossa equipe de remo trata todos igualmente!",
  [1143563228292608] = "Haha, adoraria conhecer esse senhor se tiver oportunidade!",
  [1143563228292352] = "Era um instrutor chamado Azik. Estávamos muito próximos. Já faz muito tempo desde a última vez que nos falamos; Eu me pergunto como ele está.",
  [1143563228292096] = "Você chegou atrasado; isso foi há alguns anos.",
  [1143563228291840] = "Oh? Havia um oponente no mesmo nível que você, professor?",
  [1143563228291584] = "Há muito tempo atrás, havia um cara que sempre discutia comigo até ficar com o rosto vermelho... Essa é uma memória distante agora.",
  [1143563228291328] = "O professor Cohen é muito rigoroso academicamente e fico muito feliz em conversar com ele sobre minhas ideias.",
  [1143563228291072] = "Debate? Haha, sou só eu trocando algumas pesquisas com meu aluno; não se qualifica exatamente como um debate.",
  [1143563228290816] = "Olá. Eu estava de passagem e ouvi o seu debate; parecia muito interessante.",
  [1143563228290560] = "Olá, jovem. Vejo que você está aqui há algum tempo; você gostaria de participar da discussão?",
  [1143563228290304] = "<P_Heart> (O que eles estão discutindo?) </>",
  [1143563228290048] = "No entanto, sua sugestão tem algum valor. Vou propor isso a eles.",
  [1143563228289792] = "Aston, acredito que você entende que a Igreja tem sua própria postura. É muito difícil filtrar isso...",
  [1143563228289536] = "Mas professor, apenas os clássicos da igreja contêm mais registros sobre a Guerra dos Quatro Imperadores. Encontrar verdades comuns na literatura pode ser mais provável...",
  [1143563228289280] = "Há muita incerteza em relação à história da Quarta Época. Você deve começar sua pesquisa a partir de relíquias existentes para eliminar fatores incertos.",
  [1143563228289024] = "O efeito colateral é que depois que o usuário entra no espaço do loop, um quebra-cabeça mecânico aleatório aparecerá em sua mão a cada ciclo. Deve ser resolvido dentro de um tempo limitado, ou o usuário será devorado e transformado em um quebra-cabeça mecânico totalmente novo.",
  [1143563228288768] = "Enterro elaborado com limite de palavras",
  [1143563228288512] = "Tira de Mobius, também conhecida como \"Endless Lost Path\". Um papel retangular de folha de ouro feito com artesanato especial, uma extremidade é torcida 180 graus e depois conectada à outra extremidade, formando um anel com apenas um plano.",
  [1143563228288256] = "Está tudo bem. Não importa quando, estou sempre disposto a apresentá-lo ao meu Senhor, o grande Sr.",
  [1143563228288000] = "Alto escalão, mas filantrópico e de mente aberta. Louvado seja meu Senhor!",
  [1143563228287744] = "Ele se preocupa com todos os seres vivos, mesmo que você não acredite em \"O Louco\", você ainda pode aproveitar tudo do Clube do Tarô .",
  [1143563228287488] = "Meu Senhor não forçará as pessoas a se converterem, nem se importa se a fé for pura. Simplificando, ele não se importa se as pessoas acreditam nele enquanto acreditam em outros deuses.",
  [1143563228287232] = "O Sr. “Tolo” é misericordioso e compassivo, o salvador deste mundo, mas ele nos permite tratá-lo como “ele” em vez de “Ele”.",
  [1143563228286976] = "O Sr. “Tolo” é um Deus verdadeiro reconhecido por todas as igrejas, e o sucesso da construção do Clube do Tarô também se deve à sua ajuda.",
  [1143563228286720] = "Meu Senhor salvou a cidade-estado perdida abandonada pelos deuses, conduziu os sobreviventes daquele continente para fora da “Terra Abandonada dos Deuses” e reconstruiu sua casa na ilha…",
  [1143563228286464] = "O “Anjo do Tempo”, Ele é um Anjo dos tempos antigos que eventualmente se submeteu ao meu Senhor e toca o sino do Reino dos Céus para Ele.",
  [1143563228286208] = "O “Anjo do Castigo”, Ele é o trovão do Senhor, a ira do Senhor, a palma do Senhor, e o juiz e executor de todos os caídos e impuros.",
  [1143563228285952] = "O “Anjo da Vida” é a cristalização da sabedoria e do imortal espiritualidade dentro de todos.",
  [1143563228285696] = "O “Anjo da Redenção” é o chifre do meu Senhor e o mensageiro do oráculo divino.",
  [1143563228285440] = "O “Anjo da Morte” é a existência que mais tempo segue meu Senhor e é o administrador do Submundo.",
  [1143492898234368] = "Confirme o roteiro",
  [1143563228284928] = "Meu Senhor habita acima da realidade e do Mundo Espiritual, sua misericórdia enche os céus e a terra, e há seis Anjos ao seu lado...",
  [1143492898243328] = "Quando o nome será atualizado?",
  [1143492898243072] = "Guerra?",
  [1143492898242560] = "Em algum lugar mais perto?",
  [1143492898242048] = "Como faço para exibir meu nome nele?",
