  [1143492898238976] = "Narrar a interpretação astrológica",
  [1143492898238720] = "Erro de interpretação?",
  [1143492898238464] = "Deixe-me dar uma olhada para você",
  [1143492898238208] = "Abra outro pacote",
  [1143492898237952] = "Como você sabe de tudo isso?",
  [1143492898237696] = "Eu não vou denunciar você",
  [1143492898237440] = "Eu também sou um estranho",
