  [1143492898236416] = "Crepúsculo",
  [1143492898236160] = "Adivinho que perdeu cartas de Tarô",
  [1143492898235904] = "Manhã ofuscante",
  [1143563228692736] = "Você está dizendo que meu gato não me ama e que tudo era apenas eu delirando ?!",
  [1143563228561664] = "Pode ser por causa deste item. Quero usá-lo para fazer uma nova peça de roupa. Já vi que você possui muitas roupas requintadas; eles foram feitos sob medida em uma boutique de moda sofisticada?",
  [1143563228430592] = "Está tudo bem, senhor. É uma pena que tudo isso não tenha sido usado no final. Devolvendo para você.",
  [1143563228299520] = "Qual é a utilidade de chamar os outros de idiotas? Você não deveria pensar por que não escolheu um terreno de tamanho médio para sua mãe?",
  [1143563228285184] = "O “Anjo de Mercúrio” é o avatar do destino e é o anjo que meu Senhor mais favorece.",
  [1143563229085952] = "Mais o retrato que desenhei de uma Olivia adulta na minha imaginação... ah, as mães sempre imaginam que suas filhas são mais bonitas que elas.",
  [1143563228954880] = "Há uma barraca de frutas no final da Iron Cross Street; vá depois das seis da tarde. O dono tem pressa em fechar e você pode comprar uma sacola grande por um sol.",
  [1143563228823808] = "No dia em que preparei a poção, Susie abriu a porta e entrou no laboratório, lambendo uma porção da poção do Espectador. Felizmente, preparei dois conjuntos de materiais na época.",
  [1143563228807424] = "Ela me disse que essas coisas não foram feitas para lidar com criminosos comuns.",
