  [1143492898196736] = "Distrito pobre",
  [1143492898196480] = "É isso por enquanto",
  [1143492898196224] = "Quanto por sessão?",
  [1143492898195968] = "O que você pode adivinhar?",
  [1139094851821056] = "O tolo que não pertence a esta época",
  [1139094851802368] = "O que?",
  [1130298758700032] = "O que é?",
  [1147890944710912] = "O que está errado?",
  [818107787030528] = "Vá em frente, meu verdadeiro amor é... *ronco*, *bufo*...",
  [818107787030272] = "Suspiro, devo encontrar seu verdadeiro amor então?",
  [818107787030016] = "Você faz perguntas muito complicadas. Você não é muito bom em conversar.",
  [818107787029760] = "Você chama sua própria noiva de bruxa?",
  [818107787029504] = "Amanhã é o dia do meu casamento, e Emilia, minha linda noiva bruxa, certamente ficará com raiva de novo...",
  [818107787017984] = "Devemos esperar por Godot.",
  [818107787017728] = "Não podemos. Não vamos a lugar nenhum.",
  [818107787017472] = "Por que você não pode partir sozinho?",
  [818107787017216] = "Talvez. Ontem, hoje, amanhã – não tenho acompanhado.",
  [818107787016960] = "...... Você está esperando há muito tempo?",
  [818107787016704] = "Esperando por Godot juntos.",
  [818107787016448] = "E então, nos reunimos aqui.",
  [818107787016192] = "Ficamos muito tentados e concordamos em viajar juntos.",
  [818107787015936] = "Ele disse que o trem em Backlund é muito longo e você pode ir até a Montanha Nevada.",
  [818107787015680] = "Ele disse que Tingen tem um distrito universitário e que você pode voar acima das nuvens em uma aeronave.",
  [818107787015424] = "Ele disse que o mundo exterior é muito grande.",
  [818107786978304] = "<P_Heart> (Eles estão incomodando aquela garota? Suba e ajude-a!) </>",
  [818107786974464] = "Hum? Nada. Algo está errado, tente ativar Visão Espiritual .",
  [818107786949888] = "<P_Heart> (Ele está fingindo ser um cogumelo!) </>",
  [818107786949632] = "<P_Heart> (Seus globos oculares estão se movendo ligeiramente; ele está pensando em algo e está muito lúcido.) </>",
  [818107786949376] = "<P_Heart> (Deixe-me ver, ele está segurando a cabeça com as duas mãos, o queixo enterrado nos joelhos, como se estivesse resistindo ao mundo exterior.) </>",
  [818107786949120] = "<P_Heart> (Ele parou de falar...) </>",
  [818107786948864] = "Um cogumelo?",
  [818107786948608] = "Eu sou um cogumelo.",
  [818107786913280] = "Todos sentimos pena dela, mas o que podemos dizer? Contanto que ela esteja feliz.",
  [818107786913024] = "Agora ela sempre diz que Thomas ainda está aqui, sentado ao lado dela. Às vezes ela até serve cerveja para o lugar vazio, dizendo que Thomas adora essa bebida...",
  [818107786912768] = "Suspiro, depois que Thomas faleceu, o cabelo de Eleanor ficou grisalho durante a noite.",
  [818107786912512] = "Então agora...",
  [818107786912256] = "Thomas adorava contar piadas, e Eleanor ria atrás do balcão, sem conseguir nem segurar o copo na mão... tsk tsk, naquela hora era tão bom.",
  [818107786912000] = "Todos os dias, de manhã à noite, a loja ficava lotada de gente e as risadas podiam ser ouvidas de uma ponta à outra.",
  [818107786658048] = "A melhor lembrança da cidade de Lamud! Sr./Sra. {{|}}, esta é a melhor opção para escolher presentes para sua família e amigos!",
  [818107786561280] = "Se você encontrar alguma pista relevante, por favor, me diga. Claro, pagarei uma recompensa generosa.",
  [818107786560768] = "O que esta profecia significa?",
  [818107786560000] = "Qual é a “Profecia Misteriosa do Lago Dourado do Outono” que você acabou de mencionar?",
  [818107786559744] = "Cyril, me dê mais tempo... Tudo bem, não decepcione a paisagem do Golden Autumn Lake, vamos esquecer temporariamente tudo em Backlund.",
  [818107786559488] = "Eloise, deixe-o, ok? Ele não entende você de jeito nenhum; ele só quer uma máquina obediente.",
  [818107786559232] = "Ah, então ele deveria trabalhar na corte de Backlund, e não herdar uma editora.",
  [818107786558976] = "Ele sempre diz que a pontuação deve ser tão rigorosa quanto um contrato de casamento.",
  [813709740047616] = "Por que?",
  [813709740039936] = "Por que você diz isso?",
  [813709739988224] = "Adeus.",
  [809242974039808] = "Galhos e folhas formam passos suaves, deixando-me caminhar em direção ao longo sono no fundo da água...",
  [809242974039552] = "Os ovos fritos deste lugar são os melhores...",
  [809242974039296] = "Quando Gila vai voltar...",
  [809242974022656] = "Venha, assim, deixe-me te ensinar a lutar!",
  [804913646966784] = "Realmente?",
  [519041161376256] = "O tempo está muito ruim, uma nevasca com certeza chegará em meia hora!",
  [519041161374464] = "Por que não podemos?",
  [519041160888064] = "Minha querida, por que me lembro que o Imperador Roselle escreveu o mesmo poema?",
  [519041160887808] = "“Cansado, sentado na beira da estrada, tirando este livro…”",
  [519041160887552] = "“Quando você estiver velho, grisalho e cheio de sono.”",
  [360778595143680] = "Rozanne voltou a falar recentemente; ela tem treinado muito bem o novo funcionário.",
  [360778595143424] = "Rozanne ficou obcecada em preparar café, dizendo que quer preparar o mesmo sabor que o Velho Neil.",
  [360778595143168] = "Em vez de satisfazer os requisitos, ela precisa de alguém que possa entendê-la ao seu lado.",
  [360778595142912] = "Rozanne terá um bom marido que poderá acompanhá-la e satisfazer todas as suas necessidades, do tipo que pode até tomar café com pimenta!",
  [360778595142656] = "Ela tem reclamado de turnos noturnos e problemas de pele ultimamente; ela deve encontrar um colega que possa alternar os turnos com ela.",
  [360778595142400] = "Hoje Rozanne ficou amiga de uma garota que veio fazer um pedido, e eles até marcaram para fazer compras no dia de folga.",
  [360778595142144] = "Não se preocupe, Rozanne é uma garota extrovertida; ela não estará sozinha.",
  [360778595141888] = "Se algo acontecer comigo, espero que todos possam ajudar a cuidar da minha filha e a proteger sua felicidade.",
  [360778595141120] = "Como Vigia Noturno guardando Tingen, não posso ir para casa na hora todos os dias para contar suas histórias de dormir, só posso rezar para a Deusa, desejando-lhe um bom sonho.",
}
